BEGIN TRANSACTION;
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1, 'Unparalleled', 'adj', 'Vô song / Không gì sánh bằng', 'Studying abroad gives young people an unparalleled opportunity to learn new languages and experience different cultures.', 'Unit 2: Mental and Physical Development');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (2, 'Memorize', 'v', 'Ghi nhớ / Học thuộc lòng', 'Students should understand the main ideas instead of trying to memorize every single fact for their exams.', 'Unit 2: Mental and Physical Development');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (3, 'Adolescence', 'n', 'Tuổi thiếu niên / Thời kỳ vị thành niên', 'During adolescence, teenagers experience many emotional changes and try to become more independent from their parents.', 'Unit 1: Growing Up');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (4, 'Adulthood', 'n', 'Tuổi trưởng thành', 'Entering adulthood brings important responsibilities, such as managing personal finances and building an independent career.', 'Unit 1: Growing Up');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (5, 'Bond', 'n', 'Mối quan hệ gắn kết / Tình cảm gắn bó', 'Sharing meals together every evening helps family members build a strong emotional bond with one another.', 'Unit 1: Growing Up');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (6, 'Brotherhood', 'n', 'Tình anh em / Tình huynh đệ', 'Playing sports together helps young men develop a strong sense of brotherhood and teamwork.', 'Unit 1: Growing Up');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (7, 'Character', 'n', 'Tính cách / Phẩm chất', 'Voluntary work helps students build strong character and learn how to help other people in need.', 'Unit 1: Growing Up');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (8, 'Childhood', 'n', 'Thời thơ ấu / Tuổi thơ', 'A happy childhood full of outdoor activities can positively affect a person''s mental health later in life.', 'Unit 1: Growing Up');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (9, 'Conflict', 'n', 'Sự xung đột / Mâu thuẫn', 'Open communication is the best way to resolve conflict between parents and their teenage children.', 'Unit 1: Growing Up');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (10, 'Connection', 'n', 'Mối quan hệ / Sự kết nối', 'Social media helps people maintain a close connection with friends who live in different countries.', 'Unit 1: Growing Up');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (11, 'Fatherhood', 'n', 'Thiên chức làm cha / Cương vị làm cha', 'Modern fatherhood involves spending more quality time at home caring for and educating young children.', 'Unit 1: Growing Up');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (12, 'Friendship', 'n', 'Tình bạn', 'True friendship is based on mutual trust, honesty, and support during difficult moments in life.', 'Unit 1: Growing Up');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (13, 'Instinct', 'n', 'Bản năng', 'When danger appears suddenly, a person''s natural instinct is to protect themselves and their family.', 'Unit 1: Growing Up');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (14, 'Interaction', 'n', 'Sự tương tác', 'Regular face-to-face interaction with teachers helps students understand difficult lessons much faster and better.', 'Unit 1: Growing Up');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (15, 'Motherhood', 'n', 'Thiên chức làm mẹ / Tình mẫu tử', 'Balancing the demands of motherhood with a full-time career can be challenging for many modern women.', 'Unit 1: Growing Up');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (16, 'Nature', 'n', 'Bản chất / Thiên nhiên', 'Spending time in nature on weekends helps workers reduce stress after a busy week.', 'Unit 1: Growing Up');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (17, 'Parent', 'n', 'Cha mẹ / Phụ huynh', 'Every parent wants to provide their children with a safe environment and a good education.', 'Unit 1: Growing Up');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (18, 'Relation', 'n', 'Mối quan hệ / Mối liên hệ / Người thân', 'There is a direct relation between regular exercise and improved physical and mental well-being.', 'Unit 1: Growing Up');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (19, 'Relationship', 'n', 'Mối quan hệ', 'Maintaining a good relationship with colleagues makes the daily work environment much more pleasant and productive.', 'Unit 1: Growing Up');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (20, 'Relative', 'n', 'Họ hàng / Người thân', 'During traditional holidays, people often travel back to their hometowns to visit every close relative.', 'Unit 1: Growing Up');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (21, 'Resemblance', 'n', 'Sự giống nhau / Nét tương đồng', 'The young boy shares a striking resemblance to his father in both appearance and gentle smile.', 'Unit 1: Growing Up');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (22, 'Rivalry', 'n', 'Sự cạnh tranh / Sự ganh đua', 'Healthy rivalry between classmates can motivate everyone to study harder and achieve better academic results.', 'Unit 1: Growing Up');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (23, 'Sibling', 'n', 'Anh chị em ruột', 'Children who grow up with an older sibling often learn to share their toys and cooperate easily.', 'Unit 1: Growing Up');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (24, 'Teenager', 'n', 'Thanh thiếu niên (13-19 tuổi)', 'Every teenager needs guidance from both parents and teachers to make good decisions about their future.', 'Unit 1: Growing Up');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (25, 'Temperament', 'n', 'Tính khí / Tâm tính', 'Her calm temperament helps her deal with difficult customers without getting angry or stressed.', 'Unit 1: Growing Up');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (26, 'Ties', 'n', 'Mối quan hệ gắn bó / Sự ràng buộc', 'Family ties remain extremely strong in Asian cultures even when children move away from home.', 'Unit 1: Growing Up');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (27, 'Upbringing', 'n', 'Sự nuôi dưỡng / Sự giáo dục gia đình', 'A loving family upbringing teaches children how to show kindness and respect toward other people.', 'Unit 1: Growing Up');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (28, 'Active role', 'n', 'Vai trò tích cực / Vai trò chủ động', 'Parents should play an active role in helping their children develop healthy reading habits at home.', 'Unit 1: Growing Up');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (29, 'Extended family', 'n', 'Đại gia đình (nhiều thế hệ)', 'Living in an extended family allows grandparents to help take care of their young grandchildren.', 'Unit 1: Growing Up');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (30, 'Family gathering', 'n', 'Buổi sum họp gia đình', 'Our annual family gathering during the New Year holiday brings together relatives from different cities.', 'Unit 1: Growing Up');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (31, 'Immediate family', 'n', 'Gia đình trực hệ (cha mẹ và con cái)', 'He decided to celebrate his university graduation quietly with only his immediate family members.', 'Unit 1: Growing Up');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (32, 'Maternal instinct', 'n', 'Bản năng làm mẹ', 'Her strong maternal instinct made her protect the injured child without thinking about her own safety.', 'Unit 1: Growing Up');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (33, 'Sibling rivalry', 'n', 'Sự ganh đua giữa anh chị em', 'Parents can reduce sibling rivalry by treating each child fairly and praising their unique talents.', 'Unit 1: Growing Up');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (34, 'Stable upbringing', 'n', 'Sự nuôi dạy ổn định / Sự giáo dục vững chắc', 'Children who enjoy a stable upbringing are usually more confident and successful in their adult lives.', 'Unit 1: Growing Up');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (35, 'Striking resemblance', 'n', 'Sự giống nhau đáng kinh ngạc', 'The little girl bears a striking resemblance to her grandmother when she was at that young age.', 'Unit 1: Growing Up');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (36, 'Close', 'adj', 'Gần gũi / Thân thiết', 'She maintains a close relationship with her childhood friends even though they live in different countries.', 'Unit 1: Growing Up');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (37, 'Close-knit', 'adj', 'Gắn bó khăng khít / Khăng khít', 'They grew up in a close-knit community where neighbors always supported each other in difficult times.', 'Unit 1: Growing Up');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (38, 'Maternal', 'adj', '(Thuộc) người mẹ / Phía ngoại', 'His maternal grandparents lived in the countryside and taught him how to grow organic vegetables.', 'Unit 1: Growing Up');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (39, 'Parental', 'adj', '(Thuộc) cha mẹ / Phụ huynh', 'Children need consistent parental guidance to navigate the dangers of using the internet safely.', 'Unit 1: Growing Up');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (40, 'Rewarding', 'adj', 'Đáng giá / Bổ ích / Đem lại cảm giác thỏa mãn', 'Teaching young children can be demanding, but it is one of the most rewarding careers in society.', 'Unit 1: Growing Up');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (41, 'Stable', 'adj', 'Ổn định / Vững chắc', 'A stable job with a reliable monthly income allows young couples to buy their first home.', 'Unit 1: Growing Up');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (42, 'Accommodate', 'v', 'Cung cấp chỗ ở / Đáp ứng (nhu cầu)', 'The new school building was designed to accommodate up to five hundred students and teachers.', 'Unit 1: Growing Up');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (43, 'Adopt', 'v', 'Nhận nuôi / Áp dụng (chính sách, phương pháp)', 'Many modern cities are trying to adopt green policies to reduce air pollution and protect public health.', 'Unit 1: Growing Up');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (44, 'Break down', 'v', 'Bị hỏng / Đổ vỡ / Suy sụp', 'Without clear communication and mutual trust, even long-lasting relationships can easily break down over time.', 'Unit 1: Growing Up');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (45, 'Develop', 'v', 'Phát triển / Mở rộng', 'Reading books every day helps young children develop their language skills and creative thinking ability.', 'Unit 1: Growing Up');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (46, 'Endure', 'v', 'Chịu đựng / Tồn tại lâu dài', 'True friendships can endure through difficult times and long periods of physical separation.', 'Unit 1: Growing Up');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (47, 'Establish', 'v', 'Thành lập / Thiết lập / Tạo dựng', 'It is important for parents to establish clear household rules to teach their children good discipline.', 'Unit 1: Growing Up');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (48, 'Have sth in common', 'v', 'Có điểm chung / Có cùng sở thích', 'Close friends often have many interests in common, which helps them understand each other better.', 'Unit 1: Growing Up');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (49, 'Inherit', 'v', 'Thừa hưởng / Kế thừa', 'Many children inherit physical traits from their parents, such as eye color and hair texture.', 'Unit 1: Growing Up');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (50, 'Interact', 'v', 'Tương tác / Tiếp xúc', 'Team sports give teenagers great opportunities to interact with peers and develop social skills.', 'Unit 1: Growing Up');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (51, 'Nurture', 'v', 'Nuôi dưỡng / Bồi dưỡng / Chăm sóc', 'Parents and teachers must work together to nurture a child''s natural talents and curiosity.', 'Unit 1: Growing Up');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (52, 'Play a role', 'v', 'Đóng một vai trò / Góp phần', 'Teachers play a role in helping young students build confidence and strong moral values.', 'Unit 1: Growing Up');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (53, 'Relate (to)', 'v', 'Thấu hiểu / Đồng cảm / Có liên hệ với', 'Many teenagers find it hard to relate to their parents because of modern lifestyle differences.', 'Unit 1: Growing Up');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (54, 'Adolescent', 'n', 'Người vị thành niên / Thanh thiếu niên', 'An adolescent often experiences emotional stress when preparing for competitive university entrance examinations.', 'Unit 2: Mental and Physical Development');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (55, 'Behaviour', 'n', 'Hành vi / Cách cư xử', 'Parents should encourage good behaviour by praising their children whenever they complete their daily chores.', 'Unit 2: Mental and Physical Development');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (56, 'Childhood', 'n', 'Thời thơ ấu / Tuổi thơ', 'Spending quality time with family during childhood creates warm memories that last for a lifetime.', 'Unit 2: Mental and Physical Development');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (57, 'Concept', 'n', 'Khái niệm / Quan niệm', 'The teacher used real-life examples to explain the complex concept of renewable energy to students.', 'Unit 2: Mental and Physical Development');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (58, 'Consequence', 'n', 'Hậu quả / Kết quả', 'Losing personal focus at school is often a direct consequence of spending too much time gaming.', 'Unit 2: Mental and Physical Development');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (59, 'Gesture', 'n', 'Cử chỉ / Điệu bộ', 'Giving a warm handshake is a common polite gesture when meeting business partners for the first time.', 'Unit 2: Mental and Physical Development');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (60, 'Growth', 'n', 'Sự tăng trưởng / Sự phát triển', 'A balanced daily diet rich in vitamins is essential for the healthy physical growth of children.', 'Unit 2: Mental and Physical Development');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (61, 'Imagination', 'n', 'Trí tưởng tượng', 'Reading adventure stories encourages children to use their imagination and explore new creative ideas.', 'Unit 2: Mental and Physical Development');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (62, 'Infancy', 'n', 'Thời kỳ sơ sinh / Giai đoạn ấu thơ', 'Nutritious food and emotional warmth during infancy are vital for healthy brain development.', 'Unit 2: Mental and Physical Development');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (63, 'Infant', 'n', 'Trẻ sơ sinh', 'A mother can usually tell whether her infant is crying because of hunger or feeling sleepy.', 'Unit 2: Mental and Physical Development');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (64, 'Maturity', 'n', 'Sự trưởng thành / Sự chín chắn', 'Living alone in a foreign city helps university students develop greater emotional maturity and self-discipline.', 'Unit 2: Mental and Physical Development');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (65, 'Memory', 'n', 'Trí nhớ / Ký ức', 'Regular physical exercise and healthy nutrition help elderly people maintain a sharp memory.', 'Unit 2: Mental and Physical Development');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (66, 'Milestone', 'n', 'Cột mốc quan trọng / Bước ngoặt', 'Graduating from university is a major milestone that marks the beginning of an independent professional life.', 'Unit 2: Mental and Physical Development');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (67, 'Mind', 'n', 'Tâm trí / Trí óc', 'Listening to relaxing classical music helps quiet the mind and improves concentration while studying.', 'Unit 2: Mental and Physical Development');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (68, 'Peers', 'n', 'Bạn đồng trang lứa / Bạn cùng tuổi', 'Teenagers often feel strong pressure from their peers to follow current fashion trends and lifestyles.', 'Unit 2: Mental and Physical Development');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (69, 'Period', 'n', 'Thời kỳ / Giai đoạn', 'Adolescence is a critical period when young people form their identities and choose their future paths.', 'Unit 2: Mental and Physical Development');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (70, 'Phase', 'n', 'Giai đoạn / Thời kỳ', 'The first phase of the environmental project will focus on cleaning local rivers and planting trees.', 'Unit 2: Mental and Physical Development');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (71, 'Rate', 'n', 'Tốc độ / Tỷ lệ', 'Children learn new vocabulary words at an impressive rate when their parents read books with them.', 'Unit 2: Mental and Physical Development');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (72, 'Reminder', 'n', 'Lời nhắc nhở / Vật nhắc nhớ', 'She placed a sticky note on her study desk as a visual reminder to finish her homework.', 'Unit 2: Mental and Physical Development');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (73, 'Social skills', 'n', 'Kỹ năng xã hội / Kỹ năng giao tiếp xã hội', 'Joining school clubs allows young students to develop effective social skills and make lifelong friends.', 'Unit 2: Mental and Physical Development');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (74, 'Stage', 'n', 'Giai đoạn / Thời kỳ', 'Learning to share toys with others is a crucial stage in early childhood social development.', 'Unit 2: Mental and Physical Development');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (75, 'Toddler', 'n', 'Trẻ mới biết đi (1-3 tuổi)', 'A toddler requires constant adult attention because they are naturally curious about everything around them.', 'Unit 2: Mental and Physical Development');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (76, 'Transition', 'n', 'Sự chuyển tiếp / Quá trình chuyển đổi', 'The transition from high school to university life can be overwhelming for many young students.', 'Unit 2: Mental and Physical Development');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (77, 'Abstract', 'adj', 'Trừu tượng', 'Young children find it much easier to understand concrete examples rather than purely abstract mathematical concepts.', 'Unit 2: Mental and Physical Development');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (78, 'Clumsy', 'adj', 'Vụng về / Hậu đậu', 'He felt clumsy when he accidentally dropped his coffee cup during his first job interview.', 'Unit 2: Mental and Physical Development');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (79, 'Fond', 'adj', 'Yêu thương / Đầy yêu thích / Thân thương', 'Most adults still cherish fond memories of spending carefree summer holidays in their rural hometowns.', 'Unit 2: Mental and Physical Development');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (80, 'Fully-grown', 'adj', 'Trưởng thành hoàn toàn / Phát triển đầy đủ', 'When a domestic cat becomes fully-grown, it requires a balanced diet to maintain a healthy weight.', 'Unit 2: Mental and Physical Development');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (81, 'Immature', 'adj', 'Chưa chín chắn / Non nớt', 'Blaming others for personal mistakes is an immature habit that prevents individuals from improving themselves.', 'Unit 2: Mental and Physical Development');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (82, 'Independent', 'adj', 'Tự lập / Độc lập', 'Living away from home teaches university students how to cook, clean, and become truly independent.', 'Unit 2: Mental and Physical Development');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (83, 'Irresponsible', 'adj', 'Vô trách nhiệm / Thiếu trách nhiệm', 'Driving a motor vehicle after drinking alcohol is an irresponsible action that endangers everyone on the road.', 'Unit 2: Mental and Physical Development');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (84, 'Mature', 'adj', 'Chín chắn / Trưởng thành', 'She demonstrated a mature attitude by listening calmly to constructive feedback from her school manager.', 'Unit 2: Mental and Physical Development');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (85, 'Patient', 'adj', 'Kiên nhẫn / Nhẫn nại', 'Primary school teachers must remain patient when helping young children learn basic reading and writing.', 'Unit 2: Mental and Physical Development');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (86, 'Rebellious', 'adj', 'Nổi loạn / Ương bướng', 'He went through a rebellious phase during high school, often questioning school rules and parental authority.', 'Unit 2: Mental and Physical Development');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (87, 'Significant', 'adj', 'Đáng kể / Quan trọng', 'Eating a nutritious breakfast provides a significant boost to energy levels and concentration during morning classes.', 'Unit 2: Mental and Physical Development');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (88, 'Tolerant', 'adj', 'Khoan dung / Có tính dung thứ', 'Living in a global city encourages citizens to be more tolerant of different cultures and perspectives.', 'Unit 2: Mental and Physical Development');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (89, 'Acquire', 'v', 'Tiếp thu / Đạt được', 'Young children acquire language naturally by listening to their parents talk and reading stories daily.', 'Unit 2: Mental and Physical Development');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (90, 'Develop', 'v', 'Phát triển / Rèn luyện', 'Participating in volunteer projects helps teenagers develop empathy and practical teamwork skills.', 'Unit 2: Mental and Physical Development');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (91, 'Gesture', 'v', 'Ra hiệu / Làm cử chỉ', 'Tourists often gesture with their hands when trying to communicate with locals in foreign countries.', 'Unit 2: Mental and Physical Development');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (92, 'Grow', 'v', 'Lớn lên / Phát triển', 'Healthy plants grow quickly when they receive plenty of sunlight, fresh water, and fertile soil.', 'Unit 2: Mental and Physical Development');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (93, 'Imitate', 'v', 'Bắt chước / Bắt chước theo', 'Young children naturally imitate the speech patterns and daily habits of their parents at home.', 'Unit 2: Mental and Physical Development');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (94, 'Look back', 'v', 'Nhìn lại / Nhớ lại', 'Older people often look back on their youthful adventures with deep fondness and gentle laughter.', 'Unit 2: Mental and Physical Development');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (95, 'Master', 'v', 'Làm chủ / Nắm vững (kỹ năng)', 'It takes regular practice and genuine patience to master a difficult foreign language like Japanese.', 'Unit 2: Mental and Physical Development');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (96, 'Mature', 'v', 'Trưởng thành / Trở nên chín chắn', 'Teenagers gradually mature as they face everyday responsibilities and make important decisions about their future.', 'Unit 2: Mental and Physical Development');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (97, 'Remember', 'v', 'Ghi nhớ / Nhớ', 'Students should remember to bring their identity cards and admission tickets to the examination room.', 'Unit 2: Mental and Physical Development');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (98, 'Remind', 'v', 'Nhắc nhở / Gợi nhớ', 'Smartphones can remind busy professionals about upcoming appointments and important daily deadlines.', 'Unit 2: Mental and Physical Development');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (99, 'Reminisce', 'v', 'Hồi tưởng / Nhớ lại quá khứ', 'My grandparents often reminisce about their youth when our whole family gathers for dinner.', 'Unit 2: Mental and Physical Development');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (100, 'Throw a tantrum', 'v', 'Nổi cơn tam bành / Ăn vạ / Nổi giận đùng đùng', 'Young children often throw a tantrum when they do not get the toys they want.', 'Unit 2: Mental and Physical Development');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (101, 'Visualise', 'v', 'Hình dung / Mường tượng trong tâm trí', 'Teachers often encourage students to visualise the story before they start writing their essays.', 'Unit 2: Mental and Physical Development');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (102, 'Typically', 'v', 'Thông thường / Điển hình', 'Students typically spend several hours each day reviewing their lessons and preparing for exams.', 'Unit 2: Mental and Physical Development');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (103, 'Bear in mind', 'phrase', 'Ghi nhớ / Hãy nhớ rằng', 'You should bear in mind that learning a foreign language requires regular practice and patience.', 'Unit 2: Mental and Physical Development');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (104, 'Broaden the mind', 'phrase', 'Mở rộng tầm hiểu biết / Mở mang đầu óc', 'Traveling to different countries can help young people broaden the mind and understand new cultures.', 'Unit 2: Mental and Physical Development');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (105, 'Have something in mind', 'phrase', 'Có ý định / Có ý tưởng trong đầu', 'Do you have something in mind for the weekend, or should we go to the cinema?', 'Unit 2: Mental and Physical Development');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (106, 'Have something on your mind', 'phrase', 'Có điều đang bận tâm / Lo lắng về điều gì', 'You look quiet today; do you have something on your mind about your final examination?', 'Unit 2: Mental and Physical Development');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (107, 'It slipped my mind', 'phrase', 'Tôi quên khuấy mất / Vô tình quên mất', 'I was planning to buy some fresh milk after work, but it completely slipped my mind.', 'Unit 2: Mental and Physical Development');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (108, 'Keep an open mind', 'phrase', 'Giữ tư duy cởi mở / Sẵn sàng tiếp thu ý kiến mới', 'It is important to keep an open mind when you listen to opinions that differ from yours.', 'Unit 2: Mental and Physical Development');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (109, 'My mind went blank', 'phrase', 'Đầu óc tôi trống rỗng / Quên sạch không nghĩ ra được gì', 'When the teacher asked me a difficult question in class, my mind went completely blank.', 'Unit 2: Mental and Physical Development');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (110, 'Put your mind at ease', 'phrase', 'Làm cho bạn an tâm / Giải tỏa lo lắng', 'The doctor explained the test results clearly to put her mind at ease before the surgery.', 'Unit 2: Mental and Physical Development');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (111, 'Allergy', 'n', 'Dị ứng / Bệnh dị ứng', 'He developed a severe food allergy after eating seafood during his holiday at the beach.', 'Unit 3: Keeping Fit');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (112, 'Anxiety', 'n', 'Sự lo âu / Cảm giác lo lắng', 'Many high school students experience anxiety before taking important examinations like the IELTS test.', 'Unit 3: Keeping Fit');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (113, 'Appetite', 'n', 'Sự thèm ăn / Khẩu vị', 'Doing regular physical exercise in the morning can help improve your appetite and mood.', 'Unit 3: Keeping Fit');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (114, 'Artery', 'n', 'Động mạch', 'Eating too much fatty food can block a main artery and lead to serious heart problems.', 'Unit 3: Keeping Fit');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (115, 'Asset', 'n', 'Tài sản quý giá / Thế mạnh / Lợi thế', 'Good physical health is a valuable asset that helps people work efficiently and enjoy life.', 'Unit 3: Keeping Fit');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (116, 'Benefit', 'n', 'Lợi ích / Thuận lợi', 'One major benefit of walking every day is that it strengthens your heart and bones.', 'Unit 3: Keeping Fit');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (117, 'Cravings', 'n', 'Cơn thèm đồ ăn / Cảm giác thèm thuồng', 'Drinking plenty of water throughout the day can help you control cravings for sweet snacks.', 'Unit 3: Keeping Fit');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (118, 'Depression', 'n', 'Bệnh trầm cảm / Tình trạng trầm cảm', 'Physical activity and outdoor hobbies are effective ways to reduce stress and prevent depression.', 'Unit 3: Keeping Fit');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (119, 'Diagnosis', 'n', 'Sự chẩn đoán / Kết quả chẩn đoán bệnh', 'An early diagnosis of the disease gives patients a much higher chance of full recovery.', 'Unit 3: Keeping Fit');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (120, 'Diet', 'n', 'Chế độ ăn uống / Chế độ ăn kiêng', 'A balanced diet with plenty of green vegetables and fresh fruits is essential for good health.', 'Unit 3: Keeping Fit');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (121, 'Dietician', 'n', 'Chuyên gia dinh dưỡng', 'She decided to consult a professional dietician to build a healthier meal plan for weight loss.', 'Unit 3: Keeping Fit');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (122, 'Disease', 'n', 'Bệnh tật / Căn bệnh', 'Frequent hand washing is a simple way to prevent the spread of infectious disease.', 'Unit 3: Keeping Fit');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (123, '(eating) disorder', 'n', 'Rối loạn ăn uống', 'Social media pressure about body image can cause teenagers to develop an eating disorder.', 'Unit 3: Keeping Fit');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (124, 'Exercise', 'n', 'Sự tập thể dục / Bài tập thể dục', 'Doctors advise adults to do at least thirty minutes of moderate exercise every single day.', 'Unit 3: Keeping Fit');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (125, 'Factor', 'n', 'Yếu tố / Nhân tố', 'Poor nutrition is a leading factor that causes many chronic illnesses among middle-aged people.', 'Unit 3: Keeping Fit');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (126, 'Fast food', 'n', 'Thức ăn nhanh / Đồ ăn nhanh', 'Many busy parents rely on fast food for dinner because they lack time to cook.', 'Unit 3: Keeping Fit');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (127, 'Fat', 'n', 'Chất béo / Mỡ', 'Eating too much saturated fat can raise cholesterol levels and harm your cardiovascular system.', 'Unit 3: Keeping Fit');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (128, 'Harm', 'n', 'Sự tổn hại / Tác hại', 'Staying up late every night can cause serious harm to your immune system and memory.', 'Unit 3: Keeping Fit');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (129, 'Health', 'n', 'Sức khỏe', 'Regular exercise and adequate sleep are vital habits for maintaining good mental and physical health.', 'Unit 3: Keeping Fit');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (130, 'Heart attack', 'n', 'Cơn đau tim / Cơn nhồi máu cơ tim', 'He stopped smoking and changed his diet immediately after surviving a mild heart attack.', 'Unit 3: Keeping Fit');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (131, 'Infection', 'n', 'Sự nhiễm trùng / Tình trạng nhiễm khuẩn', 'You should clean the wound thoroughly to prevent a bacterial infection from getting worse.', 'Unit 3: Keeping Fit');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (132, 'Ingredients', 'n', 'Nguyên liệu / Thành phần món ăn', 'Cooking at home allows you to choose fresh ingredients and avoid harmful chemical additives.', 'Unit 3: Keeping Fit');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (133, 'Insomnia', 'n', 'Chứng mất ngủ / Bệnh khó ngủ', 'Drinking coffee late in the evening is one of the most common causes of insomnia.', 'Unit 3: Keeping Fit');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (134, 'Intake', 'n', 'Lượng nạp vào / Lượng tiêu thụ', 'Nutrition experts recommend that adults should reduce their daily intake of salt and sugar.', 'Unit 3: Keeping Fit');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (135, 'Junk food', 'n', 'Đồ ăn vặt không lành mạnh / Thức ăn rác', 'Schools should ban junk food in their cafeterias to encourage students to eat healthy meals.', 'Unit 3: Keeping Fit');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (136, 'Muscle', 'n', 'Cơ bắp / Bắp thịt', 'Lifting weights regularly helps to build muscle strength and improve overall body posture.', 'Unit 3: Keeping Fit');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (137, 'Nutrient', 'n', 'Chất dinh dưỡng', 'Green vegetables provide every essential nutrient that our body needs to stay completely healthy.', 'Unit 3: Keeping Fit');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (138, 'Nutrition', 'n', 'Dinh dưỡng / Chế độ dinh dưỡng', 'Schools should educate young children about nutrition so that they can form healthy eating habits.', 'Unit 3: Keeping Fit');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (139, 'Obesity', 'n', 'Bệnh béo phì / Tình trạng béo phì', 'Childhood obesity has become a serious public health issue in many developed countries today.', 'Unit 3: Keeping Fit');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (140, 'Onset', 'n', 'Sự khởi phát / Thời điểm bắt đầu', 'Regular exercise can significantly delay the onset of many age-related health conditions.', 'Unit 3: Keeping Fit');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (141, 'Portion', 'n', 'Khẩu phần ăn / Phần chia', 'Eating a smaller portion of rice at dinner helped him control his daily calorie intake.', 'Unit 3: Keeping Fit');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (142, 'Risk', 'n', 'Nguy cơ / Rủi ro', 'Smoking cigarettes and drinking too much alcohol greatly increase the risk of heart disease.', 'Unit 3: Keeping Fit');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (143, 'Serving', 'n', 'Khẩu phần ăn / Suất ăn', 'Health experts suggest eating at least one serving of fresh vegetables with every meal.', 'Unit 3: Keeping Fit');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (144, 'Stress', 'n', 'Sự căng thẳng / Áp lực tinh thần', 'Many working people listen to classical music to relieve stress after a long busy day.', 'Unit 3: Keeping Fit');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (145, 'Stroke', 'n', 'Cơn đột quỵ / Tai biến mạch máu não', 'High blood pressure is one of the main factors that can cause a dangerous stroke.', 'Unit 3: Keeping Fit');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (146, 'Treatment', 'n', 'Sự điều trị / Liệu trình chữa bệnh', 'Modern medical treatment has helped many patients recover quickly from severe physical injuries.', 'Unit 3: Keeping Fit');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (147, 'Therapy', 'n', 'Liệu pháp / Phương pháp trị liệu', 'He attended physical therapy twice a week to regain full movement in his injured leg.', 'Unit 3: Keeping Fit');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (148, 'Variety', 'n', 'Sự đa dạng / Nhiều loại phong phú', 'You should eat a wide variety of colorful fruits and vegetables to absorb different vitamins.', 'Unit 3: Keeping Fit');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (149, 'Weight', 'n', 'Cân nặng / Trọng lượng', 'She managed to lose excess weight by combining daily jogging with a balanced healthy diet.', 'Unit 3: Keeping Fit');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (150, 'Acute', 'adj', 'Cấp tính / Dữ dội / Rất nghiêm trọng', 'The patient was rushed to the local hospital after experiencing acute pain in his chest.', 'Unit 3: Keeping Fit');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (151, 'Allergic', 'adj', 'Bị dị ứng / Có cơ địa dị ứng', 'My younger brother is allergic to seafood, so he always avoids eating prawns and crabs.', 'Unit 3: Keeping Fit');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (152, 'Alternate', 'adj', 'Luân phiên / Xen kẽ / Cách ngày', 'She attends fitness classes on alternate days to give her muscles sufficient time to rest.', 'Unit 3: Keeping Fit');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (153, 'Brisk', 'adj', 'Nhanh nhẹn / Nhanh và dứt khoát', 'Taking a thirty-minute brisk walk every morning helps stimulate blood circulation and burn fat.', 'Unit 3: Keeping Fit');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (154, 'Chronic', 'adj', 'Mãn tính / Kinh niên kéo dài', 'Patients suffering from chronic back pain often find gentle swimming very beneficial for recovery.', 'Unit 3: Keeping Fit');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (155, 'Harmful', 'adj', 'Có hại / Gây nguy hại', 'Smoking cigarettes and drinking excessive alcohol have extremely harmful effects on your internal organs.', 'Unit 3: Keeping Fit');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (156, 'Healthy', 'adj', 'Khỏe mạnh / Lành mạnh', 'Maintaining a healthy lifestyle through good food and regular exercise prevents many serious diseases.', 'Unit 3: Keeping Fit');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (157, 'Infectious', 'adj', 'Lây nhiễm / Truyền nhiễm', 'Flu is an infectious illness that spreads very quickly among children in crowded classrooms.', 'Unit 3: Keeping Fit');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (158, 'Moderate', 'adj', 'Vừa phải / Điều độ', 'Doing moderate exercise for twenty minutes each morning can improve your overall energy levels.', 'Unit 3: Keeping Fit');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (159, 'Obese', 'adj', 'Bị béo phì', 'People who are obese face a significantly higher risk of developing diabetes and heart problems.', 'Unit 3: Keeping Fit');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (160, 'Overweight', 'adj', 'Thừa cân / Quá cân', 'Many overweight children find it difficult to participate actively in physical sports at school.', 'Unit 3: Keeping Fit');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (161, 'Persistent', 'adj', 'Dai dẳng / Kiên trì / Kéo dài liên tục', 'If you suffer from a persistent cough for two weeks, you should see a doctor.', 'Unit 3: Keeping Fit');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (162, 'Regular', 'adj', 'Đều đặn / Thường xuyên', 'Doing regular exercise helps you maintain a healthy body and reduce stress after work.', 'Unit 3: Keeping Fit');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (163, 'Vital', 'adj', 'Thiết yếu / Vô cùng quan trọng', 'Drinking plenty of clean water every day plays a vital role in maintaining good health.', 'Unit 3: Keeping Fit');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (164, 'Avoid', 'v', 'Tránh xa / Tránh né', 'Doctors advise patients with heart conditions to avoid foods that contain high amounts of salt.', 'Unit 3: Keeping Fit');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (165, 'Counteract', 'v', 'Chống lại / Làm giảm bớt tác hại', 'Eating fresh green vegetables can help counteract the negative effects of stress on your body.', 'Unit 3: Keeping Fit');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (166, 'Curb', 'v', 'Kiềm chế / Kìm hãm / Ngăn chặn', 'The government has introduced new tax policies to curb the consumption of sugary drinks.', 'Unit 3: Keeping Fit');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (167, 'Cure', 'v', 'Chữa khỏi / Điều trị dứt điểm', 'Modern antibiotics can easily cure many bacterial infections that were once dangerous to humans.', 'Unit 3: Keeping Fit');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (168, 'Diminish', 'v', 'Giảm bớt / Suy giảm', 'Getting enough sleep at night will help diminish feelings of anxiety and fatigue during work.', 'Unit 3: Keeping Fit');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (169, 'Disrupt', 'v', 'Làm gián đoạn / Gây xáo trộn', 'Using smartphones late at night can severely disrupt your natural sleep cycle and cause insomnia.', 'Unit 3: Keeping Fit');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (170, 'Eliminate', 'v', 'Loại bỏ / Triệt tiêu hoàn toàn', 'To lose weight effectively, you should try to eliminate sugary snacks from your daily diet.', 'Unit 3: Keeping Fit');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (171, 'Maintain', 'v', 'Duy trì / Giữ gìn', 'It is important for older adults to maintain a regular exercise routine to stay active.', 'Unit 3: Keeping Fit');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (172, 'Overdo', 'v', 'Làm quá mức / Vận động quá sức', 'Beginners should not overdo their gym workouts because it can easily lead to serious injuries.', 'Unit 3: Keeping Fit');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (173, 'Overeat', 'v', 'Ăn quá nhiều / Ăn quá độ', 'People tend to overeat when they watch television because they do not notice feeling full.', 'Unit 3: Keeping Fit');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (174, 'Prevent', 'v', 'Ngăn chặn / Phòng ngừa', 'Washing your hands with soap before meals helps prevent the spread of harmful bacteria.', 'Unit 3: Keeping Fit');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (175, 'Recommend', 'v', 'Khuyên bảo / Đề xuất', 'Doctors often recommend eating fresh fruit instead of processed snacks to protect your overall health.', 'Unit 3: Keeping Fit');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (176, 'Recover', 'v', 'Hồi phục / Bình phục', 'It usually takes several weeks for patients to recover fully after having major surgery.', 'Unit 3: Keeping Fit');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (177, 'Reduce', 'v', 'Giảm bớt / Cắt giảm', 'Practicing yoga every morning can help reduce mental tension and improve your flexibility.', 'Unit 3: Keeping Fit');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (178, 'Skip', 'v', 'Bỏ qua / Bỏ bữa', 'You should never skip breakfast because it gives you vital energy for the entire morning.', 'Unit 3: Keeping Fit');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (179, 'Stimulate', 'v', 'Kích thích / Thúc đẩy', 'Reading books and solving puzzles can stimulate brain activity and enhance your memory as you age.', 'Unit 3: Keeping Fit');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (180, 'Trigger', 'v', 'Gây ra / Khơi mào / Kích hoạt', 'Eating certain foods or smelling strong chemicals can trigger a painful migraine headache.', 'Unit 3: Keeping Fit');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (181, 'Activity', 'n', 'Hoạt động', 'Outdoor activity like cycling in the park helps children develop strong muscles and healthy habits.', 'Unit 4: Lifestyles');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (182, 'Aspect', 'n', 'Khía cạnh / Phương diện', 'Work-life balance is an important aspect of modern lifestyle that many young workers care about.', 'Unit 4: Lifestyles');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (183, 'Attitude', 'n', 'Thái độ / Quan điểm sống', 'Maintaining a positive attitude toward challenges can help you overcome stress in your daily life.', 'Unit 4: Lifestyles');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (184, '(achieve a) balance', 'n', 'Sự cân bằng / Đạt được sự cân bằng', 'It is difficult for working parents to achieve a balance between their careers and family life.', 'Unit 4: Lifestyles');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (185, 'Competition', 'n', 'Cuộc thi / Sự cạnh tranh', 'Taking part in a friendly sports competition encourages teenagers to build teamwork and confidence.', 'Unit 4: Lifestyles');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (186, 'Creativity', 'n', 'Sự sáng tạo / Óc sáng tạo', 'Art classes in primary schools provide a great way for children to develop their creativity.', 'Unit 4: Lifestyles');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (187, 'Daily routine', 'n', 'Thói quen hằng ngày / Lịch trình hằng ngày', 'Having a stable daily routine helps students manage their study time much more effectively.', 'Unit 4: Lifestyles');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (188, 'Desire', 'n', 'Khao khát / Mong muốn', 'Many young people share a strong desire to travel abroad and explore new cultures.', 'Unit 4: Lifestyles');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (189, 'Disappointment', 'n', 'Sự thất vọng / Nỗi thất vọng', 'She could not hide her disappointment when she received lower exam scores than she expected.', 'Unit 4: Lifestyles');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (190, 'Experience', 'n', 'Kinh nghiệm / Trải nghiệm', 'Volunteering in community projects is an enriching experience that teaches valuable social skills.', 'Unit 4: Lifestyles');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (191, 'Fulfilment', 'n', 'Cảm giác viên mãn / Sự thỏa nguyện', 'Helping others in need brings a deep sense of personal fulfilment and happiness to volunteers.', 'Unit 4: Lifestyles');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (192, 'Goal', 'n', 'Mục tiêu', 'Setting a realistic goal is the first step towards achieving academic success at university.', 'Unit 4: Lifestyles');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (193, 'Hobby', 'n', 'Sở thích', 'Gardening is a relaxing hobby that helps many elderly people stay physically active and happy.', 'Unit 4: Lifestyles');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (194, 'Insight', 'n', 'Cái nhìn sâu sắc / Sự hiểu biết sâu sắc', 'The guest speaker gave valuable insight into how modern technology is reshaping our daily lifestyles.', 'Unit 4: Lifestyles');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (195, 'Leisure', 'n', 'Thời gian rảnh rỗi / Hoạt động thư giãn', 'Most busy professionals enjoy spending their leisure time with family or playing outdoor sports.', 'Unit 4: Lifestyles');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (196, 'Lifestyle', 'n', 'Lối sống / Phong cách sống', 'Adopting an active lifestyle with healthy meals can prevent many common diseases among older adults.', 'Unit 4: Lifestyles');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (197, 'Optimist', 'n', 'Người lạc quan', 'As an optimist, she always believes that hard work will lead to success in life.', 'Unit 4: Lifestyles');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (198, 'Outlook', 'n', 'Quan điểm / Cách nhìn / Triển vọng', 'Travelling to different countries can help young people develop a positive outlook on life.', 'Unit 4: Lifestyles');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (199, 'Opportunity', 'n', 'Cơ hội / Dịp tốt', 'Studying abroad provides students with a great opportunity to learn about new cultures.', 'Unit 4: Lifestyles');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (200, 'Personality', 'n', 'Tính cách / Nhân cách', 'Parents play an important role in shaping the personality and behavior of their children.', 'Unit 4: Lifestyles');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (201, 'Pessimist', 'n', 'Người bi quan', 'A pessimist usually focuses on the problems instead of looking for solutions.', 'Unit 4: Lifestyles');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (202, 'Priority', 'n', 'Sự ưu tiên / Quyền ưu tiên', 'Maintaining a healthy lifestyle should be a top priority for busy working people.', 'Unit 4: Lifestyles');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (203, 'Pressure', 'n', 'Áp lực', 'Many students feel heavy pressure from exams and expectations from their parents.', 'Unit 4: Lifestyles');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (204, 'Realist', 'n', 'Người thực tế', 'He is a realist who accepts practical difficulties rather than dreaming about perfection.', 'Unit 4: Lifestyles');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (205, 'Risk-taker', 'n', 'Người thích mạo hiểm / Người dám chấp nhận rủi ro', 'A successful entrepreneur is often a risk-taker who is not afraid of failure.', 'Unit 4: Lifestyles');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (206, 'Self-expression', 'n', 'Sự tự thể hiện bản thân', 'Art and music give young people a creative way for emotional self-expression.', 'Unit 4: Lifestyles');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (207, 'Sense', 'n', 'Cảm giác / Giác quan / Ý thức', 'Doing volunteer work helps young people develop a strong sense of social responsibility.', 'Unit 4: Lifestyles');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (208, 'Active', 'adj', 'Năng động / Tích cực', 'Children who lead an active lifestyle are generally healthier and more energetic.', 'Unit 4: Lifestyles');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (209, 'Bored', 'adj', 'Buồn chán / Cảm thấy chán', 'Students often get bored when the lessons are too long and not interactive.', 'Unit 4: Lifestyles');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (210, 'Confused', 'adj', 'Bối rối / Hoang mang', 'Fresh graduates often feel confused when choosing the right career path for themselves.', 'Unit 4: Lifestyles');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (211, 'Dissatisfied', 'adj', 'Không hài lòng / Bất mãn', 'Many customers were dissatisfied with the slow customer service at the local bank.', 'Unit 4: Lifestyles');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (212, 'Intense', 'adj', 'Mãnh liệt / Dữ dội / Cao độ', 'University students often experience intense pressure during their final examination period.', 'Unit 4: Lifestyles');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (213, 'Materialistic', 'adj', 'Thực dụng / Coi trọng vật chất', 'Modern society has become more materialistic because people often judge success by wealth.', 'Unit 4: Lifestyles');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (214, 'Negative', 'adj', 'Tiêu cực / Bi quan', 'Spending too much time on social media can have a negative impact on mental health.', 'Unit 4: Lifestyles');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (215, 'Outdoor', 'adj', 'Ngoài trời', 'Schools should encourage outdoor activities to help children stay active and fit.', 'Unit 4: Lifestyles');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (216, 'Positive', 'adj', 'Tích cực / Lạc quan', 'Regular exercise and a balanced diet bring many positive benefits to physical health.', 'Unit 4: Lifestyles');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (217, 'Recreational', 'adj', 'Giải trí / Tiêu khiển', 'The city should build more recreational facilities like public parks and sports centers.', 'Unit 4: Lifestyles');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (218, 'Successful', 'adj', 'Thành công', 'Hard work and dedication are essential qualities to become successful in your chosen career.', 'Unit 4: Lifestyles');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (219, 'Achieve (a goal)', 'v', 'Đạt được (mục tiêu) / Hoàn thành', 'You need a clear plan and strong discipline to achieve a goal in your studies.', 'Unit 4: Lifestyles');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (220, 'Appeal', 'v', 'Thu hút / Hấp dẫn / Kêu gọi', 'Living in a peaceful countryside appeals to many elderly people seeking quiet retirement.', 'Unit 4: Lifestyles');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (221, 'Attract', 'v', 'Thu hút / Lôi cuốn', 'Big cities always attract young people because of abundant job opportunities and modern lifestyle.', 'Unit 4: Lifestyles');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (222, 'Choose', 'v', 'Chọn / Lựa chọn', 'Many students choose to live in a dormitory to save accommodation costs.', 'Unit 4: Lifestyles');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (223, 'Express', 'v', 'Bày tỏ / Thể hiện', 'It is important for children to learn how to express their feelings calmly and clearly.', 'Unit 4: Lifestyles');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (224, 'Enjoy', 'v', 'Thưởng thức / Tận hưởng / Thích', 'Many young people enjoy spending their weekends doing outdoor activities with close friends.', 'Unit 4: Lifestyles');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (225, 'Fulfil', 'v', 'Thực hiện / Hoàn thành / Làm thỏa mãn', 'He worked very hard to fulfil his dream of becoming a university lecturer.', 'Unit 4: Lifestyles');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (226, 'Improve', 'v', 'Cải thiện / Nâng cao', 'Reading English news every day can significantly improve your vocabulary and reading comprehension.', 'Unit 4: Lifestyles');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (227, 'Motivate', 'v', 'Thúc đẩy / Động viên / Tạo động lực', 'Good teachers always motivate their students to explore new knowledge and think independently.', 'Unit 4: Lifestyles');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (228, 'Participate', 'v', 'Tham gia', 'Students should actively participate in community services to gain valuable practical experience.', 'Unit 4: Lifestyles');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (229, 'Regret', 'v', 'Hối tiếc / Tiếc nuối', 'Many people later regret spending too much time working instead of caring for family.', 'Unit 4: Lifestyles');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (230, 'Relax', 'v', 'Thư giãn / Nghỉ ngơi', 'Listening to soft music is a wonderful way to relax after a stressful working day.', 'Unit 4: Lifestyles');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (231, 'Satisfy', 'v', 'Làm hài lòng / Thỏa mãn / Đáp ứng', 'The company improved its product quality to satisfy the increasing demands of modern customers.', 'Unit 4: Lifestyles');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (232, 'Lead a happy life', 'v', 'Sống một cuộc sống hạnh phúc', 'Balancing work and personal life is essential to lead a happy life in modern times.', 'Unit 4: Lifestyles');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (233, 'Live life on the edge', 'v', 'Sống mạo hiểm / Sống phiêu lưu', 'Extreme sports enthusiasts usually like to live life on the edge by taking big challenges.', 'Unit 4: Lifestyles');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (234, 'Live life to the full', 'v', 'Sống hết mình / Tận hưởng cuộc sống trọn vẹn', 'Young people should pursue their passions and live life to the full every single day.', 'Unit 4: Lifestyles');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (235, 'Make a choice', 'v', 'Đưa ra lựa chọn / Chọn lựa', 'High school graduates must make a choice between entering university or finding immediate employment.', 'Unit 4: Lifestyles');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (236, 'Make a decision', 'v', 'Đưa ra quyết định', 'You should carefully consider all advantages and disadvantages before you make a decision.', 'Unit 4: Lifestyles');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (237, 'Make a living', 'v', 'Kiếm sống / Mưu sinh', 'Many rural workers move to large industrial cities to make a living and support families.', 'Unit 4: Lifestyles');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (238, 'Meet a need', 'v', 'Đáp ứng một nhu cầu', 'The new community healthcare center was built to meet a need for affordable medical care.', 'Unit 4: Lifestyles');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (239, 'Miss (an opportunity)', 'v', 'Bỏ lỡ (một cơ hội)', 'If you hesitate too long, you might miss an opportunity to study at this prestigious university.', 'Unit 4: Lifestyles');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (240, 'Play a role', 'v', 'Đóng vai trò / Góp phần', 'Schools play a role in teaching children essential social skills for their future growth.', 'Unit 4: Lifestyles');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (241, 'Put pressure on', 'v', 'Gây áp lực lên / Tạo áp lực đối với', 'Parents should not put pressure on their children to achieve perfect test scores in school.', 'Unit 4: Lifestyles');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (242, 'Set (a goal)', 'v', 'Đặt ra (mục tiêu)', 'It is important to set a goal before you begin preparing for the IELTS examination.', 'Unit 4: Lifestyles');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (243, 'Take part (in)', 'v', 'Tham gia (vào)', 'All university students are encouraged to take part in green environmental protection projects.', 'Unit 4: Lifestyles');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (244, 'Work hard for a living', 'v', 'Làm việc chăm chỉ để kiếm sống', 'My parents had to work hard for a living to provide us with higher education.', 'Unit 4: Lifestyles');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (245, 'All walks of life', 'phrase', 'Mọi tầng lớp xã hội', 'Public libraries welcome people from all walks of life who want to gain more knowledge.', 'Unit 4: Lifestyles');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (246, 'Cost of living', 'phrase', 'Chi phí sinh hoạt', 'The high cost of living in metropolitan areas makes it difficult for young couples to buy homes.', 'Unit 4: Lifestyles');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (247, 'Lifelong ambition', 'phrase', 'Ước mơ cả đời / Hoài bão suốt đời', 'Winning a scholarship to study in the UK was her lifelong ambition since early childhood.', 'Unit 4: Lifestyles');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (248, 'Living expenses', 'phrase', 'Chi phí sinh hoạt / Tiền sinh hoạt', 'Many students work part-time jobs during their studies to cover their monthly living expenses.', 'Unit 4: Lifestyles');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (249, 'Once in a lifetime opportunity', 'phrase', 'Cơ hội ngàn năm có một / Cơ hội một lần trong đời', 'Receiving a full scholarship to Cambridge is truly a once in a lifetime opportunity for him.', 'Unit 4: Lifestyles');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (250, 'Standard of living', 'phrase', 'Mức sống / Tiêu chuẩn sống', 'Economic development has significantly improved the overall standard of living for most citizens in this country.', 'Unit 4: Lifestyles');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (251, 'Way of life', 'phrase', 'Lối sống / Nếp sống', 'Modern technology has completely changed the traditional way of life in many rural communities.', 'Unit 4: Lifestyles');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (252, 'Assignment', 'n', 'Bài tập / Bài tập lớn / Nhiệm vụ được giao', 'Students must submit their written assignment before midnight to avoid losing valuable academic marks.', 'Unit 5: Student Life');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (253, 'College', 'n', 'Trường đại học / Trường cao đẳng', 'After finishing high school, she decided to attend a local college to study computer programming.', 'Unit 5: Student Life');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (254, 'Controversy', 'n', 'Sự tranh cãi / Cuộc tranh luận', 'The introduction of school uniforms has caused a lot of controversy among students and parents.', 'Unit 5: Student Life');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (255, 'Curriculum', 'n', 'Chương trình giảng dạy / Khung chương trình học', 'The school curriculum should include more practical skills like financial management and critical thinking.', 'Unit 5: Student Life');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (256, 'Dissertation', 'n', 'Luận văn tốt nghiệp / Luận án', 'Final-year university students must write a lengthy dissertation based on their own independent research.', 'Unit 5: Student Life');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (257, 'Education', 'n', 'Giáo dục / Nền giáo dục', 'Investing in primary education is crucial for reducing poverty and boosting long-term economic growth.', 'Unit 5: Student Life');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (258, 'Exam', 'n', 'Kỳ thi / Bài thi', 'Students should review their study notes carefully before taking the final semester exam.', 'Unit 5: Student Life');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (259, 'Field (of study)', 'n', 'Lĩnh vực nghiên cứu / Chuyên ngành học', 'Artificial intelligence has become an extremely popular field of study among university students today.', 'Unit 5: Student Life');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (260, 'Findings', 'n', 'Kết quả nghiên cứu / Phát hiện', 'The research findings showed that regular physical activity helps improve students'' memory and concentration.', 'Unit 5: Student Life');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (261, 'Funding', 'n', 'Nguồn kinh phí / Tiền tài trợ', 'The university received significant funding from the government to build new science laboratories.', 'Unit 5: Student Life');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (262, 'Grade', 'n', 'Điểm số / Điểm học tập', 'She studied diligently every evening to achieve a high grade in her mathematics exam.', 'Unit 5: Student Life');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (263, 'Graduation', 'n', 'Lễ tốt nghiệp / Sự tốt nghiệp', 'Many students feel proud and excited when attending their university graduation ceremony with family.', 'Unit 5: Student Life');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (264, 'Grant', 'n', 'Khoản trợ cấp / Tiền trợ cấp nghiên cứu', 'The student received a government grant to pay for his educational expenses abroad.', 'Unit 5: Student Life');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (265, 'High school', 'n', 'Trường trung học phổ thông / Trường cấp 3', 'Students often make lifelong friendships during their time studying at high school together.', 'Unit 5: Student Life');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (266, 'Homework', 'n', 'Bài tập về nhà', 'Teachers should not assign too much homework so that children have time to relax.', 'Unit 5: Student Life');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (267, 'Junior school', 'n', 'Trường tiểu học (cho trẻ 7-11 tuổi) / Trường sơ cấp', 'Children in junior school learn fundamental subjects like reading, mathematics, and basic science.', 'Unit 5: Student Life');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (268, 'Kindergarten', 'n', 'Trường mẫu giáo / Lớp mầm non', 'Going to kindergarten helps young children develop basic social skills before entering primary school.', 'Unit 5: Student Life');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (269, 'Learning disorder', 'n', 'Hội chứng rối loạn học tập', 'Children with a learning disorder need special support and patient guidance from experienced teachers.', 'Unit 5: Student Life');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (270, 'Lecturer', 'n', 'Giảng viên đại học', 'The lecturer explained complex economic theories using simple examples that everyone could understand.', 'Unit 5: Student Life');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (271, 'Library', 'n', 'Thư viện', 'The university library provides students with a quiet environment and access to numerous textbooks.', 'Unit 5: Student Life');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (272, 'Limits', 'n', 'Giới hạn / Giới hạn năng lực', 'Studying for tough exams often pushes students to test the limits of their abilities.', 'Unit 5: Student Life');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (273, 'Masters', 'n', 'Bằng thạc sĩ / Chương trình thạc sĩ', 'She plans to pursue a Masters degree in international business after completing her bachelor degree.', 'Unit 5: Student Life');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (274, 'Nursery', 'n', 'Nhà trẻ / Trường mầm non', 'Working parents often send their toddlers to a local nursery during regular working hours.', 'Unit 5: Student Life');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (275, 'PhD', 'n', 'Học vị tiến sĩ / Bằng tiến sĩ', 'He spent four years conducting scientific research to complete his PhD in chemistry.', 'Unit 5: Student Life');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (276, 'Primary school', 'n', 'Trường tiểu học / Trường cấp 1', 'Primary school provides young children with essential foundational skills in reading and basic mathematics.', 'Unit 5: Student Life');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (277, 'Program', 'n', 'Chương trình đào tạo / Khóa học', 'This university offers an exchange program that allows students to study in France for one year.', 'Unit 5: Student Life');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (278, 'Project', 'n', 'Dự án / Đề án học tập', 'Working on a group project teaches students how to cooperate and solve problems together.', 'Unit 5: Student Life');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (279, 'Research', 'n', 'Nghiên cứu / Công trình nghiên cứu', 'Scientific research plays a crucial role in discovering new medical treatments for dangerous diseases.', 'Unit 5: Student Life');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (280, 'Resources', 'n', 'Tài liệu học tập / Nguồn lực / Tài nguyên', 'Online learning platforms provide abundant learning resources for students around the world.', 'Unit 5: Student Life');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (281, 'Results', 'n', 'Kết quả / Kết quả thi cử', 'Students were nervous while waiting for their final examination results to be published online.', 'Unit 5: Student Life');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (282, 'Scholarship', 'n', 'Học bổng', 'He won a prestigious scholarship to study environmental engineering at a top university in Australia.', 'Unit 5: Student Life');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (283, 'Scope', 'n', 'Phạm vi / Quy mô', 'The scope of this research paper is limited to renewable energy use in developing countries.', 'Unit 5: Student Life');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (284, 'Secondary school', 'n', 'Trường trung học cơ sở / Trường cấp 2', 'Students in secondary school usually begin to study more specialized academic subjects like physics.', 'Unit 5: Student Life');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (285, 'Sources', 'n', 'Nguồn tài liệu / Nguồn trích dẫn', 'Academic essays require students to cite reliable sources such as academic journals and official reports.', 'Unit 5: Student Life');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (286, 'Syllabus', 'n', 'Đề cương khóa học / Giáo trình tóm tắt', 'On the first day of class, the professor handed out the course syllabus detailing all assignments.', 'Unit 5: Student Life');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (287, 'Task', 'n', 'Nhiệm vụ / Bài tập được giao', 'Completing this difficult writing task requires students to conduct extensive background research.', 'Unit 5: Student Life');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (288, 'Theory', 'n', 'Lý thuyết / Học thuyết', 'Students need to understand both scientific theory and practical application to succeed in engineering.', 'Unit 5: Student Life');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (289, 'Thesis', 'n', 'Luận văn / Luận án tốt nghiệp', 'She spent almost an entire year conducting field surveys to complete her master thesis.', 'Unit 5: Student Life');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (290, 'Tutor', 'n', 'Gia sư / Giảng viên hướng dẫn', 'My private tutor helped me improve my English pronunciation and grammar significantly before the exam.', 'Unit 5: Student Life');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (291, 'Topic', 'n', 'Chủ đề / Đề tài', 'Choosing an interesting topic makes writing an academic essay much more enjoyable and effective.', 'Unit 5: Student Life');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (292, 'University', 'n', 'Trường đại học', 'Entering university gives young adults more independence and helps them prepare for future careers.', 'Unit 5: Student Life');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (293, 'Academic', 'adj', 'Thuộc học thuật / Mang tính học thuật', 'Good academic performance in school can open doors to prestigious universities and attractive scholarships.', 'Unit 5: Student Life');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (294, 'Eligible', 'adj', 'Đủ điều kiện / Đủ tư cách', 'Only students with high grade point averages are eligible to apply for this international scholarship.', 'Unit 5: Student Life');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (295, 'Mixed', 'adj', 'Hỗn hợp / Đan xen / Cả nam lẫn nữ', 'Many students prefer to study in mixed schools because it prepares them for real life.', 'Unit 5: Student Life');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (296, 'Postgraduate', 'adj', 'Sau đại học', 'She decided to apply for a postgraduate course in education to improve her career prospects.', 'Unit 5: Student Life');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (297, 'Relevant', 'adj', 'Có liên quan / Thích hợp', 'University courses should provide relevant skills that help graduates find good jobs easily.', 'Unit 5: Student Life');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (298, 'Senior', 'adj', 'Cấp cao / Lớn tuổi hơn / Lâu năm', 'First-year students often receive helpful advice from senior students about campus life.', 'Unit 5: Student Life');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (299, 'Single-sex', 'adj', 'Đơn giới tính / Dành riêng cho nam hoặc nữ', 'Some parents choose single-sex schools because they believe students can concentrate better.', 'Unit 5: Student Life');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (300, 'Studious', 'adj', 'Chăm học / Ham học', 'He is a studious person who spends most of his free time reading in the library.', 'Unit 5: Student Life');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (301, 'Work-related', 'adj', 'Liên quan đến công việc', 'Many young employees experience work-related stress because of heavy workloads and long hours.', 'Unit 5: Student Life');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (302, 'Adopt (an approach)', 'v', 'Áp dụng (một cách tiếp cận / một phương pháp)', 'Teachers should adopt a modern approach to help students learn English more effectively.', 'Unit 5: Student Life');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (303, 'Analyse', 'v', 'Phân tích', 'Students need to analyse the survey results carefully before writing their final report.', 'Unit 5: Student Life');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (304, 'Conduct', 'v', 'Tiến hành / Thực hiện', 'Scientists conduct research to discover new ways to protect the natural environment.', 'Unit 5: Student Life');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (305, 'Concentrate', 'v', 'Tập trung', 'It is difficult for children to concentrate on studying when their room is noisy.', 'Unit 5: Student Life');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (306, 'Consider', 'v', 'Cân nhắc / Xem xét', 'High school graduates should consider their personal interests before choosing a university major.', 'Unit 5: Student Life');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (307, 'Find out', 'v', 'Tìm hiểu / Khám phá ra', 'Students can visit the university website to find out more about tuition fees.', 'Unit 5: Student Life');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (308, 'Graduate', 'v', 'Tốt nghiệp', 'After they graduate from university, many young people want to travel abroad.', 'Unit 5: Student Life');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (309, 'Learn (about)', 'v', 'Tìm hiểu về / Học về', 'History classes allow young students to learn about different cultures and traditions.', 'Unit 5: Student Life');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (310, 'Organise', 'v', 'Tổ chức / Sắp xếp', 'The school will organise a sports event to encourage students to stay healthy.', 'Unit 5: Student Life');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (311, 'Overcome', 'v', 'Vượt qua / Khắc phục', 'Practicing speaking every day helped him overcome his fear of making mistakes.', 'Unit 5: Student Life');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (312, 'Review', 'v', 'Ôn tập / Xem lại / Đánh giá', 'You should review your notes every evening to prepare well for exams.', 'Unit 5: Student Life');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (313, 'Revise', 'v', 'Ôn tập / Sửa đổi', 'Students often spend several weeks revising their lessons before the final examination.', 'Unit 5: Student Life');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (314, 'Struggle', 'v', 'Gặp khó khăn / Vật lộn', 'Many international students struggle with the language barrier during their first semester.', 'Unit 5: Student Life');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (315, 'Take (a course)', 'v', 'Tham gia (khóa học) / Học (một khóa)', 'I decided to take an online course to improve my digital skills.', 'Unit 5: Student Life');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (316, 'Relatively', 'v', 'Tương đối', 'Living in the countryside is relatively cheap compared to living in a big city.', 'Unit 5: Student Life');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (317, 'Accuracy', 'n', 'Độ chính xác / Sự chính xác', 'Language learners should focus on both accuracy and fluency when practicing speaking.', 'Unit 6: Effective Communication');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (318, 'Communication', 'n', 'Giao tiếp / Sự liên lạc / Truyền thông', 'Good communication skills are essential for building positive relationships at work.', 'Unit 6: Effective Communication');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (319, 'Concept', 'n', 'Khái niệm / Ý tưởng', 'The professor used simple examples to explain a difficult scientific concept to students.', 'Unit 6: Effective Communication');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (320, 'Conjecture', 'n', 'Sự phỏng đoán / Sự ước đoán', 'Without clear evidence, the news report was based purely on conjecture.', 'Unit 6: Effective Communication');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (321, 'Dialect', 'n', 'Phương ngữ / Tiếng địa phương', 'People from different regions of the country often speak with a distinct dialect.', 'Unit 6: Effective Communication');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (322, 'Fluency', 'n', 'Sự lưu loát / Độ trôi chảy', 'Daily conversation with native speakers will greatly improve your fluency in English.', 'Unit 6: Effective Communication');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (323, 'Gesture', 'n', 'Cử chỉ / Điệu bộ', 'A friendly gesture such as a smile can help break the ice when meeting new people.', 'Unit 6: Effective Communication');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (324, 'Hesitation', 'n', 'Sự do dự / Sự ngập ngừng', 'Too much hesitation during the speaking test can lower your overall fluency score.', 'Unit 6: Effective Communication');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (325, 'Language', 'n', 'Ngôn ngữ / Tiếng', 'Learning a second language helps broaden your knowledge and career opportunities.', 'Unit 6: Effective Communication');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (326, 'Language barrier', 'n', 'Rào cản ngôn ngữ', 'The language barrier made it challenging for tourists to ask for directions.', 'Unit 6: Effective Communication');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (327, 'Linguist', 'n', 'Nhà ngôn ngữ học', 'As a linguist, she studies how children acquire their first language naturally.', 'Unit 6: Effective Communication');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (328, 'Linguistics', 'n', 'Ngôn ngữ học', 'He chose to study linguistics at university because he is fascinated by word origins.', 'Unit 6: Effective Communication');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (329, 'Means of communication', 'n', 'Phương tiện giao tiếp / Phương tiện liên lạc', 'Social media has become the most popular means of communication among teenagers today.', 'Unit 6: Effective Communication');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (330, 'Mother tongue', 'n', 'Tiếng mẹ đẻ', 'Children learn their mother tongue naturally through daily interaction with their parents.', 'Unit 6: Effective Communication');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (331, 'Native speaker', 'n', 'Người bản xứ / Người nói tiếng bản ngữ', 'Talking regularly with a native speaker is a great way to improve your pronunciation.', 'Unit 6: Effective Communication');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (332, 'Pronunciation', 'n', 'Cách phát âm / Sự phát âm', 'Clear pronunciation allows listeners to understand your message without any confusion.', 'Unit 6: Effective Communication');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (333, 'Sign language', 'n', 'Ngôn ngữ ký hiệu', 'Many deaf people use sign language to communicate comfortably with their friends and family.', 'Unit 6: Effective Communication');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (334, 'Vocabulary', 'n', 'Từ vựng', 'Reading books every day is an effective method to expand your English vocabulary.', 'Unit 6: Effective Communication');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (335, 'Incoherent', 'adj', 'Không mạch lạc / Rời rạc', 'Because he was nervous, his presentation became incoherent and hard to follow.', 'Unit 6: Effective Communication');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (336, 'Inherent', 'adj', 'Vốn có / Cố hữu', 'Stress is an inherent part of working in busy modern environments.', 'Unit 6: Effective Communication');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (337, 'Sophisticated', 'adj', 'Tinh vi / Phức tạp / Tinh tế', 'Modern smartphones use sophisticated technology to recognize voice commands accurately.', 'Unit 6: Effective Communication');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (338, 'Spontaneous', 'adj', 'Tự phát / Tự nhiên / Ngẫu hứng', 'Her spontaneous response showed that she truly understood the question.', 'Unit 6: Effective Communication');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (339, 'Clarify', 'v', 'Làm rõ / Giải thích rõ ràng', 'The teacher used simple examples to clarify the rules of the grammar lesson.', 'Unit 6: Effective Communication');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (340, 'Communicate', 'v', 'Giao tiếp / Truyền đạt', 'Technology allows people from different countries to communicate with each other easily.', 'Unit 6: Effective Communication');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (341, 'Comprehend', 'v', 'Hiểu / Lĩnh hội', 'Beginners often find it difficult to comprehend complex academic texts.', 'Unit 6: Effective Communication');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (342, 'Conclude', 'v', 'Kết luận / Kết thúc', 'In the final paragraph of your essay, you should conclude your main arguments.', 'Unit 6: Effective Communication');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (343, 'Confirm', 'v', 'Xác nhận / Khẳng định', 'Please check your email and confirm your flight booking before tomorrow morning.', 'Unit 6: Effective Communication');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (344, 'Converse', 'v', 'Trò chuyện / Đàm đạo', 'She enjoys the opportunity to converse with native speakers to practice her pronunciation.', 'Unit 6: Effective Communication');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (345, 'Define', 'v', 'Định nghĩa / Xác định rõ', 'Dictionaries help students define unfamiliar words when reading new articles.', 'Unit 6: Effective Communication');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (346, 'Demonstrate', 'v', 'Chứng minh / Thể hiện / Minh họa', 'Candidates should demonstrate strong communication skills during the job interview.', 'Unit 6: Effective Communication');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (347, 'Distinguish', 'v', 'Phân biệt', 'Young children can easily distinguish between different sounds in a language.', 'Unit 6: Effective Communication');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (348, 'Emerge', 'v', 'Xuất hiện / Nổi lên', 'Online learning began to emerge as a popular trend during the pandemic.', 'Unit 6: Effective Communication');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (349, 'Evolve', 'v', 'Phát triển / Tiến hóa', 'Human languages continue to evolve over time as new words are created.', 'Unit 6: Effective Communication');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (350, 'Explain', 'v', 'Giải thích', 'The guide will explain the history of the museum to the tourists.', 'Unit 6: Effective Communication');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (351, 'Express', 'v', 'Bày tỏ / Thể hiện / Diễn đạt', 'Writing a personal diary is a wonderful way to express your feelings and thoughts.', 'Unit 6: Effective Communication');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (352, 'Gesture', 'v', 'Ra hiệu / Làm cử chỉ', 'The teacher gestured towards the whiteboard to draw the students'' attention.', 'Unit 6: Effective Communication');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (353, 'Illustrate', 'v', 'Minh họa / Làm rõ', 'The speaker used colourful charts to illustrate the growth of online shopping.', 'Unit 6: Effective Communication');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (354, 'Imply', 'v', 'Ngụ ý / Ám chỉ', 'His silent reaction seemed to imply that he did not agree with the plan.', 'Unit 6: Effective Communication');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (355, 'Indicate', 'v', 'Chỉ ra / Biểu thị', 'Recent survey results indicate that more people prefer working from home.', 'Unit 6: Effective Communication');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (356, 'Pronounce', 'v', 'Phát âm', 'It takes regular practice to pronounce English words with correct word stress.', 'Unit 6: Effective Communication');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (357, 'Recall', 'v', 'Nhớ lại / Hồi tưởng', 'I can clearly recall my first day at primary school with my parents.', 'Unit 6: Effective Communication');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (358, 'Refer (to)', 'v', 'Tham khảo / Đề cập đến', 'Students can refer to the textbook whenever they need help with homework.', 'Unit 6: Effective Communication');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (359, 'Signify', 'v', 'Biểu thị / Thể hiện / Có ý nghĩa là', 'In many cultures, a white dove is used to signify peace and harmony.', 'Unit 6: Effective Communication');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (360, 'State', 'v', 'Tuyên bố / Nêu rõ / Phát biểu', 'You should clearly state your personal opinion in the introduction of your essay.', 'Unit 6: Effective Communication');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (361, 'Stutter', 'v', 'Nói lắp', 'He used to stutter when speaking in public, but regular training helped him improve.', 'Unit 6: Effective Communication');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (362, 'Suggest', 'v', 'Gợi ý / Đề xuất', 'Experts suggest that children should limit their daily screen time to protect their eyes.', 'Unit 6: Effective Communication');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (363, 'Translate', 'v', 'Dịch / Biên dịch / Phiên dịch', 'This handy software can translate simple sentences from English into Vietnamese instantly.', 'Unit 6: Effective Communication');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (364, 'There is something to be said for', 'idiom', 'Có lý do chính đáng / Có điểm đáng khen / Có lợi thế', 'There is something to be said for living in a quiet rural town with fresh air.', 'Unit 6: Effective Communication');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (365, 'Needless to say', 'idiom', 'Rõ ràng là / Không cần phải nói cũng biết', 'Needless to say, regular physical exercise brings many benefits to your health.', 'Unit 6: Effective Communication');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (366, 'Have a say', 'idiom', 'Có tiếng nói / Có quyền tham gia quyết định', 'Citizens should have a say in major community projects that affect their neighborhood.', 'Unit 6: Effective Communication');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (367, 'When all is said and done', 'idiom', 'Sau tất cả / Rốt cuộc', 'When all is said and done, good health remains the most valuable treasure in life.', 'Unit 6: Effective Communication');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (368, 'Having said that', 'idiom', 'Tuy nhiên / Dù vậy', 'City life is very exciting; having said that, it can also be quite stressful.', 'Unit 6: Effective Communication');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (369, 'To say the least', 'idiom', 'Nói khiêm tốn là / Nói giảm nhẹ thì là', 'Finding a decent job after graduation was challenging, to say the least.', 'Unit 6: Effective Communication');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (370, 'You can say that again!', 'idiom', 'Hoàn toàn đồng ý! / Chuẩn không cần chỉnh!', 'When Tom said the exam was very tough, I replied, ''You can say that again!''', 'Unit 6: Effective Communication');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (371, 'That is to say', 'idiom', 'Tức là / Nói cách khác', 'Our company is expanding rapidly, that is to say, we need more qualified staff.', 'Unit 6: Effective Communication');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (372, 'Accommodation', 'n', 'Chỗ ở / Nơi lưu trú', 'Tourists should book their hotel accommodation in advance during the peak summer holiday season.', 'Unit 7: On the Move');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (373, 'Attraction', 'n', 'Điểm tham quan / Điểm thu hút du khách', 'The ancient temple has become a major tourist attraction in this coastal city.', 'Unit 7: On the Move');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (374, 'Community', 'n', 'Cộng đồng', 'Local community members worked together to clean the local beach last weekend.', 'Unit 7: On the Move');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (375, 'Countryside', 'n', 'Vùng nông thôn / Miền quê', 'Many city residents like to spend weekends in the countryside to enjoy fresh air.', 'Unit 7: On the Move');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (376, 'Destination', 'n', 'Điểm đến', 'Da Nang is a popular holiday destination for domestic and international travelers.', 'Unit 7: On the Move');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (377, 'Eco-tourism', 'n', 'Du lịch sinh thái', 'Eco-tourism helps protect natural habitats while providing financial support to local residents.', 'Unit 7: On the Move');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (378, 'Effect', 'n', 'Tác động / Ảnh hưởng', 'Excessive tourism can have a negative effect on the local natural environment.', 'Unit 7: On the Move');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (379, 'Facilities', 'n', 'Cơ sở vật chất / Tiện nghi', 'The university provides modern sports facilities such as a swimming pool and a gym.', 'Unit 7: On the Move');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (380, 'Identification', 'n', 'Giấy tờ tùy thân / Sự nhận diện', 'Passengers must show their personal identification before boarding an international flight.', 'Unit 7: On the Move');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (381, 'Inhabitant', 'n', 'Cư dân / Người dân', 'Every inhabitant in this mountain village welcomes visitors with warm hospitality.', 'Unit 7: On the Move');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (382, 'Itinerary', 'n', 'Lịch trình / Hành trình chuyến đi', 'The travel agent gave us a detailed itinerary for our five-day trip to Japan.', 'Unit 7: On the Move');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (383, 'Journey', 'n', 'Chuyến đi / Cuộc hành trình', 'The train journey through the countryside offered stunning views of green mountains.', 'Unit 7: On the Move');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (384, 'Landscape', 'n', 'Phong cảnh / Cảnh quan', 'Tourists were amazed by the breathtaking mountain landscape of the national park.', 'Unit 7: On the Move');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (385, 'Luggage', 'n', 'Hành lý', 'Please keep an eye on your luggage while waiting at the busy train station.', 'Unit 7: On the Move');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (386, 'Peak', 'n', 'Đỉnh / Thời kỳ cao điểm', 'Hotel room rates usually reach their peak during the summer holiday months.', 'Unit 7: On the Move');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (387, 'Tourism', 'n', 'Ngành du lịch / Hoạt động du lịch', 'International tourism brings significant financial income to many developing countries.', 'Unit 7: On the Move');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (388, 'Tourist', 'n', 'Khách du lịch / Du khách', 'Every summer, thousands of tourists visit this historical city to admire old buildings.', 'Unit 7: On the Move');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (389, 'Transport', 'n', 'Giao thông / Phương tiện giao thông', 'Using public transport like buses and trains can significantly reduce air pollution.', 'Unit 7: On the Move');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (390, 'Travel', 'n', 'Việc đi lại / Việc du lịch', 'Air travel has become much cheaper and more convenient over the past decade.', 'Unit 7: On the Move');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (391, 'Travelling', 'n', 'Việc đi du lịch / Việc đi lại', 'Travelling alone can teach young people how to be independent and solve problems.', 'Unit 7: On the Move');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (392, 'Trend', 'n', 'Xu hướng / Chiều hướng', 'There is a growing trend towards eco-friendly travel among younger generations.', 'Unit 7: On the Move');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (393, 'Trip', 'n', 'Chuyến đi', 'We took a memorable trip to the countryside during our summer holiday.', 'Unit 7: On the Move');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (394, 'Village', 'n', 'Ngôi làng / Làng quê', 'Many tourists enjoy visiting this peaceful village to experience traditional rural life.', 'Unit 7: On the Move');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (395, 'Adventurous', 'adj', 'Thích phiêu lưu / Mạo hiểm', 'Adventurous travellers often prefer hiking in the mountains rather than staying in hotels.', 'Unit 7: On the Move');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (396, 'Budget', 'adj', 'Tiết kiệm / Giá rẻ / Phù hợp túi tiền', 'Budget airlines allow more young people to travel abroad without spending much money.', 'Unit 7: On the Move');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (397, 'Breathtaking', 'adj', 'Ngoạn mục / Đẹp ngỡ ngàng', 'The view from the top of the mountain was truly breathtaking at sunrise.', 'Unit 7: On the Move');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (398, 'Coastal', 'adj', 'Thuộc ven biển / Duyên hải', 'Many coastal cities attract millions of visitors every year because of their beaches.', 'Unit 7: On the Move');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (399, 'Cosmopolitan', 'adj', 'Đa văn hóa / Mang tính quốc tế', 'London is a cosmopolitan city where you can meet people from all over the world.', 'Unit 7: On the Move');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (400, 'Diverse', 'adj', 'Đa dạng / Phong phú', 'The national park is home to a diverse range of plant and animal species.', 'Unit 7: On the Move');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (401, 'Flexible', 'adj', 'Linh hoạt', 'Having a flexible work schedule allows employees to balance their career and family.', 'Unit 7: On the Move');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (402, 'Foreign', 'adj', 'Nước ngoài / Ngoại quốc', 'Learning a foreign language helps students communicate effectively in international environments.', 'Unit 7: On the Move');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (403, 'Local', 'adj', 'Thuộc địa phương / Bản địa', 'Tourists should try the local food whenever they visit a new country.', 'Unit 7: On the Move');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (404, 'Luxurious', 'adj', 'Sang trọng / Xa hoa', 'They stayed at a luxurious resort near the beach during their summer vacation.', 'Unit 7: On the Move');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (405, 'Mountainous', 'adj', 'Có nhiều núi / Miền núi', 'Traveling through mountainous regions can be difficult because the roads are narrow and steep.', 'Unit 7: On the Move');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (406, 'Peaceful', 'adj', 'Yên bình / Thanh bình', 'Living in a peaceful countryside helps people reduce stress from busy city life.', 'Unit 7: On the Move');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (407, 'Picturesque', 'adj', 'Đẹp như tranh vẽ / Cổ kính đẹp mắt', 'The town is famous for its picturesque streets lined with historic houses and colorful flowers.', 'Unit 7: On the Move');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (408, 'Polluted', 'adj', 'Bị ô nhiễm', 'Many large cities suffer from polluted air caused by heavy traffic and factories.', 'Unit 7: On the Move');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (409, 'Quaint', 'adj', 'Cổ kính / Duyên dáng nét xưa', 'We had lunch in a quaint little café located in the old town center.', 'Unit 7: On the Move');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (410, 'Remote', 'adj', 'Xa xôi / Hẻo lánh', 'Children in remote areas often have limited access to modern educational facilities.', 'Unit 7: On the Move');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (411, 'Rough', 'adj', 'Gồ ghề / Biển động / Gian nan', 'The ferry trip was uncomfortable because the sea was extremely rough that day.', 'Unit 7: On the Move');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (412, 'Rural', 'adj', 'Thuộc nông thôn / Làng quê', 'Many young people leave rural areas to find better job opportunities in big cities.', 'Unit 7: On the Move');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (413, 'Scenic', 'adj', 'Có cảnh quan đẹp / Phong cảnh hữu tình', 'We drove along the scenic route by the coast to enjoy the ocean view.', 'Unit 7: On the Move');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (414, 'Stunning', 'adj', 'Tuyệt đẹp / Lộng lẫy ấn tượng', 'The hotel offers a stunning view of the ocean from every guest room.', 'Unit 7: On the Move');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (415, 'Tough', 'adj', 'Khó khăn / Gian nan', 'Climbing that steep mountain in bad weather was a tough challenge for the hikers.', 'Unit 7: On the Move');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (416, 'Traditional', 'adj', 'Truyền thống', 'People usually wear traditional clothes during special festivals to celebrate their cultural heritage.', 'Unit 7: On the Move');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (417, 'Unspoilt', 'adj', 'Hoang sơ / Còn nguyên vẹn nét tự nhiên', 'The island is known for its unspoilt beaches and clean, crystal-clear water.', 'Unit 7: On the Move');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (418, 'Urban', 'adj', 'Thuộc đô thị / Thành thị', 'Rapid urban development has led to traffic congestion and a shortage of green spaces.', 'Unit 7: On the Move');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (419, 'Affect', 'v', 'Ảnh hưởng đến / Tác động đến', 'Extreme weather conditions can negatively affect the tourism industry and local businesses.', 'Unit 7: On the Move');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (420, 'Fluctuate', 'v', 'Dao động / Biến động', 'The price of flight tickets tends to fluctuate depending on the travel season.', 'Unit 7: On the Move');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (421, 'Age', 'n', 'Thời đại / Tuổi tác', 'We are currently living in a digital age where technology changes our daily life.', 'Unit 8: Through the Ages');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (422, 'Archaeologist', 'n', 'Nhà khảo cổ học', 'The archaeologist discovered ancient pottery that provided valuable information about early human civilization.', 'Unit 8: Through the Ages');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (423, 'Century', 'n', 'Thế kỷ', 'This historic castle was built in the seventeenth century and remains well preserved.', 'Unit 8: Through the Ages');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (424, 'Decade', 'n', 'Thập kỷ', 'Over the past decade, public transport in this city has improved significantly.', 'Unit 8: Through the Ages');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (425, 'Era', 'n', 'Kỷ nguyên / Thời đại', 'The invention of the internet marked the beginning of a new technological era.', 'Unit 8: Through the Ages');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (426, 'Evidence', 'n', 'Bằng chứng / Dấu vết', 'Scientists found clear evidence that humans lived in this cave thousands of years ago.', 'Unit 8: Through the Ages');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (427, 'Excavation', 'n', 'Sự khai quật / Hoạt động khai quật', 'The excavation of the ancient tomb revealed many gold artifacts and historical treasures.', 'Unit 8: Through the Ages');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (428, 'Generation', 'n', 'Thế hệ', 'Parents should pass down traditional cultural values to the younger generation.', 'Unit 8: Through the Ages');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (429, 'The Middle Ages', 'n', 'Thời Trung Cổ', 'During the Middle Ages, many grand castles and stone cathedrals were built across Europe.', 'Unit 8: Through the Ages');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (430, 'Millennia', 'n', 'Các thiên niên kỷ / Hàng ngàn năm', 'These rock paintings have survived for several millennia despite severe weather conditions.', 'Unit 8: Through the Ages');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (431, 'Period', 'n', 'Giai đoạn / Thời kỳ', 'The country experienced a long period of economic growth after the major reform.', 'Unit 8: Through the Ages');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (432, 'Phase', 'n', 'Giai đoạn / Thời kỳ', 'The construction project has successfully entered its final phase ahead of schedule.', 'Unit 8: Through the Ages');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (433, 'Pioneer', 'n', 'Người tiên phong', 'Marie Curie was a pioneer in science whose research changed the medical world.', 'Unit 8: Through the Ages');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (434, 'Timeline', 'n', 'Tiến trình thời gian / Dòng thời gian', 'The history teacher drew a timeline on the board to illustrate important events.', 'Unit 8: Through the Ages');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (435, 'Ancient', 'adj', 'Cổ đại / Cổ xưa', 'Ancient monuments like the pyramids continue to attract millions of tourists every year.', 'Unit 8: Through the Ages');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (436, 'Chronological', 'adj', 'Theo trình tự thời gian', 'The textbook presents historical events in chronological order to help students learn easily.', 'Unit 8: Through the Ages');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (437, 'Consecutive', 'adj', 'Liên tiếp / Liền nhau', 'The team worked hard for three consecutive days to finish the scientific report.', 'Unit 8: Through the Ages');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (438, 'Historical', 'adj', 'Thuộc về lịch sử / Mang tính lịch sử', 'Visiting historical sites helps young people understand more about their national heritage.', 'Unit 8: Through the Ages');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (439, 'Imminent', 'adj', 'Sắp xảy ra / Cận kề', 'The local government warned residents about an imminent storm heading toward the coast.', 'Unit 8: Through the Ages');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (440, 'Middle-aged', 'adj', 'Trung niên / Độ tuổi trung niên', 'Middle-aged workers often seek more balance between their professional careers and family life.', 'Unit 8: Through the Ages');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (441, 'Nostalgic', 'adj', 'Hoài niệm / Nhớ về quá khứ', 'Listening to old songs makes many elderly people feel nostalgic about their youth.', 'Unit 8: Through the Ages');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (442, 'Prehistoric', 'adj', 'Tiền sử / Thuộc thời tiền sử', 'Prehistoric tools found in the cave show how early humans hunted for food.', 'Unit 8: Through the Ages');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (443, 'Prior (to)', 'adj', 'Trước / Trước khi', 'Prior to taking the final exam, students should review all their lecture notes carefully.', 'Unit 8: Through the Ages');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (444, 'Punctual', 'adj', 'Đúng giờ', 'It is important for job applicants to be punctual when attending an interview.', 'Unit 8: Through the Ages');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (445, 'Time-consuming', 'adj', 'Tốn nhiều thời gian / Mất thời gian', 'Doing scientific research by hand is a time-consuming process that requires great patience.', 'Unit 8: Through the Ages');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (446, 'Erode', 'v', 'Xói mòn / Ăn mòn', 'Heavy rains and strong winds continue to erode the soil along the riverbank.', 'Unit 8: Through the Ages');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (447, 'Infer', 'v', 'Suy ra / Luận ra', 'From the archaeological discoveries, researchers can infer how ancient communities lived and worked.', 'Unit 8: Through the Ages');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (448, 'Predate', 'v', 'Có trước / Xảy ra trước', 'Some stone tools found at the site predate the arrival of modern humans.', 'Unit 8: Through the Ages');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (449, 'Span', 'v', 'Kéo dài qua / Trải dài qua', 'His successful teaching career spanned more than three decades at the local university.', 'Unit 8: Through the Ages');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (450, 'In time', 'phrase', 'Kịp lúc / Kịp giờ', 'We arrived at the airport in time to catch our flight to Sydney.', 'Unit 8: Through the Ages');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (451, 'Lose track of time', 'phrase', 'Quên mất thời gian / Không để ý thời gian', 'I often lose track of time when I am reading an interesting book.', 'Unit 8: Through the Ages');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (452, 'On time', 'phrase', 'Đúng giờ', 'All students are expected to submit their weekly assignments on time.', 'Unit 8: Through the Ages');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (453, 'Save time', 'phrase', 'Tiết kiệm thời gian', 'Using online shopping services can save time for busy working parents.', 'Unit 8: Through the Ages');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (454, 'Spend time', 'phrase', 'Dành thời gian', 'Parents should spend time reading books and talking with their children every day.', 'Unit 8: Through the Ages');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (455, 'Take so long', 'phrase', 'Mất quá nhiều thời gian', 'Public transport should be improved because daily commuting should not take so long.', 'Unit 8: Through the Ages');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (456, 'The right time', 'phrase', 'Thời điểm thích hợp / Đúng lúc', 'University graduation is the right time for young people to plan their future careers.', 'Unit 8: Through the Ages');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (457, 'Chronologically', 'v', 'Theo trình tự thời gian', 'The events in the history museum are arranged chronologically to assist visitors.', 'Unit 8: Through the Ages');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (458, 'Formerly', 'v', 'Trước đây / Trước kia', 'This building was formerly a textile factory before becoming a modern art museum.', 'Unit 8: Through the Ages');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (459, 'Previously', 'v', 'Trước đó / Trước đây', 'He previously worked as a high school teacher before joining the research institute.', 'Unit 8: Through the Ages');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (460, 'Subsequently', 'v', 'Sau đó / Về sau', 'The company developed a new product and subsequently expanded into international markets.', 'Unit 8: Through the Ages');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (461, 'Agriculture', 'n', 'Nông nghiệp / Ngành nông nghiệp', 'Modern agriculture relies heavily on technology to increase crop yields and save water.', 'Unit 9: The Natural World');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (462, 'Animal kingdom', 'n', 'Giới động vật / Vương quốc động vật', 'Lions and tigers are among the most powerful predators in the animal kingdom.', 'Unit 9: The Natural World');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (463, 'Burrow', 'n', 'Hang (thỏ, chồn) / Hang đào dưới đất', 'Rabbits often dig a deep burrow in the ground to hide from predators.', 'Unit 9: The Natural World');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (464, 'Climate', 'n', 'Khí hậu', 'Human activities have caused significant changes in global climate over recent decades.', 'Unit 9: The Natural World');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (465, 'Crop(s)', 'n', 'Cây trồng / Hoa màu / Mùa màng', 'Severe droughts can destroy crops and lead to serious food shortages for local people.', 'Unit 9: The Natural World');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (466, 'Decline', 'n', 'Sự suy giảm / Sự sụt giảm', 'There has been a sharp decline in the population of wild tigers recently.', 'Unit 9: The Natural World');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (467, 'Den', 'n', 'Hang thú / Hang ổ', 'The mother bear protected her young cubs inside a warm den during winter.', 'Unit 9: The Natural World');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (468, 'Disaster', 'n', 'Thảm họa / Tai ương', 'The earthquake was a terrible natural disaster that destroyed hundreds of residential buildings.', 'Unit 9: The Natural World');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (469, 'Ecological balance', 'n', 'Sự cân bằng sinh thái', 'Protecting endangered predators is essential for maintaining a healthy ecological balance in nature.', 'Unit 9: The Natural World');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (470, 'Ecology', 'n', 'Sinh thái học / Hệ sinh thái', 'Students in environmental science classes learn about plant ecology and forest conservation.', 'Unit 9: The Natural World');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (471, 'Evolution', 'n', 'Sự tiến hóa', 'The evolution of bird species shows how animals adapt to changing natural environments.', 'Unit 9: The Natural World');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (472, 'Extinction', 'n', 'Sự tuyệt chủng', 'Many rare animals are now facing extinction due to habitat loss and illegal hunting.', 'Unit 9: The Natural World');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (473, 'Fauna', 'n', 'Hệ động vật / Quần thể động vật', 'The tropical rainforest is famous for its rich fauna, including rare birds and monkeys.', 'Unit 9: The Natural World');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (474, 'Flora', 'n', 'Hệ thực vật / Quần thể thực vật', 'The botanical garden contains a wonderful variety of native flora from Southeast Asia.', 'Unit 9: The Natural World');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (475, 'Genetics', 'n', 'Di truyền học', 'Modern genetics helps scientists develop stronger crops that can resist dangerous plant diseases.', 'Unit 9: The Natural World');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (476, 'Habitat', 'n', 'Môi trường sống / Nơi sinh sống', 'Deforestation destroys the natural habitat of wild animals and threatens their survival.', 'Unit 9: The Natural World');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (477, 'Human nature', 'n', 'Bản chất con người', 'It is human nature to seek comfort and connection with other people in society.', 'Unit 9: The Natural World');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (478, 'Insect', 'n', 'Côn trùng', 'Bees are an essential insect because they help pollinate flowers and agricultural crops.', 'Unit 9: The Natural World');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (479, 'Mother Nature', 'n', 'Mẹ thiên nhiên / Thiên nhiên tự nhiên', 'We must respect Mother Nature by keeping our oceans clean and planting more trees.', 'Unit 9: The Natural World');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (480, 'Pesticides', 'n', 'Thuốc trừ sâu', 'Farmers should limit the use of chemical pesticides to protect soil and water quality.', 'Unit 9: The Natural World');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (481, 'Predator', 'n', 'Động vật săn mồi / Kẻ săn mồi', 'The wolf is a skilled predator that hunts in packs across cold forest regions.', 'Unit 9: The Natural World');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (482, 'Prey', 'n', 'Con mồi', 'Small rodents are common prey for birds of prey like eagles and owls.', 'Unit 9: The Natural World');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (483, 'Repercussions', 'n', 'Hậu quả / Tác động tiêu cực', 'Overfishing in coastal waters can have serious repercussions for the entire marine ecosystem.', 'Unit 9: The Natural World');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (484, 'Scent', 'n', 'Mùi hương / Hương thơm / Mùi (động vật)', 'Dogs have an incredible sense of smell and can follow a scent for miles.', 'Unit 9: The Natural World');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (485, 'Species', 'n', 'Loài / Giống loài', 'Many unique animal species can only be found in the dense Amazon rainforest.', 'Unit 9: The Natural World');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (486, 'Soil', 'n', 'Đất trồng / Thổ nhưỡng', 'Healthy soil rich in nutrients is necessary for growing organic vegetables and fruits.', 'Unit 9: The Natural World');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (487, 'Vegetation', 'n', 'Thảm thực vật / Cây cỏ', 'The desert has very little vegetation because rainfall is extremely rare in that region.', 'Unit 9: The Natural World');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (488, 'Vermin', 'n', 'Động vật gây hại / Côn trùng gây hại', 'Farmers often use natural methods to protect their storage barns from rats and other vermin.', 'Unit 9: The Natural World');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (489, 'Weed', 'n', 'Cỏ dại', 'Gardeners need to remove every harmful weed regularly so vegetables can grow well.', 'Unit 9: The Natural World');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (490, 'Arid', 'adj', 'Khô cằn / Cằn cỗi (khí hậu, đất)', 'Very few farming activities can succeed in arid climates without modern irrigation systems.', 'Unit 9: The Natural World');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (491, 'Catastrophic', 'adj', 'Thảm khốc / Gây tai họa lớn', 'Climate change can cause catastrophic floods and storms that destroy thousands of homes.', 'Unit 9: The Natural World');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (492, 'Disastrous', 'adj', 'Tai hại / Thảm khốc', 'A lack of planning can lead to disastrous consequences for small businesses.', 'Unit 9: The Natural World');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (493, 'Domesticated', 'adj', 'Được thuần hóa / Đã thuần dưỡng', 'Dogs and cats are domesticated animals that have lived with humans for thousands of years.', 'Unit 9: The Natural World');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (494, 'Endangered', 'adj', 'Có nguy cơ tuyệt chủng', 'Many governments are working hard to protect endangered species from illegal hunting.', 'Unit 9: The Natural World');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (495, 'Extinct', 'adj', 'Tuyệt chủng', 'If we do not stop deforestation, many rare animals will soon become extinct.', 'Unit 9: The Natural World');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (496, 'Genetically-modified', 'adj', 'Biến đổi gen', 'Some farmers prefer genetically-modified crops because they can resist pests and diseases better.', 'Unit 9: The Natural World');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (497, 'Introduced', 'adj', 'Được du nhập / Ngoại lai', 'Introduced species can sometimes threaten local wildlife by competing for food and shelter.', 'Unit 9: The Natural World');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (498, 'Native', 'adj', 'Bản địa / Bản xứ', 'The government encourages people to plant native trees to protect the local environment.', 'Unit 9: The Natural World');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (499, 'Natural', 'adj', 'Tự nhiên / Thiên nhiên', 'Eating fresh food and getting natural sunlight can help improve your overall health.', 'Unit 9: The Natural World');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (500, 'Resistant', 'adj', 'Có sức đề kháng / Kháng cự / Chống chịu', 'Scientists are trying to develop crops that are resistant to dry weather and insect damage.', 'Unit 9: The Natural World');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (501, 'Semi-arid', 'adj', 'Bán khô hạn / Bán khô cằn', 'Farming is very difficult in semi-arid areas because there is very little rain throughout the year.', 'Unit 9: The Natural World');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (502, 'Tropical', 'adj', 'Nhiệt đới', 'Many tourists enjoy visiting tropical islands because of the warm weather and beautiful beaches.', 'Unit 9: The Natural World');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (503, 'Vulnerable', 'adj', 'Dễ bị tổn thương / Dễ bị ảnh hưởng', 'Elderly people and young children are especially vulnerable to extreme summer heat.', 'Unit 9: The Natural World');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (504, 'Wild', 'adj', 'Hoang dã / Tự nhiên', 'Pollution and human activities have destroyed the natural habitats of many wild animals.', 'Unit 9: The Natural World');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (505, 'Adapt', 'v', 'Thích nghi / Làm quen', 'Living abroad teaches students how to adapt to new cultures and lifestyles quickly.', 'Unit 9: The Natural World');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (506, 'Combat', 'v', 'Chiến đấu chống lại / Giải quyết / Ngăn chặn', 'The city has planted more trees along the streets to combat air pollution.', 'Unit 9: The Natural World');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (507, 'Cultivate', 'v', 'Trồng trọt / Trau dồi / Nuôi dưỡng', 'Schools should encourage children to read books in order to cultivate good study habits.', 'Unit 9: The Natural World');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (508, 'Eradicate', 'v', 'Xóa bỏ / Diệt trừ tận gốc', 'Modern vaccines have helped society eradicate several dangerous infectious diseases completely.', 'Unit 9: The Natural World');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (509, 'Evolve', 'v', 'Tiến hóa / Phát triển dần', 'Many species have evolved over millions of years to survive in harsh weather conditions.', 'Unit 9: The Natural World');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (510, 'Hibernate', 'v', 'Ngủ đông', 'Bears eat large amounts of food during autumn before they hibernate for the winter.', 'Unit 9: The Natural World');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (511, 'Tolerate', 'v', 'Chịu đựng / Chấp nhận / Khoan dung', 'Some desert plants can tolerate extreme heat and survive without water for months.', 'Unit 9: The Natural World');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (512, 'Asteroid', 'n', 'Tiểu hành tinh', 'Astronomers continuously track any large asteroid that might come close to our planet.', 'Unit 10: Reaching for the Skies');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (513, 'Astronaut', 'n', 'Phi hành gia', 'Every astronaut must complete rigorous physical and mental training before travelling into space.', 'Unit 10: Reaching for the Skies');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (514, 'Atmosphere', 'n', 'Khí quyển / Bầu không khí', 'Burning fossil fuels releases harmful gases into the atmosphere and increases global warming.', 'Unit 10: Reaching for the Skies');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (515, 'Cosmos', 'n', 'Vũ trụ', 'Advanced space telescopes allow scientists to discover distant stars throughout the cosmos.', 'Unit 10: Reaching for the Skies');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (516, 'Crater', 'n', 'Miệng hố / Miệng núi lửa', 'The surface of the moon is covered with huge craters caused by meteor impacts.', 'Unit 10: Reaching for the Skies');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (517, 'Debris', 'n', 'Mảnh vỡ / Tàn tích / Rác vụn', 'Volunteers gathered on the beach to clear plastic debris left behind by tourists.', 'Unit 10: Reaching for the Skies');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (518, 'Earth', 'n', 'Trái Đất', 'We must protect the Earth by reducing waste and using renewable energy sources.', 'Unit 10: Reaching for the Skies');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (519, 'Exploration', 'n', 'Sự thám hiểm / Sự khám phá', 'Space exploration has helped scientists develop new technologies that benefit people in daily life.', 'Unit 10: Reaching for the Skies');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (520, 'Explorer', 'n', 'Nhà thám hiểm / Người khám phá', 'The brave explorer travelled through deep jungles to document rare animal and plant species.', 'Unit 10: Reaching for the Skies');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (521, 'Galaxy', 'n', 'Thiên hà', 'Our solar system is just a tiny part of the vast Milky Way galaxy.', 'Unit 10: Reaching for the Skies');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (522, 'Gas', 'n', 'Khí / Chất khí / Khí đốt', 'Vehicles that run on natural gas produce fewer emissions than traditional petrol cars.', 'Unit 10: Reaching for the Skies');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (523, 'Gravity', 'n', 'Trọng lực / Lực hấp dẫn', 'Astronauts float inside their spaceship because there is very little gravity in space.', 'Unit 10: Reaching for the Skies');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (524, 'Horizon', 'n', 'Đường chân trời / Tầm nhìn / Tầm hiểu biết', 'Travelling to foreign countries helps young people expand their horizon and understand diverse cultures.', 'Unit 10: Reaching for the Skies');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (525, 'Launch', 'n', 'Sự phóng (tên lửa, tàu) / Sự ra mắt (sản phẩm)', 'Thousands of excited spectators gathered along the coast to watch the rocket launch.', 'Unit 10: Reaching for the Skies');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (526, 'Meteor', 'n', 'Sao băng', 'We sat outside on the grass at midnight to watch a bright meteor fall.', 'Unit 10: Reaching for the Skies');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (527, 'Moon', 'n', 'Mặt Trăng', 'The gravitational pull of the moon creates high and low ocean tides on Earth.', 'Unit 10: Reaching for the Skies');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (528, 'Ocean', 'n', 'Đại dương', 'Plastic waste in the ocean poses a serious threat to marine life every day.', 'Unit 10: Reaching for the Skies');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (529, 'Orbit', 'n', 'Quỹ đạo', 'The weather satellite was successfully placed into orbit around the Earth yesterday.', 'Unit 10: Reaching for the Skies');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (530, 'Outer space', 'n', 'Không gian vũ trụ / Ngoài không gian', 'Scientists send powerful telescopes into outer space to take clear pictures of distant stars.', 'Unit 10: Reaching for the Skies');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (531, 'Planet', 'n', 'Hành tinh', 'Mars is the fourth planet from the sun and shares some features with Earth.', 'Unit 10: Reaching for the Skies');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (532, 'Radiation', 'n', 'Bức xạ / Sự phóng xạ', 'Astronauts wear protective suits to shield themselves from dangerous solar radiation in space.', 'Unit 10: Reaching for the Skies');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (533, 'Rocket', 'n', 'Tên lửa', 'The new rocket carried scientific equipment and essential food supplies to the space station.', 'Unit 10: Reaching for the Skies');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (534, 'Satellite', 'n', 'Vệ tinh', 'We rely on communication satellites every day to make international phone calls and access internet.', 'Unit 10: Reaching for the Skies');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (535, 'Simulator', 'n', 'Thiết bị mô phỏng / Máy mô phỏng', 'Pilot trainees spend dozens of hours in a flight simulator before flying real aeroplanes.', 'Unit 10: Reaching for the Skies');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (536, 'Solar system', 'n', 'Hệ Mặt Trời', 'Students learn that there are eight major planets moving around the sun in our solar system.', 'Unit 10: Reaching for the Skies');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (537, 'Space', 'n', 'Không gian / Vũ trụ', 'Many nations are investing substantial financial resources into space research and satellite development.', 'Unit 10: Reaching for the Skies');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (538, 'Spacecraft', 'n', 'Tàu vũ trụ', 'The unmanned spacecraft landed safely on the red planet after a seven-month journey.', 'Unit 10: Reaching for the Skies');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (539, 'Space shuttle', 'n', 'Tàu con thoi', 'The space shuttle was designed to carry astronauts and heavy cargo into orbit repeatedly.', 'Unit 10: Reaching for the Skies');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (540, 'Space station', 'n', 'Trạm vũ trụ / Trạm không gian', 'Scientists from different nations work together on the International Space Station to conduct experiments.', 'Unit 10: Reaching for the Skies');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (541, 'Surface', 'n', 'Bề mặt', 'Water covers more than seventy percent of the total surface of our home planet.', 'Unit 10: Reaching for the Skies');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (542, 'Universe', 'n', 'Vũ trụ', 'Scientists believe the universe contains billions of galaxies that are constantly moving away from each other.', 'Unit 10: Reaching for the Skies');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (543, 'Weightlessness', 'n', 'Trạng thái không trọng lượng / Tình trạng không trọng lực', 'Prolonged exposure to weightlessness in space can weaken an astronaut''s muscles and bone density.', 'Unit 10: Reaching for the Skies');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (544, 'Commercial', 'adj', 'Thuộc về thương mại / Mang tính thương mại', 'The government has approved several commercial space flights for private citizens and wealthy tourists.', 'Unit 10: Reaching for the Skies');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (545, 'Cosmic', 'adj', 'Thuộc về vũ trụ', 'Astronauts need special shielding to protect their bodies from intense cosmic rays during long missions.', 'Unit 10: Reaching for the Skies');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (546, 'Extreme', 'adj', 'Khắc nghiệt / Cực độ / Cực kỳ', 'Many vulnerable animals cannot survive extreme weather events such as severe heatwaves or blizzards.', 'Unit 10: Reaching for the Skies');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (547, 'Gravitational', 'adj', 'Thuộc về trọng lực / Thuộc lực hấp dẫn', 'The gravitational force of the sun keeps all the planets moving in regular orbits.', 'Unit 10: Reaching for the Skies');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (548, 'Horizontal', 'adj', 'Nằm ngang', 'Draw a horizontal line across the page before you begin writing your essay notes.', 'Unit 10: Reaching for the Skies');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (549, 'Inevitable', 'adj', 'Không thể tránh khỏi / Tất yếu', 'Making mistakes is an inevitable part of learning any new foreign language or skill.', 'Unit 10: Reaching for the Skies');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (550, 'Lunar', 'adj', 'Thuộc về Mặt Trăng / Âm lịch', 'Many Asian families gather to celebrate the Lunar New Year with traditional home-cooked feasts.', 'Unit 10: Reaching for the Skies');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (551, 'Meteoric', 'adj', 'Thuộc về sao băng / Nhanh chóng, chớp nhoáng', 'The young singer enjoyed a meteoric rise to fame after her song became viral online.', 'Unit 10: Reaching for the Skies');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (552, 'Outer', 'adj', 'Bên ngoài / Ở phía ngoài', 'The outer layer of clothing helps keep hikers warm during freezing winter conditions.', 'Unit 10: Reaching for the Skies');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (553, 'Solar', 'adj', 'Thuộc về Mặt Trời / Năng lượng mặt trời', 'Installing solar panels on the roof can significantly reduce electricity bills for homeowners.', 'Unit 10: Reaching for the Skies');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (554, 'Terrestrial', 'adj', 'Trên cạn / Thuộc về Trái Đất', 'Elephants are currently the largest terrestrial mammals living on our planet today.', 'Unit 10: Reaching for the Skies');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (555, 'Toxic', 'adj', 'Độc hại / Gây độc', 'Factories must not release toxic chemicals into local rivers because they poison drinking water supplies.', 'Unit 10: Reaching for the Skies');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (556, 'Uninhabitable', 'adj', 'Không thể cư trú được / Không thể ở được', 'Due to rising temperatures and severe drought, some dry regions may become completely uninhabitable.', 'Unit 10: Reaching for the Skies');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (557, 'Universal', 'adj', 'Phổ biến / Phổ quát / Toàn cầu', 'Music is often called a universal language because people from every country can appreciate it.', 'Unit 10: Reaching for the Skies');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (558, 'Unmanned', 'adj', 'Không người lái / Tự hành', 'The space agency deployed an unmanned probe to gather soil samples from the distant asteroid.', 'Unit 10: Reaching for the Skies');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (559, 'Acclimatise', 'v', 'Thích nghi với khí hậu / Làm quen với môi trường mới', 'It usually takes travellers a few days to acclimatise to the high altitude in mountain areas.', 'Unit 10: Reaching for the Skies');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (560, 'Colonise', 'v', 'Định cư / Chiếm làm thuộc địa', 'Some visionary scientists believe that humans will colonise Mars within the next century.', 'Unit 10: Reaching for the Skies');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (561, 'Explore', 'v', 'Khám phá / Thám hiểm / Tìm hiểu', 'Students should explore different career paths during university before deciding on a permanent job.', 'Unit 10: Reaching for the Skies');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (562, 'Float', 'v', 'Nổi / Trôi nổi / Lơ lửng', 'In zero gravity conditions, small water droplets float freely through the air inside the cabin.', 'Unit 10: Reaching for the Skies');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (563, 'Orbit', 'v', 'Xoay quanh quỹ đạo / Đi theo quỹ đạo', 'Several international satellites orbit the Earth daily to monitor global weather patterns and forest fires.', 'Unit 10: Reaching for the Skies');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (564, 'Propel', 'v', 'Đẩy tới / Thúc đẩy', 'Powerful rocket engines burn liquid fuel to propel the spacecraft high into the upper atmosphere.', 'Unit 10: Reaching for the Skies');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (565, 'Rotate', 'v', 'Xoay tròn / Luân phiên', 'The Earth takes approximately twenty-four hours to rotate once completely on its own axis.', 'Unit 10: Reaching for the Skies');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (566, 'Sustain', 'v', 'Duy trì / Chống đỡ / Nuôi sống', 'Remote desert communities often struggle to find enough fresh water to sustain human life.', 'Unit 10: Reaching for the Skies');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (567, 'Simulate', 'v', 'Mô phỏng / Giả lập', 'Modern computer programs can accurately simulate extreme weather conditions to test bridge safety.', 'Unit 10: Reaching for the Skies');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (568, 'Undergo', 'v', 'Trải qua / Chịu đựng', 'All new employees must undergo specialized safety training before operating heavy machinery on site.', 'Unit 10: Reaching for the Skies');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (569, 'Balcony', 'n', 'Ban công', 'Our modern apartment has a small balcony where we grow herbs and enjoy our morning coffee.', 'Unit 11: Design and Innovation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (570, 'Brick', 'n', 'Gạch xây dựng', 'Traditional houses built from red clay bricks tend to stay cooler during hot summer days.', 'Unit 11: Design and Innovation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (571, 'Building', 'n', 'Tòa nhà / Công trình xây dựng', 'The city council plans to renovate several historic buildings in the town centre next year.', 'Unit 11: Design and Innovation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (572, 'Ceiling', 'n', 'Trần nhà / Mức trần', 'The new library features high ceilings and large windows that let in plenty of natural daylight.', 'Unit 11: Design and Innovation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (573, 'Concrete', 'n', 'Bê tông', 'Reinforced concrete is widely used in modern construction because of its strength and durability.', 'Unit 11: Design and Innovation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (574, 'Construction', 'n', 'Sự xây dựng / Ngành xây dựng / Công trình', 'The construction of the new subway line will significantly reduce daily traffic jams in the city.', 'Unit 11: Design and Innovation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (575, 'Cottage', 'n', 'Nhà nhỏ ở nông thôn / Nhà tranh', 'Many retired couples prefer to live in a cozy cottage in the peaceful countryside.', 'Unit 11: Design and Innovation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (576, 'Design', 'n', 'Thiết kế / Bản thiết kế', 'Good architectural design should combine aesthetic beauty with practical energy efficiency for residents.', 'Unit 11: Design and Innovation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (577, 'Device', 'n', 'Thiết bị / Dụng cụ', 'Smart mobile devices allow students to access educational materials and communicate anytime and anywhere.', 'Unit 11: Design and Innovation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (578, 'Elevator', 'n', 'Thang máy', 'Taking the stairs instead of the elevator is an easy way to stay active during workdays.', 'Unit 11: Design and Innovation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (579, 'Engineering', 'n', 'Ngành kỹ thuật / Kỹ nghệ', 'Studying civil engineering provides university graduates with excellent career opportunities worldwide.', 'Unit 11: Design and Innovation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (580, 'Frame', 'n', 'Khung / Khung sườn', 'The sturdy steel frame supports the heavy glass walls of the modern skyscraper.', 'Unit 11: Design and Innovation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (581, 'Gadget', 'n', 'Thiết bị nhỏ / Tiện ích công nghệ', 'Electronic gadgets like tablets and smartwatches have become an essential part of daily life.', 'Unit 11: Design and Innovation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (582, 'Housing', 'n', 'Nhà ở / Vấn đề nhà ở', 'The government needs to invest in affordable housing projects for low-income families in urban areas.', 'Unit 11: Design and Innovation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (583, 'Innovation', 'n', 'Sự đổi mới / Sáng kiến cải tiến', 'Technological innovation in renewable energy is crucial for reducing our dependence on fossil fuels.', 'Unit 11: Design and Innovation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (584, 'Invention', 'n', 'Phát minh / Sự phát minh', 'The invention of the internet has completely transformed how people communicate and conduct business.', 'Unit 11: Design and Innovation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (585, 'Landmark', 'n', 'Thắng cảnh / Biểu tượng kiến trúc / Cột mốc', 'The historical tower has become a famous landmark that attracts millions of foreign tourists annually.', 'Unit 11: Design and Innovation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (586, 'Lift shaft', 'n', 'Hố thang máy / Trục thang máy', 'Engineers carefully inspected the lift shaft to ensure the safety of the tall office building.', 'Unit 11: Design and Innovation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (587, 'Occupant', 'n', 'Người cư ngụ / Người ở', 'All occupants of the residential building were safely evacuated when the fire alarm sounded.', 'Unit 11: Design and Innovation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (588, 'Platform', 'n', 'Nền tảng / Sân ga / Bục giảng', 'Online learning platforms provide flexible study schedules for busy students and working adults.', 'Unit 11: Design and Innovation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (589, 'Quarry', 'n', 'Mỏ đá / Nơi khai thác đá', 'Limestone from a local quarry was used to build many traditional houses in the village.', 'Unit 11: Design and Innovation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (590, 'Residence', 'n', 'Nơi cư trú / Chỗ ở / Nhà ở', 'Many families prefer a quiet residence in the countryside rather than living in a crowded city.', 'Unit 11: Design and Innovation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (591, 'Skyscraper', 'n', 'Tòa nhà chọc trời / Tòa nhà cao tầng', 'The city centre is famous for its modern skyscrapers and busy shopping centres.', 'Unit 11: Design and Innovation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (592, 'Staircase', 'n', 'Cầu thang', 'The old house has a beautiful wooden staircase that leads up to the second floor.', 'Unit 11: Design and Innovation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (593, 'Steel', 'n', 'Thép', 'Steel is widely used in modern construction because it is strong and highly durable.', 'Unit 11: Design and Innovation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (594, 'Storage', 'n', 'Không gian lưu trữ / Kho lưu trữ / Sự cất giữ', 'Small apartments often lack enough storage space for clothes and household items.', 'Unit 11: Design and Innovation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (595, 'Structure', 'n', 'Công trình kiến trúc / Kết cấu / Cấu trúc', 'The bridge has a strong concrete structure designed to support heavy traffic every day.', 'Unit 11: Design and Innovation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (596, 'Tension', 'n', 'Sự căng thẳng / Lực căng / Độ căng', 'Practising yoga regularly can help office workers relieve mental tension after a stressful day.', 'Unit 11: Design and Innovation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (597, 'Timber', 'n', 'Gỗ xây dựng / Gỗ xẻ', 'Many eco-friendly houses are built using local timber instead of concrete and steel.', 'Unit 11: Design and Innovation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (598, 'Airy', 'adj', 'Thoáng mát / Thoáng đãng / Thoáng khí', 'Large glass windows make the living room bright and airy throughout the entire day.', 'Unit 11: Design and Innovation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (599, 'Conventional', 'adj', 'Thông thường / Theo tập quán / Truyền thống', 'Online learning has become a popular alternative to conventional classroom education for busy adults.', 'Unit 11: Design and Innovation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (600, 'Cosy', 'adj', 'Ấm cúng / Thoải mái', 'Our family loves spending cold winter evenings together in our cosy living room.', 'Unit 11: Design and Innovation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (601, 'Cramped', 'adj', 'Chật chội / Chật hẹp / Tù túng', 'Many young workers in large cities live in cramped rental apartments to save money.', 'Unit 11: Design and Innovation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (602, 'Curved', 'adj', 'Cong / Uốn cong', 'The modern museum features curved glass walls that allow plenty of natural sunlight inside.', 'Unit 11: Design and Innovation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (603, 'Disposable', 'adj', 'Dùng một lần', 'People should reduce their use of disposable plastic cups to help protect the environment.', 'Unit 11: Design and Innovation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (604, 'Domestic', 'adj', 'Trong nước / Nội địa / Gia đình', 'Domestic flights are usually more convenient than travelling long distances by train or bus.', 'Unit 11: Design and Innovation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (605, 'Exterior', 'adj', 'Bên ngoài / Ngoại thất', 'The exterior walls of the school were painted bright yellow to welcome new students.', 'Unit 11: Design and Innovation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (606, 'Functional', 'adj', 'Tiện dụng / Hữu dụng / Thiết thực', 'The new office furniture is not only modern and stylish but also highly functional.', 'Unit 11: Design and Innovation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (607, 'Futuristic', 'adj', 'Hiện đại / Mang tính tương lai', 'The new science centre has a futuristic design that attracts thousands of young visitors.', 'Unit 11: Design and Innovation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (608, 'High-rise', 'adj', 'Cao tầng', 'Living in high-rise apartment buildings has become very common for families in urban areas.', 'Unit 11: Design and Innovation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (609, 'Innovative', 'adj', 'Sáng tạo / Mang tính đổi mới', 'The company developed an innovative mobile app that helps students learn foreign languages effectively.', 'Unit 11: Design and Innovation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (610, 'Internal', 'adj', 'Bên trong / Nội bộ', 'The internal layout of the library was redesigned to provide more quiet study areas.', 'Unit 11: Design and Innovation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (611, 'Mass-produced', 'adj', 'Được sản xuất hàng loạt', 'Mass-produced clothes are usually affordable, but handmade garments often have higher quality.', 'Unit 11: Design and Innovation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (612, 'Modern', 'adj', 'Hiện đại / Tân thời', 'Modern technology allows employees to work flexibly from home without going to the office.', 'Unit 11: Design and Innovation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (613, 'Multi-storey', 'adj', 'Nhiều tầng', 'The local government built a multi-storey car park to reduce traffic congestion in the centre.', 'Unit 11: Design and Innovation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (614, 'Old-fashioned', 'adj', 'Cổ hủ / Lỗi thời / Cổ điển', 'Some elderly people still prefer old-fashioned methods of communication, such as writing handwritten letters.', 'Unit 11: Design and Innovation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (615, 'Ornate', 'adj', 'Trang trí công phu / Hoa mỹ / Cầu kỳ', 'The historical palace is famous for its ornate ceilings and beautiful gold decorations.', 'Unit 11: Design and Innovation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (616, 'Prefabricated', 'adj', 'Tiền chế / Đúc sẵn', 'Prefabricated houses can be assembled very quickly and help reduce overall construction costs.', 'Unit 11: Design and Innovation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (617, 'Single-storey', 'adj', 'Một tầng / Nhà trệt', 'Many retired couples prefer living in a single-storey house because there are no stairs.', 'Unit 11: Design and Innovation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (618, 'Spacious', 'adj', 'Rộng rãi / Rộng lớn / Thoáng đãng', 'The hotel offers spacious guest rooms with comfortable beds and lovely garden views.', 'Unit 11: Design and Innovation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (619, 'State-of-the-art', 'adj', 'Tối tân / Hiện đại nhất', 'The hospital is equipped with state-of-the-art medical devices to treat serious illnesses effectively.', 'Unit 11: Design and Innovation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (620, 'Traditional', 'adj', 'Truyền thống', 'Many Vietnamese families prepare traditional meals together during the annual Lunar New Year.', 'Unit 11: Design and Innovation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (621, 'Two-storey', 'adj', 'Hai tầng', 'They decided to purchase a comfortable two-storey house with a lovely backyard garden.', 'Unit 11: Design and Innovation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (622, 'Typical', 'adj', 'Điển hình / Tiêu biểu / Đặc trưng', 'A typical working day for most office workers starts around eight in the morning.', 'Unit 11: Design and Innovation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (623, 'Ultra-modern', 'adj', 'Cực kỳ hiện đại / Siêu hiện đại', 'The city recently opened an ultra-modern library featuring automated book borrowing systems.', 'Unit 11: Design and Innovation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (624, 'Activate', 'v', 'Kích hoạt / Khởi động', 'Customers must enter a secret code to activate their new credit card online.', 'Unit 11: Design and Innovation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (625, 'Automate', 'v', 'Tự động hóa', 'Modern factories automate repetitive assembly tasks to increase productivity and reduce mistakes.', 'Unit 11: Design and Innovation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (626, 'Build', 'v', 'Xây dựng', 'The local council plans to build a new community centre for young residents.', 'Unit 11: Design and Innovation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (627, 'Condemn', 'v', 'Lên án / Tuyên bố không an toàn (để dỡ bỏ)', 'City authorities had to condemn the old apartment block because of serious structural damage.', 'Unit 11: Design and Innovation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (628, 'Construct', 'v', 'Xây dựng / Kiến tạo', 'Engineers are working hard to construct a new railway line connecting the two cities.', 'Unit 11: Design and Innovation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (629, 'Decorate', 'v', 'Trang trí', 'Families often decorate their homes with colourful flowers and lights before the holiday season.', 'Unit 11: Design and Innovation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (630, 'Demolish', 'v', 'Phá hủy / Dỡ bỏ (công trình)', 'The city decided to demolish the abandoned warehouse to build a green public park.', 'Unit 11: Design and Innovation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (631, 'Design', 'v', 'Thiết kế', 'Architects should design modern houses that save energy and protect the natural environment.', 'Unit 11: Design and Innovation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (632, 'Develop', 'v', 'Phát triển / Mở rộng', 'Taking part in group projects helps students develop essential teamwork and communication skills.', 'Unit 11: Design and Innovation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (633, 'Devise', 'v', 'Nghĩ ra / Sáng chế / Đề ra', 'The research team worked diligently to devise an effective method for recycling plastic waste.', 'Unit 11: Design and Innovation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (634, 'Haul', 'v', 'Kéo mạnh / Vận chuyển (hàng nặng)', 'Large trucks are used to haul heavy construction materials to the building site.', 'Unit 11: Design and Innovation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (635, 'Hoist', 'v', 'Nâng lên / Kéo lên (bằng cần cẩu hoặc dây)', 'Construction workers used a crane to hoist the heavy steel beams onto the roof.', 'Unit 11: Design and Innovation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (636, 'Invent', 'v', 'Phát minh / Sáng chế', 'Scientists are trying to invent cleaner energy technologies to fight global climate change.', 'Unit 11: Design and Innovation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (637, 'Maintain', 'v', 'Duy trì / Bảo dưỡng', 'It is essential for busy people to maintain a healthy balance between work and rest.', 'Unit 11: Design and Innovation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (638, 'Occupy', 'v', 'Chiếm / Cư ngụ / Sử dụng (không gian)', 'Administrative offices occupy the top two floors of this tall commercial building.', 'Unit 11: Design and Innovation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (639, 'Reconstruct', 'v', 'Tái thiết / Xây dựng lại', 'The local government helped residents reconstruct their damaged houses after the severe flood.', 'Unit 11: Design and Innovation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (640, 'Renovate', 'v', 'Cải tạo / Trùng tu / Nâng cấp', 'The university received financial support to renovate its science laboratories and student library.', 'Unit 11: Design and Innovation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (641, 'Support', 'v', 'Ủng hộ / Nâng đỡ / Chống đỡ', 'Parents should always support their children when they encounter difficult challenges at school.', 'Unit 11: Design and Innovation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (642, 'Trigger', 'v', 'Gây ra / Kích hoạt / Khơi mào', 'Severe air pollution can trigger serious breathing difficulties for elderly people and young children.', 'Unit 11: Design and Innovation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (643, 'Automatic pilot', 'n', 'Chế độ lái tự động', 'The aircraft flew on automatic pilot while the crew monitored navigation instruments carefully.', 'Unit 12: Information Technology');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (644, 'Computerisation', 'n', 'Sự tin học hóa / Sự vi tính hóa', 'The computerisation of library records has made finding books much faster for students.', 'Unit 12: Information Technology');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (645, 'Connection', 'n', 'Sự kết nối / Đường truyền / Mối quan hệ', 'Students need a stable internet connection to join online lectures and submit assignments.', 'Unit 12: Information Technology');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (646, 'Data', 'n', 'Dữ liệu / Số liệu', 'Researchers analysed collected data carefully before publishing the final report on health trends.', 'Unit 12: Information Technology');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (647, 'Device', 'n', 'Thiết bị / Dụng cụ', 'A smartphone is a versatile electronic device that helps people stay connected anywhere.', 'Unit 12: Information Technology');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (648, 'Function', 'n', 'Chức năng / Công dụng', 'The main function of this mobile application is to help users manage daily expenses.', 'Unit 12: Information Technology');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (649, 'Gadget', 'n', 'Thiết bị tiện ích / Đồ công nghệ', 'A smartwatch is a popular electronic gadget that tracks your daily physical activities.', 'Unit 12: Information Technology');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (650, 'The Internet', 'n', 'Mạng Internet', 'The Internet allows students around the world to access rich educational resources easily.', 'Unit 12: Information Technology');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (651, 'Keyboard', 'n', 'Bàn phím', 'She prefers using an ergonomic keyboard to type comfortably without getting tired wrists.', 'Unit 12: Information Technology');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (652, 'Keypad', 'n', 'Bàn phím số / Bàn phím nhỏ', 'Employees must enter their identification number on the keypad to enter the office.', 'Unit 12: Information Technology');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (653, 'Laptop (computer)', 'n', 'Máy tính xách tay', 'Most university students use a laptop (computer) to research study materials and write essays.', 'Unit 12: Information Technology');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (654, 'The latest', 'n', 'Cái mới nhất / Tin tức mới nhất', 'Young consumers are often eager to purchase the latest in mobile phone technology.', 'Unit 12: Information Technology');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (655, 'Memory', 'n', 'Bộ nhớ (máy tính) / Trí nhớ', 'Her smartphone does not have enough memory to store thousands of high-quality photographs.', 'Unit 12: Information Technology');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (656, 'Monitor', 'n', 'Màn hình máy tính / Thiết bị theo dõi', 'Looking at a bright computer monitor for many hours can cause severe eye fatigue.', 'Unit 12: Information Technology');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (657, 'Patent', 'n', 'Bằng sáng chế', 'The inventor was granted an international patent for her energy-saving solar heating system.', 'Unit 12: Information Technology');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (658, 'Program', 'n', 'Chương trình máy tính / Chương trình', 'He installed a new antivirus program to protect his laptop against online security threats.', 'Unit 12: Information Technology');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (659, 'Prototype', 'n', 'Nguyên mẫu / Bản mẫu thử nghiệm', 'Engineers built an initial prototype of the electric vehicle before starting mass production.', 'Unit 12: Information Technology');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (660, 'Remote control', 'n', 'Thiết bị điều khiển từ xa', 'She used the remote control to turn on the television and adjust the volume.', 'Unit 12: Information Technology');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (661, 'Silicon chip', 'n', 'Vi mạch silicon / Chip silicon', 'A tiny silicon chip inside each smartphone processes millions of digital commands every second.', 'Unit 12: Information Technology');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (662, 'Technology', 'n', 'Công nghệ / Kỹ thuật', 'Modern technology has transformed how people learn, communicate, and work in everyday life.', 'Unit 12: Information Technology');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (663, 'Telecommunications', 'n', 'Ngành viễn thông / Hệ thống viễn thông', 'Rapid improvements in telecommunications enable people to communicate instantly across different countries.', 'Unit 12: Information Technology');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (664, 'Vision', 'n', 'Tầm nhìn / Định hướng / Thị lực', 'The company founder had a clear vision for creating sustainable and eco-friendly products.', 'Unit 12: Information Technology');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (665, 'Wireless connection', 'n', 'Kết nối không dây', 'The university library provides a fast wireless connection for students doing research online.', 'Unit 12: Information Technology');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (666, 'Compact', 'adj', 'Nhỏ gọn / Tinh gọn', 'This compact digital camera is light and convenient to carry during long vacation trips.', 'Unit 12: Information Technology');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (667, 'Computerised', 'adj', 'Được vi tính hóa / Điều khiển bằng máy tính', 'The hospital installed a computerised database to manage patient appointments and medical histories.', 'Unit 12: Information Technology');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (668, 'Cutting-edge', 'adj', 'Tiên tiến nhất / Hiện đại bậc nhất', 'The laboratory uses cutting-edge technology to develop effective medical treatments for rare diseases.', 'Unit 12: Information Technology');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (669, 'Cyber', 'adj', 'Thuộc về mạng / Không gian mạng', 'Financial institutions must strengthen cyber security measures to protect client accounts against online fraud.', 'Unit 12: Information Technology');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (670, 'Dated', 'adj', 'Lỗi thời / Cũ kỹ', 'The school library decided to replace dated textbooks with up-to-date digital learning resources.', 'Unit 12: Information Technology');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (671, 'Digital', 'adj', 'Kỹ thuật số', 'Digital media allows students to access learning materials anytime using their mobile phones.', 'Unit 12: Information Technology');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (672, 'Labour-saving', 'adj', 'Tiết kiệm sức lao động / Giảm bớt công sức', 'Labour-saving household appliances like washing machines give busy families more time to relax.', 'Unit 12: Information Technology');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (673, 'Portable', 'adj', 'Di động / Dễ mang theo', 'A portable laptop enables employees to work productively while travelling on public transport.', 'Unit 12: Information Technology');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (674, 'State-of-the-art', 'adj', 'Tối tân / Hiện đại nhất', 'The new sports centre has state-of-the-art exercise equipment for athletes and local residents.', 'Unit 12: Information Technology');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (675, 'Up-to-date', 'adj', 'Hợp thời / Được cập nhật mới nhất', 'Medical professionals must read research articles regularly to maintain up-to-date knowledge of treatments.', 'Unit 12: Information Technology');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (676, 'User-friendly', 'adj', 'Thân thiện với người dùng / Dễ sử dụng', 'The learning app features a user-friendly interface that makes studying English enjoyable for beginners.', 'Unit 12: Information Technology');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (677, 'Virtual', 'adj', 'Ảo / Trực tuyến', 'Virtual classrooms allow international students to attend lectures without travelling to another country.', 'Unit 12: Information Technology');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (678, 'Wireless connection', 'adj', '(Thuộc về) kết nối không dây / Không dây', 'Slow wireless connection speeds can cause frustrating delays during live online video conferences.', 'Unit 12: Information Technology');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (679, 'Access', 'v', 'Truy cập / Tiếp cận', 'Students can easily access online reference books using their university library card.', 'Unit 12: Information Technology');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (680, 'Connect', 'v', 'Kết nối / Liên kết', 'Social media platforms enable users to connect with childhood friends living far away.', 'Unit 12: Information Technology');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (681, 'Download', 'v', 'Tải xuống / Tải về', 'Learners can download useful podcasts to practice English listening skills during their daily commute.', 'Unit 12: Information Technology');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (682, 'Display', 'v', 'Hiển thị / Trưng bày', 'The digital timetable displays accurate train departures and platform details for daily commuters.', 'Unit 12: Information Technology');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (683, 'Envisage', 'v', 'Hình dung / Dự kiến / Lường trước', 'Urban planners envisage that electric buses will replace diesel vehicles within the next decade.', 'Unit 12: Information Technology');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (684, 'Operate', 'v', 'Vận hành / Điều khiển / Hoạt động', 'Factory workers receive thorough safety training before learning how to operate heavy machinery.', 'Unit 12: Information Technology');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (685, 'Revolutionise', 'v', 'Cách mạng hóa / Đổi mới hoàn toàn', 'Advancements in renewable technology will revolutionise the way cities generate and use clean electricity.', 'Unit 12: Information Technology');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (686, 'Scroll', 'v', 'Cuộn (màn hình)', 'Users can scroll down the web page to read customer feedback and product ratings.', 'Unit 12: Information Technology');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (687, 'Speculate', 'v', 'Suy đoán / Dự đoán', 'Scientists speculate that artificial intelligence will transform many daily jobs in the near future.', 'Unit 12: Information Technology');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (688, 'Store', 'v', 'Lưu trữ / Tích trữ', 'Modern smartphones can store thousands of photos and documents without running out of memory.', 'Unit 12: Information Technology');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (689, 'Surpass', 'v', 'Vượt qua / Vượt trội hơn', 'Online shopping sales are expected to surpass traditional retail sales in the coming years.', 'Unit 12: Information Technology');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (690, 'Automatically', 'v', 'Tự động / Một cách tự động', 'Smart devices can automatically save data to the cloud whenever they connect to Wi-Fi.', 'Unit 12: Information Technology');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (691, 'Attitude', 'n', 'Thái độ / Quan điểm', 'Having a positive attitude towards learning helps students achieve better academic results.', 'Unit 13: The Modern World');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (692, 'Brand', 'n', 'Thương hiệu / Nhãn hàng', 'Many young consumers prefer to buy clothes from a well-known international brand.', 'Unit 13: The Modern World');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (693, 'Culture', 'n', 'Văn hóa', 'Traveling abroad allows people to experience a different culture and taste traditional local foods.', 'Unit 13: The Modern World');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (694, 'Cycle', 'n', 'Chu kỳ / Chu trình / Vòng tuần hoàn', 'Recycling waste paper helps create a sustainable cycle that protects natural forest resources.', 'Unit 13: The Modern World');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (695, 'Demographics', 'n', 'Nhân khẩu học / Số liệu nhân khẩu', 'Changes in demographics show that many developed countries are facing an aging workforce.', 'Unit 13: The Modern World');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (696, 'Development', 'n', 'Sự phát triển', 'Rapid economic development has greatly improved living standards for many families in rural areas.', 'Unit 13: The Modern World');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (697, 'Diversity', 'n', 'Sự đa dạng', 'Cultural diversity brings fresh ideas and unique perspectives to modern international workplaces.', 'Unit 13: The Modern World');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (698, 'Globalisation', 'n', 'Toàn cầu hóa', 'Globalisation makes it easier for companies to trade products and services across international borders.', 'Unit 13: The Modern World');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (699, 'Hindsight', 'n', 'Sự nhận thức muộn màng / Sự nhìn lại sau sự việc', 'With hindsight, the government realized that investing in public healthcare was extremely necessary.', 'Unit 13: The Modern World');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (700, 'Icon', 'n', 'Biểu tượng / Hình tượng', 'The Eiffel Tower has become a famous global icon representing French culture and history.', 'Unit 13: The Modern World');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (701, 'Identity', 'n', 'Bản sắc / Danh tính', 'Traditional festivals help young generations preserve their national identity and cultural heritage.', 'Unit 13: The Modern World');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (702, 'Implication', 'n', 'Hệ quả / Hàm ý / Tác động', 'The research paper discussed the serious social implications of high youth unemployment rates.', 'Unit 13: The Modern World');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (703, 'Impact', 'n', 'Tác động / Sự ảnh hưởng', 'Air pollution has a harmful impact on human health and the local environment.', 'Unit 13: The Modern World');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (704, 'Increase', 'n', 'Sự gia tăng / Sự tăng lên', 'There has been a sharp increase in the number of electric cars on city roads.', 'Unit 13: The Modern World');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (705, 'Influence', 'n', 'Sự ảnh hưởng / Tác động', 'Parents have a strong influence on the daily eating habits of their young children.', 'Unit 13: The Modern World');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (706, 'Industry', 'n', 'Ngành công nghiệp', 'The tourism industry provides millions of jobs and supports local businesses in coastal towns.', 'Unit 13: The Modern World');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (707, 'Isolation', 'n', 'Sự cô lập / Sự cách ly', 'Working remotely from home for a long time can lead to feelings of social isolation.', 'Unit 13: The Modern World');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (708, 'Joint venture', 'n', 'Công ty liên doanh / Sự liên doanh', 'The two technology firms established a joint venture to build modern electric vehicle batteries.', 'Unit 13: The Modern World');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (709, '(have a) monopoly', 'n', 'Độc quyền / Thế độc quyền', 'A single airline should not have a monopoly over flights between the two major cities.', 'Unit 13: The Modern World');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (710, 'Market', 'n', 'Thị trường / Chợ', 'Organic food has become increasingly popular in the domestic grocery market this year.', 'Unit 13: The Modern World');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (711, 'Modernisation', 'n', 'Sự hiện đại hóa', 'The modernisation of public transport has reduced travel time and traffic jams in the city.', 'Unit 13: The Modern World');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (712, 'Multiculturalism', 'n', 'Chủ nghĩa đa văn hóa / Sự đa dạng văn hóa', 'Multiculturalism helps people from different backgrounds learn to live and work peacefully together.', 'Unit 13: The Modern World');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (713, 'Percentage', 'n', 'Tỷ lệ phần trăm', 'A large percentage of college graduates choose to work in big metropolitan areas.', 'Unit 13: The Modern World');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (714, 'Population', 'n', 'Dân số', 'The world population is growing quickly, which puts heavy pressure on natural resources.', 'Unit 13: The Modern World');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (715, 'Prediction', 'n', 'Sự dự đoán / Dự báo', 'Experts made an accurate prediction about the growth of renewable energy sources last year.', 'Unit 13: The Modern World');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (716, 'Projection', 'n', 'Sự dự báo / Số liệu dự tính', 'According to the economic projection, the city will experience steady job growth next decade.', 'Unit 13: The Modern World');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (717, 'Proportion', 'n', 'Tỷ lệ / Phần', 'A high proportion of the family budget is spent on fresh food and education.', 'Unit 13: The Modern World');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (718, 'Rate', 'n', 'Tỷ lệ / Tốc độ', 'The unemployment rate among young adults has decreased significantly over the past two years.', 'Unit 13: The Modern World');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (719, 'Statistics', 'n', 'Số liệu thống kê / Thống kê', 'Official statistics show that public library visits have increased steadily across the country.', 'Unit 13: The Modern World');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (720, 'Trend', 'n', 'Xu hướng / Trào lưu', 'There is a growing trend of people using bicycles for daily travel to work.', 'Unit 13: The Modern World');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (721, 'Ageing', 'adj', 'Lão hóa / Già hóa', 'An ageing population requires the government to spend more money on pensions and healthcare.', 'Unit 13: The Modern World');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (722, 'Current', 'adj', 'Hiện tại / Hiện hành', 'Under the current educational system, students must take final examinations at age eighteen.', 'Unit 13: The Modern World');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (723, 'Demographic', 'adj', 'Thuộc nhân khẩu học', 'Recent demographic trends show that young families are moving away from crowded downtown areas.', 'Unit 13: The Modern World');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (724, 'Elderly', 'adj', 'Cao tuổi / Lớn tuổi', 'Many communities provide free health check-ups and home care services for elderly citizens.', 'Unit 13: The Modern World');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (725, 'Ethnic', 'adj', 'Thuộc dân tộc / Dân tộc', 'The festival celebrates traditional music, colorful clothes, and foods from different ethnic groups.', 'Unit 13: The Modern World');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (726, 'Exotic', 'adj', 'Kỳ lạ / Độc lạ / Ngoại lai', 'Tourists love visiting the botanical garden to see exotic flowers and tropical plants.', 'Unit 13: The Modern World');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (727, 'Global', 'adj', 'Toàn cầu', 'Climate change is a global issue that requires close cooperation between all countries.', 'Unit 13: The Modern World');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (728, 'Local', 'adj', 'Địa phương / Cục bộ', 'Buying groceries at the local market helps support small farmers and reduces transport pollution.', 'Unit 13: The Modern World');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (729, 'Long-term', 'adj', 'Dài hạn / Lâu dài', 'Investing in clean public transport brings long-term benefits to both the environment and society.', 'Unit 13: The Modern World');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (730, 'Mid-term', 'adj', 'Trung hạn / Giữa kỳ', 'The university students are preparing carefully for their mid-term examinations in mathematics next week.', 'Unit 13: The Modern World');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (731, 'Multicultural', 'adj', 'Đa văn hóa', 'Living in a multicultural society helps people become more open-minded and respectful toward others.', 'Unit 13: The Modern World');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (732, 'Productive', 'adj', 'Năng suất / Hiệu quả', 'Taking short rest breaks during long study sessions helps students remain energetic and productive.', 'Unit 13: The Modern World');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (733, 'Sceptical', 'adj', 'Hoài nghi / Nghi ngờ', 'Many local residents are sceptical about the government''s plan to lower housing prices soon.', 'Unit 13: The Modern World');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (734, 'Short-term', 'adj', 'Ngắn hạn', 'Fast food gives short-term energy but does not provide adequate nutrition for growing children.', 'Unit 13: The Modern World');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (735, 'Subsequent', 'adj', 'Sau đó / Tiếp theo', 'The initial project was successful, and subsequent studies confirmed that the method worked well.', 'Unit 13: The Modern World');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (736, 'Wealthy', 'adj', 'Giàu có', 'Many wealthy business owners donate money to build hospitals and schools in poor areas.', 'Unit 13: The Modern World');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (737, 'Worldwide', 'adj', 'Toàn cầu / Khắp thế giới', 'The English language has gained worldwide popularity as a common tool for international communication.', 'Unit 13: The Modern World');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (738, 'Compound', 'v', 'Làm trầm trọng thêm', 'Severe traffic delays only compound the stress that daily commuters experience on busy mornings.', 'Unit 13: The Modern World');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (739, 'Contribute', 'v', 'Đóng góp / Góp phần', 'Regular physical exercise and healthy meals contribute directly to better mental and physical well-being.', 'Unit 13: The Modern World');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (740, 'Decline', 'v', 'Giảm / Suy giảm / Từ chối', 'The number of young people who read printed newspapers continues to decline each year.', 'Unit 13: The Modern World');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (741, 'Diminish', 'v', 'Làm giảm / Suy giảm / Thu nhỏ', 'Lack of sleep will diminish your ability to focus and perform well at school.', 'Unit 13: The Modern World');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (742, 'Dominate', 'v', 'Thống trị / Chi phối', 'A few large multinational corporations dominate the global smartphone and technology industry today.', 'Unit 13: The Modern World');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (743, 'Dwindle', 'v', 'Thu hẹp / Giảm dần / Hao mòn', 'Natural fresh water supplies begin to dwindle during the dry summer months in this region.', 'Unit 13: The Modern World');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (744, 'Factor', 'v', 'Tính đến / Đưa vào tính toán', 'City planners must factor the rising population into their new public transportation projects.', 'Unit 13: The Modern World');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (745, 'Indicate', 'v', 'Chỉ ra / Cho thấy / Biểu thị', 'Recent environmental reports indicate that air quality in large cities has improved slightly.', 'Unit 13: The Modern World');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (746, 'Merge', 'v', 'Sáp nhập / Hợp nhất', 'The two local companies decided to merge to expand their reach across international markets.', 'Unit 13: The Modern World');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (747, 'Migrate', 'v', 'Di cư', 'Many rural workers migrate to industrial cities in search of better job opportunities.', 'Unit 13: The Modern World');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (748, 'Benefit', 'n', 'Lợi ích', 'Regular exercise offers many health benefits, including better sleep and reduced daily stress.', 'Unit 14: Urbanisation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (749, 'Challenge', 'n', 'Thách thức / Thử thách', 'Affordable housing is a major challenge for young people moving to metropolitan cities.', 'Unit 14: Urbanisation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (750, 'Compromise', 'n', 'Sự thỏa hiệp / Thỏa hiệp', 'Both sides reached a fair compromise to solve the conflict over working hours peacefully.', 'Unit 14: Urbanisation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (751, 'Difficulty', 'n', 'Sự khó khăn / Khó khăn', 'International students often face great difficulty adapting to a new educational and cultural environment.', 'Unit 14: Urbanisation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (752, 'Dilemma', 'n', 'Tình thế tiến thoái lưỡng nan / Vấn đề nan giải', 'Governments face a difficult dilemma between protecting nature and encouraging rapid economic development.', 'Unit 14: Urbanisation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (753, 'Inhabitant', 'n', 'Cư dân / Người dân', 'Every inhabitant of this historic neighborhood takes pride in keeping the public streets clean.', 'Unit 14: Urbanisation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (754, 'Infrastructure', 'n', 'Cơ sở hạ tầng', 'Investing in transport infrastructure is essential for supporting sustainable economic growth in developing nations.', 'Unit 14: Urbanisation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (755, 'Isolation', 'n', 'Sự cô lập / Tình trạng biệt lập', 'Living in remote countryside areas can sometimes cause a sense of social isolation.', 'Unit 14: Urbanisation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (756, 'Issue', 'n', 'Vấn đề', 'Plastic waste in the ocean has become an urgent environmental issue for many nations.', 'Unit 14: Urbanisation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (757, 'Megacity', 'n', 'Siêu đô thị', 'Tokyo is a famous megacity known for its efficient public transit and dense population.', 'Unit 14: Urbanisation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (758, 'Migrant', 'n', 'Người di cư', 'The city center attracts thousands of migrant workers looking for higher wages each year.', 'Unit 14: Urbanisation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (759, 'Obstacle', 'n', 'Trở ngại / Rào cản', 'High tuition fees remain a major obstacle for students from low-income rural families.', 'Unit 14: Urbanisation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (760, 'Overpopulation', 'n', 'Sự bùng nổ dân số / Quá tải dân số', 'Overpopulation in urban areas puts immense pressure on public hospitals, schools, and transport systems.', 'Unit 14: Urbanisation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (761, 'Population', 'n', 'Dân số', 'The growing urban population needs more affordable housing and convenient public transportation facilities.', 'Unit 14: Urbanisation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (762, 'Poverty', 'n', 'Sự nghèo đói / Cảnh nghèo khó', 'Quality education and skill training are effective tools to lift young families out of poverty.', 'Unit 14: Urbanisation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (763, 'Resolution', 'n', 'Giải pháp / Nghị quyết / Sự giải quyết', 'The committee worked hard to find a peaceful resolution to the neighborhood traffic dispute.', 'Unit 14: Urbanisation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (764, 'Setback', 'n', 'Sự thoái lui / Trở ngại / Trục trặc', 'The unexpected budget reduction was a temporary setback for the new public transport project.', 'Unit 14: Urbanisation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (765, 'Slum', 'n', 'Khu ổ chuột', 'The city government is building affordable modern apartments to replace crowded slum areas.', 'Unit 14: Urbanisation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (766, 'Solution', 'n', 'Giải pháp / Cách giải quyết', 'Using renewable solar energy is a practical solution to reduce harmful greenhouse gas emissions.', 'Unit 14: Urbanisation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (767, 'Tolerance', 'n', 'Sự khoan dung / Lòng bao dung / Sức chịu đựng', 'Living in a big diverse city helps young students develop tolerance toward different cultural traditions.', 'Unit 14: Urbanisation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (768, 'Traffic', 'n', 'Giao thông', 'Heavy traffic during rush hours causes severe stress for commuters in most major cities.', 'Unit 14: Urbanisation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (769, 'Urbanisation', 'n', 'Sự đô thị hóa', 'Rapid urbanisation has led to economic growth but also created serious environmental challenges.', 'Unit 14: Urbanisation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (770, 'Adequate', 'adj', 'Đầy đủ / Thích đáng', 'Every student requires an adequate amount of sleep each night to perform well at school.', 'Unit 14: Urbanisation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (771, 'Basic', 'adj', 'Cơ bản / Nền tảng', 'Access to clean drinking water and medical care is a basic need for every citizen.', 'Unit 14: Urbanisation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (772, 'Booming', 'adj', 'Phát triển mạnh / Đang bùng nổ', 'The booming technology sector has created thousands of high-paying jobs for young graduates.', 'Unit 14: Urbanisation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (773, 'Catastrophic', 'adj', 'Thảm họa / Thảm khốc', 'Severe flooding caused catastrophic damage to homes and public infrastructure in coastal areas.', 'Unit 14: Urbanisation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (774, 'Crowded', 'adj', 'Đông đúc', 'During rush hour, crowded trains and buses make daily commuting exhausting for city workers.', 'Unit 14: Urbanisation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (775, 'Decent', 'adj', 'Tử tế / Đàng hoàng / Thích hợp', 'Everyone deserves access to a decent home and safe working conditions in modern society.', 'Unit 14: Urbanisation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (776, 'Developing', 'adj', 'Đang phát triển', 'Many developing countries are investing heavily in renewable energy to power their growing industries.', 'Unit 14: Urbanisation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (777, 'Double-edged', 'adj', 'Hai lưỡi / Vừa có lợi vừa có hại', 'Tourism is a double-edged sword that generates revenue but can harm the natural environment.', 'Unit 14: Urbanisation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (778, 'Isolated', 'adj', 'Bị cô lập / Tách biệt', 'Many isolated mountain villages still lack reliable internet access and modern healthcare facilities.', 'Unit 14: Urbanisation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (779, 'One-sided', 'adj', 'Phiến diện / Một chiều', 'The news article presented a one-sided view of the debate without mentioning other opinions.', 'Unit 14: Urbanisation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (780, 'Long-sighted', 'adj', 'Nhìn xa trông rộng / Viễn thị', 'A long-sighted government invests heavily in early childhood education for future economic prosperity.', 'Unit 14: Urbanisation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (781, 'Long-term', 'adj', 'Dài hạn / Lâu dài', 'Regular exercise offers long-term health benefits and protects the human body from chronic diseases.', 'Unit 14: Urbanisation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (782, 'Overpriced', 'adj', 'Quá đắt / Giá quá cao', 'Apartments in the city center are often overpriced and unaffordable for young college graduates.', 'Unit 14: Urbanisation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (783, 'Overworked', 'adj', 'Quá tải công việc / Làm việc quá sức', 'Overworked healthcare employees often experience severe exhaustion due to long working hours.', 'Unit 14: Urbanisation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (784, 'Pressing', 'adj', 'Cấp bách / Cấp thiết', 'Finding clean drinking water remains a pressing problem for many rural communities today.', 'Unit 14: Urbanisation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (785, 'Rural', 'adj', 'Thuộc nông thôn / Vùng quê', 'Many young people leave rural areas to find better job opportunities in big cities.', 'Unit 14: Urbanisation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (786, 'Short-sighted', 'adj', 'Cận thị / Thiển cận (thiếu tầm nhìn xa)', 'Cutting education budgets is a short-sighted policy that will harm the country in the long term.', 'Unit 14: Urbanisation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (787, 'Short-term', 'adj', 'Ngắn hạn / Tạm thời', 'Renting an apartment is only a short-term solution while they look for a house to buy.', 'Unit 14: Urbanisation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (788, 'Staggering', 'adj', 'Đáng kinh ngạc / Sửng sốt', 'The government spent a staggering amount of money on the new public transport system.', 'Unit 14: Urbanisation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (789, 'Tolerant', 'adj', 'Khoan dung / Chấp nhận sự khác biệt', 'Schools should teach young students to be tolerant of different cultures and beliefs.', 'Unit 14: Urbanisation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (790, 'Address', 'v', 'Giải quyết / Xử lý', 'The city council needs to address traffic congestion before the summer tourist season begins.', 'Unit 14: Urbanisation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (791, 'Adjust', 'v', 'Điều chỉnh / Thích nghi', 'It takes time for international students to adjust to the new learning environment abroad.', 'Unit 14: Urbanisation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (792, 'Aggravate', 'v', 'Làm trầm trọng thêm / Làm xấu đi', 'Heavy traffic and air pollution can aggravate the health problems of local residents.', 'Unit 14: Urbanisation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (793, 'Cause', 'v', 'Gây ra / Dẫn đến', 'Smoking and an unhealthy diet can cause serious heart diseases in young adults.', 'Unit 14: Urbanisation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (794, 'Compete', 'v', 'Cạnh tranh / Thi đua', 'Small local shops find it hard to compete with large international supermarkets.', 'Unit 14: Urbanisation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (795, 'Compound', 'v', 'Làm trầm trọng thêm / Làm phức tạp thêm', 'A lack of public transport compounds the severe traffic problems in growing cities.', 'Unit 14: Urbanisation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (796, 'Deal with', 'v', 'Giải quyết / Đối phó với', 'Governments must deal with youth unemployment by creating more vocational training courses.', 'Unit 14: Urbanisation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (797, 'Deteriorate', 'v', 'Xấu đi / Suy giảm', 'Without proper maintenance, the quality of old roads will quickly deteriorate over time.', 'Unit 14: Urbanisation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (798, 'Enhance', 'v', 'Nâng cao / Cải thiện / Tăng cường', 'Reading books every day can significantly enhance your vocabulary and communication skills.', 'Unit 14: Urbanisation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (799, 'Exacerbate', 'v', 'Làm trầm trọng thêm / Làm tệ hơn', 'The recent heatwave has exacerbated the water shortage in many farming communities.', 'Unit 14: Urbanisation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (800, 'Exclude', 'v', 'Loại trừ / Ngăn chặn', 'The new community sports club does not exclude anyone based on age or gender.', 'Unit 14: Urbanisation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (801, 'Face', 'v', 'Đối mặt với / Đối diện', 'Many university graduates face difficulties when searching for their first professional job.', 'Unit 14: Urbanisation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (802, 'Flourish', 'v', 'Phát triển mạnh mẽ / Hưng thịnh', 'Local businesses can flourish if the government provides low-interest loans and tax support.', 'Unit 14: Urbanisation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (803, 'Identify', 'v', 'Nhận biết / Xác định', 'Scientists are trying to identify the main causes of global climate changes.', 'Unit 14: Urbanisation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (804, 'Improve', 'v', 'Cải thiện / Nâng cao', 'Regular physical exercise can improve both your bodily health and mental well-being.', 'Unit 14: Urbanisation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (805, 'Include', 'v', 'Bao gồm', 'A balanced daily diet should include fresh vegetables, fruits, and lean protein.', 'Unit 14: Urbanisation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (806, 'Linger', 'v', 'Kéo dài / Nán lại / Vương vấn', 'The bad smell of exhaust fumes can linger in narrow city streets for hours.', 'Unit 14: Urbanisation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (807, 'Modify', 'v', 'Sửa đổi / Điều chỉnh', 'Teachers often modify their lesson plans to suit the learning pace of each student.', 'Unit 14: Urbanisation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (808, 'Overcome', 'v', 'Vượt qua / Khắc phục', 'Students need determination and support to overcome academic pressure during final exam periods.', 'Unit 14: Urbanisation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (809, 'Present', 'v', 'Đưa ra / Gây ra / Đặt ra', 'Rapid population growth presents serious challenges for public housing and healthcare services.', 'Unit 14: Urbanisation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (810, 'Raise', 'v', 'Nâng cao / Nuôi nấng / Đưa ra', 'Schools should run awareness campaigns to raise students'' knowledge about plastic waste.', 'Unit 14: Urbanisation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (811, 'Reform', 'v', 'Cải cách / Cải tổ', 'The government decided to reform the national education system to meet modern job demands.', 'Unit 14: Urbanisation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (812, 'Regulate', 'v', 'Điều hòa / Quản lý / Quy định', 'Strict laws are needed to regulate industrial waste and protect the freshwater supply.', 'Unit 14: Urbanisation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (813, 'Remedy', 'v', 'Khắc phục / Cứu chữa / Sửa chữa', 'The local council must take immediate action to remedy the severe drinking water shortage.', 'Unit 14: Urbanisation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (814, 'Resolve', 'v', 'Giải quyết / Xử lý', 'Both sides met to resolve their differences and reach a peaceful agreement.', 'Unit 14: Urbanisation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (815, 'Tackle', 'v', 'Giải quyết / Xử lý', 'The city has launched several community projects to tackle air pollution effectively.', 'Unit 14: Urbanisation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (816, 'Tolerate', 'v', 'Chịu đựng / Tha thứ / Chấp nhận', 'Residents should not tolerate illegal garbage dumping near public parks and schools.', 'Unit 14: Urbanisation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (817, 'Transform', 'v', 'Biến đổi / Thay đổi hoàn toàn', 'Digital technology has transformed how people work, communicate, and study today.', 'Unit 14: Urbanisation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (818, 'Worsen', 'v', 'Trở nên tồi tệ hơn / Làm xấu đi', 'Heavy rains can worsen the traffic jams in large metropolitan areas.', 'Unit 14: Urbanisation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (819, 'Find a solution', 'v', 'Tìm ra giải pháp', 'Scientists are working hard to find a solution to clean energy storage problems.', 'Unit 14: Urbanisation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (820, 'Overcome a difficulty', 'v', 'Vượt qua khó khăn', 'With encouragement from her teacher, she managed to overcome a difficulty in mathematics.', 'Unit 14: Urbanisation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (821, 'Reach / find a compromise', 'v', 'Đạt được sự thỏa hiệp / Thống nhất chung', 'The management and workers must reach a compromise on working hours and overtime pay.', 'Unit 14: Urbanisation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (822, 'Remedy a situation', 'v', 'Khắc phục tình trạng / Cứu vãn tình thế', 'The school introduced free tutoring classes to remedy a situation of falling student grades.', 'Unit 14: Urbanisation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (823, 'Resolve an issue', 'v', 'Giải quyết một vấn đề', 'Open communication between parents and teenagers can help resolve an issue at home.', 'Unit 14: Urbanisation');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (824, 'Acid rain', 'n', 'Mưa axit', 'Acid rain can damage historical stone buildings and harm freshwater wildlife.', 'Unit 15: The Green Revolution');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (825, 'Biodiversity', 'n', 'Đa dạng sinh học', 'Deforestation in tropical rainforests threatens the rich biodiversity of these unique regions.', 'Unit 15: The Green Revolution');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (826, 'Climate change', 'n', 'Biến đổi khí hậu', 'Rising ocean temperatures are one of the clearest signs of global climate change.', 'Unit 15: The Green Revolution');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (827, 'Contamination', 'n', 'Sự ô nhiễm / Sự nhiễm bẩn', 'Chemical waste from nearby factories caused serious water contamination in the river.', 'Unit 15: The Green Revolution');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (828, 'Deforestation', 'n', 'Nạn phá rừng / Sự tàn phá rừng', 'Deforestation causes severe soil erosion and destroys natural habitats of wild animals.', 'Unit 15: The Green Revolution');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (829, 'Disposal', 'n', 'Sự vứt bỏ / Sự xử lý (rác thải)', 'Safe disposal of medical waste is essential to prevent dangerous infections in hospitals.', 'Unit 15: The Green Revolution');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (830, 'Drought', 'n', 'Hạn hán', 'The severe drought destroyed rice crops and left many local farmers without income.', 'Unit 15: The Green Revolution');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (831, 'Ecosystem', 'n', 'Hệ sinh thái', 'Protecting coral reefs is vital because they support a diverse marine ecosystem.', 'Unit 15: The Green Revolution');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (832, 'Emission', 'n', 'Sự phát thải / Khí thải', 'Strict regulations on carbon emission can encourage companies to use greener technologies.', 'Unit 15: The Green Revolution');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (833, 'The environment', 'n', 'Môi trường tự nhiên / Môi trường sống', 'Using public transport instead of private cars helps protect the environment from pollution.', 'Unit 15: The Green Revolution');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (834, 'Erosion', 'n', 'Sự xói mòn / Sự ăn mòn', 'Planting trees along riverbanks helps prevent soil erosion caused by heavy rains.', 'Unit 15: The Green Revolution');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (835, 'Exhaust (fumes)', 'n', 'Khí thải (động cơ / xe cộ)', 'Breathing in exhaust fumes from heavy traffic can harm the human respiratory system.', 'Unit 15: The Green Revolution');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (836, 'Fertilizer', 'n', 'Phân bón', 'Farmers are encouraged to use organic fertilizer to protect soil quality and groundwater.', 'Unit 15: The Green Revolution');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (837, 'Flood', 'n', 'Lũ lụt / Trận lụt', 'The heavy storm caused a sudden flood that damaged many homes and roads.', 'Unit 15: The Green Revolution');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (838, 'Food chain', 'n', 'Chuỗi thức ăn', 'Microplastics in the ocean are now entering the global food chain through fish.', 'Unit 15: The Green Revolution');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (839, 'Fumes', 'n', 'Khói / Khói độc / Hơi độc', 'Workers in the chemical factory must wear masks to avoid inhaling toxic fumes.', 'Unit 15: The Green Revolution');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (840, 'Greenhouse gases', 'n', 'Khí nhà kính', 'The burning of fossil fuels releases huge amounts of greenhouse gases into the atmosphere.', 'Unit 15: The Green Revolution');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (841, 'Impact', 'n', 'Tác động / Sự ảnh hưởng', 'Mass tourism can have a negative impact on delicate local environments and cultures.', 'Unit 15: The Green Revolution');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (842, 'Pollutant', 'n', 'Chất gây ô nhiễm', 'Plastic is a dangerous pollutant that takes hundreds of years to break down completely.', 'Unit 15: The Green Revolution');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (843, 'Pollution', 'n', 'Sự ô nhiễm', 'Air pollution in major cities poses a serious threat to public health and safety.', 'Unit 15: The Green Revolution');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (844, 'Process', 'n', 'Quy trình / Quá trình', 'Recycling paper is a simple process that helps save trees and reduce industrial waste.', 'Unit 15: The Green Revolution');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (845, 'Refuse', 'n', 'Rác thải / Phế thải', 'The city collects household refuse twice a week to keep residential streets clean.', 'Unit 15: The Green Revolution');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (846, 'Strain', 'n', 'Sự căng thẳng / Áp lực lớn', 'Rapid urban growth puts a heavy strain on public transport and healthcare services.', 'Unit 15: The Green Revolution');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (847, 'Threat', 'n', 'Mối đe dọa / Mối nguy cơ', 'Habitat loss is currently the biggest threat facing endangered wildlife species worldwide.', 'Unit 15: The Green Revolution');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (848, 'Waste', 'n', 'Rác thải / Sự lãng phí', 'Households should separate plastic waste from organic waste to support recycling efforts.', 'Unit 15: The Green Revolution');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (849, 'Achievable', 'adj', 'Có thể đạt được / Khả thi', 'Reducing single-use plastic in daily life is an achievable goal for every family.', 'Unit 15: The Green Revolution');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (850, 'Advantageous', 'adj', 'Có lợi / Thuận lợi', 'Studying abroad can be very advantageous for students seeking international career opportunities.', 'Unit 15: The Green Revolution');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (851, 'At risk', 'adj', 'Có nguy cơ / Đang gặp nguy hiểm', 'Many polar animals are at risk of extinction due to melting Arctic sea ice.', 'Unit 15: The Green Revolution');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (852, 'Beneficial', 'adj', 'Có lợi / Mang lại lợi ích', 'Eating plenty of fresh vegetables is beneficial to your digestive health and immunity.', 'Unit 15: The Green Revolution');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (853, 'Chronic', 'adj', 'Mãn tính / Kinh niên / Kéo dài', 'Exposure to toxic fumes can lead to chronic breathing problems in factory workers.', 'Unit 15: The Green Revolution');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (854, 'Conceivable', 'adj', 'Có thể tưởng tượng được / Có thể hình dung', 'Solar energy is suitable for almost every conceivable type of modern building design.', 'Unit 15: The Green Revolution');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (855, 'Contaminated', 'adj', 'Bị ô nhiễm / Bị nhiễm bẩn', 'Drinking contaminated water can cause serious stomach infections and other severe illnesses.', 'Unit 15: The Green Revolution');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (856, 'Devastating', 'adj', 'Có tính tàn phá / Khốc liệt', 'The major oil spill had a devastating effect on marine life along the coastline.', 'Unit 15: The Green Revolution');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (857, 'Doubtful', 'adj', 'Nghi ngờ / Không chắc chắn', 'It is doubtful that fossil fuel supplies will last until the next century.', 'Unit 15: The Green Revolution');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (858, 'Environmental', 'adj', 'Thuộc về môi trường', 'Air pollution is a pressing environmental issue that affects millions of urban citizens.', 'Unit 15: The Green Revolution');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (859, 'Environmentally friendly', 'adj', 'Thân thiện với môi trường', 'Riding a bicycle to work is an environmentally friendly way to stay fit and healthy.', 'Unit 15: The Green Revolution');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (860, 'Feasible', 'adj', 'Khả thi / Có thể thực hiện được', 'Building a solar-powered school is a feasible project for the local community.', 'Unit 15: The Green Revolution');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (861, 'Fruitless', 'adj', 'Không có kết quả / Vô ích / Thất bại', 'Their attempts to clean the river proved fruitless without strict government factory regulations.', 'Unit 15: The Green Revolution');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (862, 'Futile', 'adj', 'Vô ích / Không có kết quả', 'It is futile to plant new trees without protecting them from illegal logging activities.', 'Unit 15: The Green Revolution');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (863, 'Immune', 'adj', 'Miễn dịch / Miễn nhiễm / Không bị ảnh hưởng', 'A healthy diet helps keep your immune system strong against common seasonal infections.', 'Unit 15: The Green Revolution');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (864, 'Impracticable', 'adj', 'Không khả thi / Không thể thực hiện được', 'Banning all private cars immediately is impracticable for a city without good bus networks.', 'Unit 15: The Green Revolution');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (865, 'Improbable', 'adj', 'Khó xảy ra / Không chắc chắn', 'It seems improbable that the global temperature will drop without international climate agreements.', 'Unit 15: The Green Revolution');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (866, 'In danger (of)', 'adj', 'Có nguy cơ / Gặp nguy hiểm', 'Many rare tropical bird species are in danger of extinction due to widespread deforestation.', 'Unit 15: The Green Revolution');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (867, 'Insoluble', 'adj', 'Không thể giải quyết được / Không tan', 'Traffic congestion seems like an insoluble problem for many overcrowded modern megacities.', 'Unit 15: The Green Revolution');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (868, 'Irreparable', 'adj', 'Không thể cứu vãn / Không thể khắc phục', 'Oil spills cause irreparable damage to marine life and delicate coastal ecosystems.', 'Unit 15: The Green Revolution');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (869, 'Irreplaceable', 'adj', 'Không thể thay thế / Vô giá', 'Ancient rainforests are irreplaceable natural treasures that take centuries to grow back.', 'Unit 15: The Green Revolution');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (870, 'Irreversible', 'adj', 'Không thể đảo ngược / Không thể thay đổi lại', 'Melting polar glaciers could cause irreversible changes to global weather and sea levels.', 'Unit 15: The Green Revolution');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (871, 'Liable', 'adj', 'Có khả năng bị / Có trách nhiệm pháp lý', 'Drivers who cause traffic accidents are liable for all property damage and medical costs.', 'Unit 15: The Green Revolution');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (872, 'Life-threatening', 'adj', 'Đe dọa tính mạng / Nguy hiểm đến tính mạng', 'Severe air pollution can cause life-threatening illnesses such as asthma and heart disease.', 'Unit 15: The Green Revolution');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (873, 'Pervasive', 'adj', 'Lan tỏa khắp nơi / Tràn lan', 'Plastic waste has become a pervasive environmental problem found even on remote islands.', 'Unit 15: The Green Revolution');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (874, 'Pointless', 'adj', 'Vô nghĩa / Không có mục đích', 'It is pointless to clean the beach if visitors continue leaving plastic rubbish behind.', 'Unit 15: The Green Revolution');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (875, 'Pristine', 'adj', 'Nguyên sơ / Trong lành / Còn nguyên vẹn', 'Tourists are attracted to the island because of its pristine beaches and clear waters.', 'Unit 15: The Green Revolution');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (876, 'Questionable', 'adj', 'Đáng nghi ngờ / Còn gây tranh cãi', 'The safety of building chemical factories near residential areas remains highly questionable.', 'Unit 15: The Green Revolution');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (877, 'Recyclable', 'adj', 'Có thể tái chế', 'We should use recyclable shopping bags to cut down on plastic household waste.', 'Unit 15: The Green Revolution');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (878, 'Sustainable', 'adj', 'Bền vững / Thân thiện với môi trường', 'Using solar and wind energy is essential for sustainable economic development today.', 'Unit 15: The Green Revolution');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (879, 'Taxing', 'adj', 'Đòi hỏi nhiều nỗ lực / Căng thẳng / Nặng nhọc', 'Working long hours in a busy hospital can be mentally and physically taxing.', 'Unit 15: The Green Revolution');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (880, 'Unattainable', 'adj', 'Không thể đạt được / Xa vời', 'Zero waste may seem like an unattainable goal, but small daily efforts help significantly.', 'Unit 15: The Green Revolution');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (881, 'Unlikely', 'adj', 'Không có khả năng xảy ra / Khó có thể', 'It is unlikely that electric cars will replace all petrol vehicles within five years.', 'Unit 15: The Green Revolution');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (882, 'Unprecedented', 'adj', 'Chưa từng có / Chưa từng thấy', 'The country experienced an unprecedented heatwave that broke all previous summer temperature records.', 'Unit 15: The Green Revolution');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (883, 'Useless', 'adj', 'Vô ích / Không có tác dụng', 'Buying products with excessive plastic packaging is useless if we want to protect the environment.', 'Unit 15: The Green Revolution');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (884, 'Viable', 'adj', 'Khả thi / Có thể thực hiện được', 'Solar energy is becoming a viable alternative to fossil fuels in many developing countries.', 'Unit 15: The Green Revolution');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (885, 'Vital', 'adj', 'Thiết yếu / Cực kỳ quan trọng', 'Clean water plays a vital role in maintaining public health and preventing dangerous diseases.', 'Unit 15: The Green Revolution');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (886, 'Worthwhile', 'adj', 'Đáng giá / Bổ ích', 'Volunteering for local environmental projects is a worthwhile experience for young students.', 'Unit 15: The Green Revolution');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (887, 'Confront', 'v', 'Đối mặt / Đương đầu', 'Governments must confront serious environmental challenges before the situation becomes much worse.', 'Unit 15: The Green Revolution');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (888, 'Contaminate', 'v', 'Làm ô nhiễm / Làm nhiễm bẩn', 'Chemical waste from factories can easily contaminate nearby rivers and underground water sources.', 'Unit 15: The Green Revolution');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (889, 'Dispose of', 'v', 'Vứt bỏ / Xử lý (rác thải)', 'People should learn how to dispose of plastic items properly to reduce environmental damage.', 'Unit 15: The Green Revolution');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (890, 'Dump', 'v', 'Vứt bỏ / Đổ (rác thải)', 'Many companies illegally dump untreated industrial waste into the ocean to save money.', 'Unit 15: The Green Revolution');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (891, 'Threaten', 'v', 'Đe dọa', 'Rising sea levels threaten many coastal cities and agricultural areas around the world.', 'Unit 15: The Green Revolution');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (892, 'Inexorably', 'v', 'Không thể ngăn cản / Một cách tất yếu', 'Global temperatures continue to rise inexorably because of high greenhouse gas emissions.', 'Unit 15: The Green Revolution');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (893, 'Inevitably', 'v', 'Chắc chắn xảy ra / Tất yếu', 'Rapid urbanization will inevitably lead to serious traffic congestion and severe air pollution.', 'Unit 15: The Green Revolution');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (894, 'Atmosphere', 'n', 'Khí quyển / Bầu không khí', 'Large amounts of harmful gases are released into the atmosphere every single day.', 'Unit 16: The Energy Crisis');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (895, 'Balance', 'n', 'Sự cân bằng', 'Human activities have disrupted the natural balance of ecosystems across the planet.', 'Unit 16: The Energy Crisis');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (896, 'Biofuel', 'n', 'Nhiên liệu sinh học', 'Many scientists believe that biofuel made from plants can replace traditional fossil fuels.', 'Unit 16: The Energy Crisis');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (897, 'Carbon', 'n', 'Cacbon', 'Countries around the world are trying to reduce their total carbon footprint significantly.', 'Unit 16: The Energy Crisis');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (898, 'Carbon dioxide', 'n', 'Khí cacbonic / Khí CO2', 'Trees play an important role because they absorb carbon dioxide and release fresh oxygen.', 'Unit 16: The Energy Crisis');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (899, 'Crisis', 'n', 'Khủng hoảng / Cuộc khủng hoảng', 'The global energy crisis has forced many nations to invest in renewable energy sources.', 'Unit 16: The Energy Crisis');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (900, 'Electricity', 'n', 'Điện / Điện năng', 'Using solar panels allows households to generate their own clean electricity and save money.', 'Unit 16: The Energy Crisis');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (901, 'Emissions', 'n', 'Khí thải', 'Governments should introduce strict laws to limit harmful emissions from cars and factories.', 'Unit 16: The Energy Crisis');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (902, 'Exhaust', 'n', 'Khí thải (xe cộ) / Khói xả', 'Vehicle exhaust is one of the main causes of poor air quality in modern cities.', 'Unit 16: The Energy Crisis');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (903, 'Fossil fuel', 'n', 'Nhiên liệu hóa thạch', 'Burning fossil fuel releases dangerous greenhouse gases that contribute directly to global warming.', 'Unit 16: The Energy Crisis');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (904, 'Fuel', 'n', 'Nhiên liệu / Chất đốt', 'Rising fuel prices have encouraged more commuters to switch to public transport.', 'Unit 16: The Energy Crisis');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (905, 'Fumes', 'n', 'Khói độc / Khí thải độc hại', 'Inhaling toxic exhaust fumes every day can cause serious health problems for city residents.', 'Unit 16: The Energy Crisis');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (906, 'Gas', 'n', 'Khí đốt / Khí ga', 'Natural gas is commonly used for cooking and heating in many modern households.', 'Unit 16: The Energy Crisis');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (907, 'Greenhouse gas', 'n', 'Khí nhà kính', 'Reducing greenhouse gas emissions is essential to prevent severe changes in world climate.', 'Unit 16: The Energy Crisis');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (908, 'Hybrid', 'n', 'Xe lai điện (hybrid) / Sự kết hợp', 'Many drivers prefer buying a hybrid because it consumes less petrol and produces lower emissions.', 'Unit 16: The Energy Crisis');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (909, 'Hydrogen', 'n', 'Khí hydro / Hydro', 'Scientists are exploring hydrogen as a clean and sustainable source of energy for vehicles.', 'Unit 16: The Energy Crisis');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (910, 'Petrol', 'n', 'Xăng', 'The high price of petrol has encouraged many people to cycle or take the bus to work.', 'Unit 16: The Energy Crisis');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (911, 'Resources', 'n', 'Tài nguyên / Nguồn lực', 'We must use natural resources wisely to ensure there is enough energy for future generations.', 'Unit 16: The Energy Crisis');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (912, 'Turbine', 'n', 'Tua-bin', 'A modern wind turbine can generate enough clean power for hundreds of local homes.', 'Unit 16: The Energy Crisis');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (913, 'Vehicle', 'n', 'Phương tiện giao thông / Xe cộ', 'Every motor vehicle should undergo regular checks to ensure it does not produce dangerous emissions.', 'Unit 16: The Energy Crisis');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (914, 'Alternative', 'adj', 'Thay thế', 'Governments should invest heavily in alternative energy sources like wind and solar power.', 'Unit 16: The Energy Crisis');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (915, 'Critical', 'adj', 'Quan trọng / Mang tính quyết định', 'Conserving freshwater is a critical issue that requires immediate action from all countries.', 'Unit 16: The Energy Crisis');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (916, 'Disposable', 'adj', 'Dùng một lần', 'People should avoid using disposable plastic cups and bottles to protect the marine environment.', 'Unit 16: The Energy Crisis');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (917, 'Drastic', 'adj', 'Quyết liệt / Mạnh mẽ', 'Cities need to take drastic measures to control air pollution caused by heavy traffic.', 'Unit 16: The Energy Crisis');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (918, 'Eco-friendly', 'adj', 'Thân thiện với môi trường', 'Consumers are encouraged to choose eco-friendly products that do not harm natural habitats.', 'Unit 16: The Energy Crisis');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (919, 'Efficient', 'adj', 'Hiệu quả / Tiết kiệm năng lượng', 'Modern appliances are much more efficient and help families reduce their monthly electricity bills.', 'Unit 16: The Energy Crisis');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (920, 'Effective', 'adj', 'Hiệu quả / Có tác dụng', 'Public campaigns are an effective way to raise awareness about saving water at home.', 'Unit 16: The Energy Crisis');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (921, 'Environmentally friendly', 'adj', 'Thân thiện với môi trường', 'Riding a bicycle to work is an environmentally friendly habit that also improves personal fitness.', 'Unit 16: The Energy Crisis');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (922, 'Nuclear', 'adj', 'Thuộc về hạt nhân', 'Nuclear power can produce large amounts of energy without creating significant air pollution.', 'Unit 16: The Energy Crisis');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (923, 'Rechargeable', 'adj', 'Có thể sạc lại', 'Using rechargeable batteries is a simple habit that helps reduce toxic chemical waste.', 'Unit 16: The Energy Crisis');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (924, 'Renewable', 'adj', 'Có thể tái tạo', 'Switching to renewable energy like solar and wind power helps fight global climate change.', 'Unit 16: The Energy Crisis');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (925, 'Solar', 'adj', 'Thuộc về mặt trời / Năng lượng mặt trời', 'Installing solar panels on rooftops can provide free and clean electricity for households.', 'Unit 16: The Energy Crisis');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (926, 'Unleaded (petrol)', 'adj', 'Không chì (xăng)', 'Most modern cars run on unleaded petrol to reduce poisonous lead emissions into the air.', 'Unit 16: The Energy Crisis');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (927, 'Absorb', 'v', 'Hấp thụ / Hút', 'Forests absorb large quantities of carbon dioxide from the atmosphere and help cool the planet.', 'Unit 16: The Energy Crisis');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (928, 'Conserve', 'v', 'Bảo tồn / Tiết kiệm', 'Everyone should try to conserve electricity by turning off lights when leaving a room.', 'Unit 16: The Energy Crisis');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (929, 'Consume', 'v', 'Tiêu thụ / Tiêu dùng', 'Large air conditioners consume a significant amount of electricity during hot summer months.', 'Unit 16: The Energy Crisis');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (930, 'Convert', 'v', 'Chuyển đổi / Biến đổi', 'Solar panels convert natural sunlight directly into electrical energy for domestic use.', 'Unit 16: The Energy Crisis');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (931, 'Counter', 'v', 'Chống lại / Đối phó', 'Planting more green trees is an effective measure to counter the effects of global warming.', 'Unit 16: The Energy Crisis');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (932, 'Deplete', 'v', 'Làm cạn kiệt / Suy giảm', 'Overusing natural resources will rapidly deplete fossil fuel reserves across the world.', 'Unit 16: The Energy Crisis');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (933, 'Diminish', 'v', 'Giảm bớt / Suy giảm', 'The supply of fresh drinking water may diminish significantly if pollution continues to spread.', 'Unit 16: The Energy Crisis');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (934, 'Discharge', 'v', 'Xả ra / Thải ra', 'It is illegal for factories to discharge untreated chemical waste into nearby rivers.', 'Unit 16: The Energy Crisis');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (935, 'Dwindle', 'v', 'Thu hẹp dần / Suy giảm dần', 'Global oil reserves continue to dwindle as energy consumption rises each year.', 'Unit 16: The Energy Crisis');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (936, 'Emit', 'v', 'Phát ra / Thải ra', 'Old motor vehicles emit dangerous amounts of toxic fumes into the city air.', 'Unit 16: The Energy Crisis');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (937, 'Expend', 'v', 'Tiêu hao / Dành ra', 'Athletes expend a tremendous amount of physical energy during competitive sports events.', 'Unit 16: The Energy Crisis');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (938, 'Limit', 'v', 'Hạn chế / Giới hạn', 'Governments should limit the use of private cars in city centers to curb pollution.', 'Unit 16: The Energy Crisis');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (939, 'Maintain', 'v', 'Duy trì / Giữ vững', 'Regular exercise and a healthy diet help individuals maintain good physical and mental health.', 'Unit 16: The Energy Crisis');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (940, 'Outweigh', 'v', 'Vượt trội hơn / Lớn hơn', 'The long-term benefits of renewable energy far outweigh the initial costs of installation.', 'Unit 16: The Energy Crisis');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (941, 'Preserve', 'v', 'Bảo tồn / Giữ gìn', 'National parks are established to preserve rare animal species and their natural habitats.', 'Unit 16: The Energy Crisis');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (942, 'Retain', 'v', 'Giữ lại / Duy trì', 'Wetlands help retain excess rainwater and prevent severe flooding in surrounding residential areas.', 'Unit 16: The Energy Crisis');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (943, 'Waste', 'v', 'Lãng phí', 'People should not waste clean water when washing dishes or taking daily showers.', 'Unit 16: The Energy Crisis');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (944, 'Advertisement', 'n', 'Bài quảng cáo / Mẩu quảng cáo', 'I saw an interesting job advertisement online for an English teacher position yesterday.', 'Unit 17: Talking Business');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (945, 'Advertising', 'n', 'Hoạt động quảng cáo / Ngành quảng cáo', 'Companies spend billions of dollars on advertising to promote their newest electronic gadgets.', 'Unit 17: Talking Business');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (946, 'Boss', 'n', 'Sếp / Cấp trên / Ông chủ', 'A good boss always listens to employee feedback and encourages personal professional growth.', 'Unit 17: Talking Business');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (947, 'Campaign', 'n', 'Chiến dịch', 'The marketing campaign successfully attracted millions of young customers to the new brand.', 'Unit 17: Talking Business');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (948, 'Candidate', 'n', 'Ứng viên / Thí sinh', 'The successful candidate should have excellent communication skills and relevant work experience.', 'Unit 17: Talking Business');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (949, 'Career', 'n', 'Sự nghiệp / Nghề nghiệp', 'Choosing a suitable career path is one of the most important decisions for graduates.', 'Unit 17: Talking Business');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (950, 'Clerk', 'n', 'Nhân viên văn phòng / Nhân viên bán hàng', 'The bank clerk helped me complete the financial paperwork quickly and politely.', 'Unit 17: Talking Business');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (951, 'Client', 'n', 'Khách hàng / Thân chủ', 'The lawyer met with an important client this morning to discuss a new business contract.', 'Unit 17: Talking Business');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (952, 'Colleague', 'n', 'Đồng nghiệp', 'I usually discuss project ideas with my colleague before presenting them to the manager.', 'Unit 17: Talking Business');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (953, 'Company', 'n', 'Công ty / Doanh nghiệp', 'Many graduates want to work for a multinational company with good career opportunities.', 'Unit 17: Talking Business');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (954, 'Consumer', 'n', 'Người tiêu dùng', 'A smart consumer always compares prices and reads reviews before buying expensive electronics online.', 'Unit 17: Talking Business');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (955, 'Credibility', 'n', 'Sự uy tín / Độ tin cậy', 'Honest customer reviews help enhance the credibility of online shopping platforms.', 'Unit 17: Talking Business');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (956, 'Customer', 'n', 'Khách hàng', 'Providing excellent service is the best way to satisfy every customer and ensure repeat business.', 'Unit 17: Talking Business');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (957, 'Earnings', 'n', 'Thu nhập / Tiền lương', 'Workers often save a portion of their monthly earnings for retirement and emergencies.', 'Unit 17: Talking Business');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (958, 'Employee', 'n', 'Nhân viên / Người lao động', 'The company offers free healthcare insurance to every full-time employee and their family.', 'Unit 17: Talking Business');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (959, 'Employer', 'n', 'Người sử dụng lao động / Nhà tuyển dụng', 'A good employer provides comfortable working conditions and rewards hard-working staff members.', 'Unit 17: Talking Business');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (960, 'Employment', 'n', 'Việc làm / Sự thuê mướn lao động', 'Tourism has created many employment opportunities for local residents in rural areas.', 'Unit 17: Talking Business');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (961, 'Experience', 'n', 'Kinh nghiệm / Trải nghiệm', 'Practical work experience is just as valuable as university degrees in finding a good job.', 'Unit 17: Talking Business');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (962, 'Goods', 'n', 'Hàng hóa', 'Supermarkets import various consumer goods from other countries to offer wider choices.', 'Unit 17: Talking Business');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (963, 'Income', 'n', 'Thu nhập', 'Many people take on freelance tasks in their free time to supplement their monthly income.', 'Unit 17: Talking Business');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (964, 'Industry', 'n', 'Ngành công nghiệp / Ngành kinh doanh', 'The technology industry is growing rapidly and providing numerous job opportunities for young people.', 'Unit 17: Talking Business');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (965, 'Interview', 'n', 'Buổi phỏng vấn / Cuộc phỏng vấn', 'Dressing smartly and arriving on time will make a positive impression during a job interview.', 'Unit 17: Talking Business');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (966, 'Job', 'n', 'Công việc / Việc làm', 'Having a stable job provides financial security and helps people support their families.', 'Unit 17: Talking Business');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (967, 'Job satisfaction', 'n', 'Sự hài lòng trong công việc', 'High job satisfaction often leads to greater employee productivity and loyalty to the firm.', 'Unit 17: Talking Business');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (968, 'Labourer', 'n', 'Người lao động chân tay / Công nhân', 'A construction labourer often works outdoors in difficult weather conditions to build houses.', 'Unit 17: Talking Business');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (969, 'Management', 'n', 'Ban quản lý / Sự quản lý', 'Effective management is essential for leading a business through difficult economic periods.', 'Unit 17: Talking Business');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (970, 'Manual work', 'n', 'Công việc lao động chân tay', 'Many young people today prefer working in modern offices rather than doing manual work.', 'Unit 17: Talking Business');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (971, 'Market', 'n', 'Thị trường / Chợ', 'Smartphones have captured a huge share of the global consumer electronics market.', 'Unit 17: Talking Business');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (972, 'Marketing', 'n', 'Tiếp thị / Hoạt động tiếp thị', 'Digital marketing allows small businesses to connect directly with potential customers worldwide.', 'Unit 17: Talking Business');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (973, 'Meeting', 'n', 'Cuộc họp', 'The manager scheduled a weekly meeting to discuss new project targets and employee feedback.', 'Unit 17: Talking Business');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (974, 'Money', 'n', 'Tiền bạc / Tiền', 'Learning how to budget your money wisely is an essential life skill for university students.', 'Unit 17: Talking Business');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (975, 'Niche', 'n', 'Thị trường ngách / Vị trí thích hợp', 'The company found a profitable niche by selling organic baby food to health-conscious parents.', 'Unit 17: Talking Business');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (976, 'Occupation', 'n', 'Nghề nghiệp / Công việc', 'Teaching is considered a demanding occupation that requires patience, dedication, and deep knowledge.', 'Unit 17: Talking Business');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (977, 'Office', 'n', 'Văn phòng / Nơi làm việc', 'Many employees now work from home two days a week instead of commuting to the office.', 'Unit 17: Talking Business');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (978, 'Overtime', 'n', 'Giờ làm thêm / Tăng ca', 'Employees who work overtime during busy periods are entitled to receive higher pay rates.', 'Unit 17: Talking Business');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (979, 'Packaging', 'n', 'Bao bì / Sự đóng gói', 'Companies should design eco-friendly packaging that uses biodegradable materials instead of plastic.', 'Unit 17: Talking Business');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (980, 'Pay', 'n', 'Tiền lương / Thù lao', 'Fair pay and flexible working hours can motivate employees to perform better at work.', 'Unit 17: Talking Business');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (981, 'Perk', 'n', 'Phúc lợi bổ sung / Đặc quyền công việc', 'A company car and flexible working hours are great perks of this job.', 'Unit 17: Talking Business');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (982, 'Product', 'n', 'Sản phẩm', 'The company plans to launch a new eco-friendly product next month.', 'Unit 17: Talking Business');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (983, 'Profession', 'n', 'Nghề nghiệp / Giới chuyên môn', 'Teaching is considered a noble profession that requires great patience and dedication.', 'Unit 17: Talking Business');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (984, 'Prospects', 'n', 'Triển vọng / Cơ hội thăng tiến', 'Graduates usually choose companies that offer good career prospects for the future.', 'Unit 17: Talking Business');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (985, 'Qualifications', 'n', 'Bằng cấp / Trình độ chuyên môn', 'Candidates need relevant academic qualifications and practical skills to apply for this job.', 'Unit 17: Talking Business');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (986, 'Retirement', 'n', 'Sự nghỉ hưu / Tuổi nghỉ hưu', 'Many elderly people enjoy traveling and pursuing new hobbies after their retirement.', 'Unit 17: Talking Business');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (987, 'Salary', 'n', 'Mức lương / Tiền lương', 'She receives a competitive monthly salary and an attractive annual bonus.', 'Unit 17: Talking Business');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (988, 'Shares', 'n', 'Cổ phần / Cổ phiếu', 'Employees are allowed to buy company shares at a discounted price every year.', 'Unit 17: Talking Business');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (989, 'Shift work', 'n', 'Công việc theo ca / Làm việc theo ca', 'Doctors and nurses often do shift work to care for patients overnight.', 'Unit 17: Talking Business');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (990, 'Skills', 'n', 'Kỹ năng', 'Good communication skills help employees work effectively with colleagues and clients.', 'Unit 17: Talking Business');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (991, 'Staff', 'n', 'Đội ngũ nhân viên / Nhân viên', 'The hotel trained all staff members to provide excellent customer service.', 'Unit 17: Talking Business');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (992, 'Supervisor', 'n', 'Người giám sát / Quản lý trực tiếp', 'You should discuss any workplace issues with your supervisor as soon as possible.', 'Unit 17: Talking Business');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (993, 'Takeover', 'n', 'Sự tiếp quản / Sự mua lại công ty', 'The corporate takeover created many new opportunities for talented young workers.', 'Unit 17: Talking Business');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (994, 'Target', 'n', 'Mục tiêu / Chỉ tiêu', 'The sales team worked very hard to meet their monthly targets.', 'Unit 17: Talking Business');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (995, 'Trade', 'n', 'Thương mại / Sự buôn bán', 'International trade helps countries exchange essential goods and develop their economies.', 'Unit 17: Talking Business');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (996, 'Trend', 'n', 'Xu hướng', 'Working remotely has become a popular trend among young professionals today.', 'Unit 17: Talking Business');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (997, 'Unemployment', 'n', 'Tình trạng thất nghiệp / Nạn thất nghiệp', 'High unemployment among young graduates is a serious issue in many countries.', 'Unit 17: Talking Business');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (998, 'Wages', 'n', 'Tiền công / Tiền lương (trả theo tuần, giờ)', 'Many factory workers demand higher wages to deal with rising living costs.', 'Unit 17: Talking Business');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (999, 'Workforce', 'n', 'Lực lượng lao động', 'Women make up a significant portion of the modern workforce nowadays.', 'Unit 17: Talking Business');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1000, 'Workplace', 'n', 'Nơi làm việc / Môi trường làm việc', 'A positive workplace culture helps increase productivity and job satisfaction for employees.', 'Unit 17: Talking Business');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1001, 'Casual', 'adj', 'Thời vụ / Thoải mái / Không chính thức', 'Many university students take casual jobs during the summer to earn extra money.', 'Unit 17: Talking Business');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1002, 'Demanding', 'adj', 'Đòi hỏi khắt khe / Đầy thử thách', 'Being a doctor is a demanding career that requires great dedication and energy.', 'Unit 17: Talking Business');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1003, 'Economic', 'adj', 'Thuộc về kinh tế', 'Tourism plays an important role in the economic development of coastal cities.', 'Unit 17: Talking Business');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1004, 'Economical', 'adj', 'Tiết kiệm / Ít tốn kém', 'Using public transport is an economical way to travel around the city.', 'Unit 17: Talking Business');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1005, 'Exhausting', 'adj', 'Làm kiệt sức / Rất mệt mỏi', 'Working long hours without enough sleep is exhausting for both mind and body.', 'Unit 17: Talking Business');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1006, 'Hospitality', 'adj', 'Thuộc ngành khách sạn - du lịch / Hiếu khách', 'Many young people choose to work in the hospitality industry during vacations.', 'Unit 17: Talking Business');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1007, 'Monotonous', 'adj', 'Đơn điệu / Nhàm chán', 'Entering data into computers every day can quickly become a monotonous job.', 'Unit 17: Talking Business');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1008, 'Part-time', 'adj', 'Bán thời gian', 'She found a part-time job at a bookstore to support her living expenses.', 'Unit 17: Talking Business');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1009, 'Retail', 'adj', 'Bán lẻ / Thuộc ngành bán lẻ', 'The rapid growth of online shopping has changed the modern retail market significantly.', 'Unit 17: Talking Business');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1010, 'Redundant', 'adj', 'Bị sa thải do dôi dư nhân lực / Dư thừa', 'Many factory workers were made redundant when modern machines replaced manual tasks.', 'Unit 17: Talking Business');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1011, 'Rewarding', 'adj', 'Bổ ích / Mang lại sự thỏa mãn', 'Volunteering to teach poor children is a deeply rewarding experience for youth.', 'Unit 17: Talking Business');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1012, 'Unemployed', 'adj', 'Thất nghiệp / Không có việc làm', 'The government provides monthly financial allowances to help unemployed citizens find work.', 'Unit 17: Talking Business');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1013, 'Unskilled', 'adj', 'Lao động phổ thông / Không đòi hỏi tay nghề', 'Automation is rapidly replacing many unskilled jobs in factories across the world.', 'Unit 17: Talking Business');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1014, 'Apply', 'v', 'Nộp đơn (xin việc, học) / Áp dụng', 'Graduates are encouraged to apply for jobs that match their university degrees.', 'Unit 17: Talking Business');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1015, 'Compete', 'v', 'Cạnh tranh / Tranh tài', 'Small local stores have to compete against large international supermarket chains.', 'Unit 17: Talking Business');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1016, 'Earn', 'v', 'Kiếm được (tiền, sự tôn trọng)', 'He works hard every day to earn enough money for his children''s education.', 'Unit 17: Talking Business');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1017, 'Endorse', 'v', 'Quảng cáo đại diện / Tán thành, ủng hộ', 'Famous sports stars often endorse expensive brands to promote products to teenagers.', 'Unit 17: Talking Business');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1018, 'Invest (in)', 'v', 'Đầu tư (vào)', 'Governments should invest in public transportation to reduce severe traffic congestion in cities.', 'Unit 17: Talking Business');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1019, 'Persuade', 'v', 'Thuyết phục', 'Good advertisements can persuade customers to try new products in the market.', 'Unit 17: Talking Business');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1020, 'To be promoted', 'v', 'Được thăng chức', 'She worked very hard and was pleased to be promoted to senior manager.', 'Unit 17: Talking Business');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1021, 'Request', 'v', 'Yêu cầu / Đề nghị', 'Employees can request flexible working hours to maintain a healthy work-life balance.', 'Unit 17: Talking Business');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1022, 'Retire', 'v', 'Nghỉ hưu', 'My grandfather decided to retire early so that he could enjoy gardening peacefully.', 'Unit 17: Talking Business');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1023, 'Actions', 'n', 'Hành động / Biện pháp hành động', 'Governments must take immediate legal actions against companies that pollute local rivers.', 'Unit 18: The Law');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1024, 'Arson', 'n', 'Tội cố ý phóng hỏa / Sự phóng hỏa', 'The police arrested a suspect for committing arson at an empty warehouse.', 'Unit 18: The Law');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1025, 'Authority', 'n', 'Cơ quan chức năng / Thẩm quyền', 'The local authority decided to build more parks and leisure centers for residents.', 'Unit 18: The Law');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1026, 'Burglary', 'n', 'Tội đột nhập trộm cắp / Vụ trộm nhà', 'Installing modern security cameras helps protect private houses against burglary during vacations.', 'Unit 18: The Law');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1027, 'Consequences', 'n', 'Hậu quả / Hệ quả', 'Young people need to understand the serious legal consequences of committing violent crimes.', 'Unit 18: The Law');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1028, 'Convict', 'n', 'Người bị kết án / Tù nhân', 'Former convicts often struggle to find stable jobs after leaving prison.', 'Unit 18: The Law');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1029, 'Crime', 'n', 'Tội phạm / Tội ác', 'Poverty and lack of education often lead to higher levels of violent crime.', 'Unit 18: The Law');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1030, 'Crime rate', 'n', 'Tỷ lệ tội phạm', 'Installing bright streetlights has helped decrease the crime rate in this neighborhood.', 'Unit 18: The Law');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1031, 'Criminal', 'n', 'Tội phạm / Kẻ phạm tội', 'The police caught the dangerous criminal within twenty-four hours after the robbery.', 'Unit 18: The Law');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1032, 'Deterrent', 'n', 'Biện pháp răn đe / Yếu tố ngăn chặn', 'Heavy fines can serve as an effective deterrent against speeding on busy roads.', 'Unit 18: The Law');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1033, 'Evidence', 'n', 'Bằng chứng / Chứng cứ', 'The detective gathered clear physical evidence to identify the suspect of the crime.', 'Unit 18: The Law');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1034, 'Fine', 'n', 'Tiền phạt', 'Drivers who park their cars in prohibited areas must pay a heavy fine.', 'Unit 18: The Law');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1035, 'Fraud', 'n', 'Tội lừa đảo / Sự gian lận', 'Online fraud has become a growing concern for banks and their digital customers.', 'Unit 18: The Law');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1036, 'Imprisonment', 'n', 'Án tù / Sự phạt tù / Sự giam giữ', 'The judge sentenced the corrupt official to ten years of imprisonment.', 'Unit 18: The Law');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1037, 'Inequality', 'n', 'Sự bất bình đẳng', 'Social inequality often leads to frustration and contributes to social instability and crime.', 'Unit 18: The Law');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1038, 'Intent', 'n', 'Ý định / Ý đồ (phạm tội)', 'The prosecution must prove that the suspect acted with clear criminal intent.', 'Unit 18: The Law');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1039, 'Intrusion', 'n', 'Sự xâm phạm / Sự xâm nhập trái phép', 'Excessive surveillance is often seen as an unnecessary intrusion into private personal life.', 'Unit 18: The Law');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1040, 'Judge', 'n', 'Thẩm phán / Quan tòa', 'The judge listened to both lawyers before delivering a fair and final verdict.', 'Unit 18: The Law');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1041, 'Jury', 'n', 'Bồi thẩm đoàn', 'The jury listened to the witnesses carefully before reaching their final decision.', 'Unit 18: The Law');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1042, 'Kidnapping', 'n', 'Tội bắt cóc / Vụ bắt cóc', 'The government introduced strict laws to prevent cases of child kidnapping in cities.', 'Unit 18: The Law');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1043, 'Lawyer', 'n', 'Luật sư', 'Every person has the legal right to consult an experienced lawyer before trial.', 'Unit 18: The Law');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1044, 'Motive', 'n', 'Động cơ (phạm tội)', 'The police are still investigating the real motive behind the armed bank robbery.', 'Unit 18: The Law');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1045, 'Murder', 'n', 'Tội giết người / Vụ án mạng', 'The suspect was charged with murder and faced a potential life sentence.', 'Unit 18: The Law');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1046, 'Offence', 'n', 'Hành vi phạm tội / Tội phạm', 'Driving without a valid license is considered a serious legal offence in most nations.', 'Unit 18: The Law');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1047, 'Pickpocketing', 'n', 'Tội móc túi / Nạn móc túi', 'Tourists should watch their belongings carefully to avoid pickpocketing on crowded trains.', 'Unit 18: The Law');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1048, 'Prevention', 'n', 'Sự phòng ngừa / Sự ngăn chặn', 'Crime prevention requires close cooperation between local communities and the police force.', 'Unit 18: The Law');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1049, 'Prison', 'n', 'Nhà tù / Trại giam', 'Many countries are reforming their prison systems to focus on prisoner rehabilitation.', 'Unit 18: The Law');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1050, 'Prisoner', 'n', 'Tù nhân', 'Prisoners are offered educational courses to help them find employment after release.', 'Unit 18: The Law');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1051, 'Property crime', 'n', 'Tội xâm phạm quyền sở hữu / Tội phạm tài sản', 'Better street lighting helps reduce property crime such as burglary and vehicle theft.', 'Unit 18: The Law');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1052, 'Prosecutor', 'n', 'Công tố viên / Kiểm sát viên', 'The prosecutor presented solid evidence to convince the court of the defendant''s guilt.', 'Unit 18: The Law');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1053, 'Protection', 'n', 'Sự bảo vệ', 'Witnesses in dangerous criminal investigations often receive round-the-clock police protection.', 'Unit 18: The Law');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1054, 'Punishment', 'n', 'Hình phạt / Sự trừng phạt', 'Community service is often used as a punishment for minor first-time offences.', 'Unit 18: The Law');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1055, 'Recklessness', 'n', 'Sự liều lĩnh / Tính bất cẩn, coi thường nguy hiểm', 'His recklessness behind the wheel caused a severe traffic accident yesterday afternoon.', 'Unit 18: The Law');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1056, 'Smuggling', 'n', 'Tội buôn lậu / Sự buôn lậu', 'Customs officers work tirelessly at border checkpoints to combat illegal drug smuggling.', 'Unit 18: The Law');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1057, 'Social system', 'n', 'Hệ thống xã hội', 'A fair legal framework is essential for maintaining order in every social system.', 'Unit 18: The Law');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1058, 'Swearing', 'n', 'Hành vi chửi thề / Lời nói tục tĩu', 'Swearing in public places or school classrooms is considered rude and unacceptable behavior.', 'Unit 18: The Law');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1059, 'The accused', 'n', 'Bị cáo / Người bị buộc tội', 'The accused firmly stated that he was far away when the incident happened.', 'Unit 18: The Law');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1060, 'Toxic waste', 'n', 'Chất thải độc hại', 'Factories that illegally dump toxic waste into rivers should receive extremely heavy penalties.', 'Unit 18: The Law');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1061, 'Vandalism', 'n', 'Hành vi phá hoại của công / Tội phá hoại tài sản', 'The city council spent substantial money repairing bus stops damaged by youth vandalism.', 'Unit 18: The Law');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1062, 'Victim', 'n', 'Nạn nhân', 'Support programs are available to help crime victims recover both physically and emotionally.', 'Unit 18: The Law');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1063, 'Violation', 'n', 'Sự vi phạm / Hành vi vi phạm', 'Exceeding the speed limit in school zones is a serious violation of traffic laws.', 'Unit 18: The Law');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1064, 'Criminal', 'adj', 'Thuộc về hình sự / Phạm pháp', 'He was arrested by the police due to continuous involvement in criminal activities.', 'Unit 18: The Law');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1065, 'Drug-related', 'adj', 'Liên quan đến ma túy', 'Police launched an intensive campaign to tackle drug-related crimes in urban centers.', 'Unit 18: The Law');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1066, 'Evil', 'adj', 'Độc ác / Tàn ác', 'Society strongly condemns such evil behavior that causes deep pain to innocent people.', 'Unit 18: The Law');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1067, 'Guilty', 'adj', 'Có tội / Cảm thấy có lỗi', 'The jury declared the driver guilty of causing the accident while using his phone.', 'Unit 18: The Law');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1068, 'Harsh', 'adj', 'Khắc nghiệt / Nặng nề (hình phạt)', 'Some legal experts argue that harsh prison sentences do not effectively deter young offenders.', 'Unit 18: The Law');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1069, 'Innocent', 'adj', 'Vô tội / Trong sạch', 'The court finally declared him innocent after decisive new evidence came to light.', 'Unit 18: The Law');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1070, 'Intentional', 'adj', 'Cố ý / Có chủ đích', 'The official report concluded that the property damage was intentional rather than accidental.', 'Unit 18: The Law');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1071, 'Law-abiding', 'adj', 'Tuân thủ pháp luật / Tôn trọng luật pháp', 'Most law-abiding citizens respect community regulations and contribute to a peaceful society.', 'Unit 18: The Law');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1072, 'Non-violent', 'adj', 'Phi bạo lực / Không dùng bạo lực', 'Judges often sentence non-violent offenders to community service rather than long prison terms.', 'Unit 18: The Law');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1073, 'Offensive', 'adj', 'Xúc phạm / Phản cảm', 'Using offensive language during online discussions can result in your account being suspended.', 'Unit 18: The Law');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1074, 'On trial', 'adj', 'Đang bị hầu tòa / Đang bị xét xử', 'The former company director is currently on trial for accepting massive corporate bribes.', 'Unit 18: The Law');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1075, 'Petty (crime)', 'adj', 'Vặt vãnh / Nhỏ (tội phạm nhỏ)', 'Petty crime like shoplifting is common in crowded shopping centers during holiday seasons.', 'Unit 18: The Law');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1076, 'Punishable', 'adj', 'Có thể bị xử phạt / Đáng bị trừng phạt', 'Driving without wearing a safety belt is punishable by a substantial monetary fine.', 'Unit 18: The Law');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1077, 'Random', 'adj', 'Ngẫu nhiên', 'Traffic police officers carry out random alcohol breath tests on drivers every weekend.', 'Unit 18: The Law');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1078, 'Strict', 'adj', 'Nghiêm ngặt / Khắt khe', 'The government should enforce strict environmental regulations to reduce industrial pollution.', 'Unit 18: The Law');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1079, 'Unintentional', 'adj', 'Vô ý / Không cố ý', 'Many car accidents are unintentional and occur because drivers are tired or distracted.', 'Unit 18: The Law');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1080, 'Victimless', 'adj', 'Không có nạn nhân', 'Some people believe that illegal downloading is a victimless crime, but artists lose money.', 'Unit 18: The Law');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1081, 'Abide (by)', 'v', 'Tuân theo / Chấp hành', 'All citizens must abide by the law to keep their community safe and peaceful.', 'Unit 18: The Law');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1082, 'Abolish', 'v', 'Bãi bỏ / Hủy bỏ', 'Several countries decided to abolish the death penalty and replace it with life imprisonment.', 'Unit 18: The Law');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1083, 'Combat', 'v', 'Đấu tranh chống lại / Ngăn chặn', 'The government is trying to combat crime by installing more security cameras in public areas.', 'Unit 18: The Law');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1084, 'Deter', 'v', 'Răn đe / Ngăn chặn', 'Heavy fines can deter drivers from speeding and help reduce serious road accidents.', 'Unit 18: The Law');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1085, 'Enforce', 'v', 'Thực thi / Bắt buộc tuân thủ', 'The local police strictly enforce traffic laws to protect pedestrians and reduce road accidents.', 'Unit 18: The Law');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1086, 'Imprison', 'v', 'Bỏ tù / Tống giam', 'The court decided to imprison the criminal for five years for violent robbery.', 'Unit 18: The Law');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1087, 'Monitor', 'v', 'Giám sát / Theo dõi', 'Parents should monitor how much time their children spend on social media every day.', 'Unit 18: The Law');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1088, 'Obey', 'v', 'Tuân theo / Nghe lời', 'Young drivers must learn to obey traffic regulations to prevent dangerous accidents on roads.', 'Unit 18: The Law');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1089, 'Offend', 'v', 'Phạm tội / Vi phạm pháp luật / Làm xúc phạm', 'Many teenagers who offend for the first time receive community service instead of prison.', 'Unit 18: The Law');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1090, 'Perpetrate', 'v', 'Phạm (tội) / Gây ra (hành vi xấu)', 'Criminals who perpetrate violent crimes against innocent citizens deserve to receive harsh punishments.', 'Unit 18: The Law');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1091, 'Prevent', 'v', 'Ngăn chặn / Ngăn ngừa', 'Good education and stable jobs can help prevent young people from committing crimes.', 'Unit 18: The Law');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1092, 'Protect', 'v', 'Bảo vệ / Che chở', 'The primary duty of police officers is to protect citizens from dangerous criminals.', 'Unit 18: The Law');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1093, 'Prove', 'v', 'Chứng minh / Chứng tỏ', 'The prosecutor could not prove that the suspect was present at the crime scene.', 'Unit 18: The Law');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1094, 'Punish', 'v', 'Trừng phạt / Xử phạt', 'Schools should punish students who bully others to create a safe learning environment.', 'Unit 18: The Law');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1095, 'Resent', 'v', 'Bực bội / Phẫn uất / Không bằng lòng', 'Many citizens resent paying higher taxes when public services do not improve significantly.', 'Unit 18: The Law');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1096, 'Respect', 'v', 'Tôn trọng / Kính trọng / Tuân thủ', 'Everyone must respect the law and treat other members of the community fairly.', 'Unit 18: The Law');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1097, 'Violate', 'v', 'Vi phạm / Xâm phạm', 'Companies that violate environmental regulations should be forced to pay heavy financial penalties.', 'Unit 18: The Law');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1098, 'Accept the consequences', 'v', 'Chấp nhận hậu quả', 'If teenagers break school rules, they must accept the consequences of their bad actions.', 'Unit 18: The Law');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1099, 'Commit a crime', 'v', 'Phạm tội', 'People who commit a crime should be given a chance to reform their lives.', 'Unit 18: The Law');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1100, 'Convict a criminal', 'v', 'Kết án phạm nhân / Kết tội kẻ phạm tội', 'The court needs clear and convincing evidence before it can convict a criminal.', 'Unit 18: The Law');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1101, 'Impose a fine', 'v', 'Phạt tiền / Áp dụng mức phạt tiền', 'The traffic police will impose a fine on anyone who drives through a red light.', 'Unit 18: The Law');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1102, 'Pass a law', 'v', 'Thông qua một đạo luật / Ban hành luật', 'The government should pass a law to ban single-use plastic bags in all supermarkets.', 'Unit 18: The Law');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1103, 'Solve a crime', 'v', 'Phá án / Giải quyết vụ án', 'Police detectives used modern camera footage and fingerprints to solve a difficult crime.', 'Unit 18: The Law');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1104, 'Access', 'n', 'Quyền truy cập / Sự tiếp cận', 'Students living in remote areas need free internet access to complete their online homework.', 'Unit 19: The Media');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1105, 'Attitude', 'n', 'Thái độ / Quan điểm', 'Having a positive attitude towards learning can help university students achieve academic success.', 'Unit 19: The Media');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1106, 'Author', 'n', 'Tác giả / Nhà văn', 'The author wrote an inspiring book about how modern technology changes our daily lifestyle.', 'Unit 19: The Media');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1107, 'Bias', 'n', 'Sự thiên vị / Thành kiến', 'Reporters must avoid political bias and present facts fairly to all their readers.', 'Unit 19: The Media');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1108, 'Censorship', 'n', 'Sự kiểm duyệt', 'Strict government censorship can sometimes prevent journalists from reporting truthful news about society.', 'Unit 19: The Media');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1109, 'Challenge', 'n', 'Thử thách / Thách thức', 'Finding a balance between work and family life is a major challenge for working parents.', 'Unit 19: The Media');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1110, 'Credibility', 'n', 'Độ tin cậy / Sự tín nhiệm', 'Publishing fake news damages the credibility of newspapers and makes readers lose their trust.', 'Unit 19: The Media');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1111, 'Current affairs', 'n', 'Thời sự / Các vấn đề hiện nay', 'Watching current affairs programmes helps young people stay informed about global economic issues.', 'Unit 19: The Media');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1112, 'Editor', 'n', 'Biên tập viên / Chủ bút', 'The newspaper editor checks every article carefully to ensure all facts are completely accurate.', 'Unit 19: The Media');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1113, 'Exposé', 'n', 'Bài phóng sự điều tra / Phóng sự phơi bày sự thật', 'The journalist published an exposé revealing how the factory secretly dumped toxic chemicals into rivers.', 'Unit 19: The Media');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1114, 'Exposure', 'n', 'Sự tiếp xúc / Sự phơi bày', 'Early exposure to foreign languages helps young children develop their communication skills faster.', 'Unit 19: The Media');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1115, 'Fame', 'n', 'Danh tiếng / Tiếng tăm', 'Many young singers seek international fame without realizing how stressful public life can be.', 'Unit 19: The Media');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1116, 'Free press', 'n', 'Báo chí tự do', 'A free press is essential in a democratic society to hold powerful leaders accountable.', 'Unit 19: The Media');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1117, 'Ideology', 'n', 'Hệ tư tưởng', 'The political party promotes an economic ideology that emphasizes free trade and private investment.', 'Unit 19: The Media');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1118, 'Influence', 'n', 'Sự ảnh hưởng / Tác động', 'Social media has a powerful influence on the shopping habits of young consumers today.', 'Unit 19: The Media');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1119, 'The Internet', 'n', 'Mạng Internet', 'The Internet allows university students to access valuable academic research materials from anywhere.', 'Unit 19: The Media');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1120, 'Investigation', 'n', 'Cuộc điều tra / Sự điều tra', 'The police launched an official investigation into the recent bank robbery downtown.', 'Unit 19: The Media');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1121, 'Issue', 'n', 'Vấn đề / Số báo', 'Air pollution has become an urgent environmental issue in many large modern cities.', 'Unit 19: The Media');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1122, 'Journal', 'n', 'Tạp chí chuyên ngành / Nhật ký', 'She published her medical research findings in a respected international science journal.', 'Unit 19: The Media');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1123, 'Journalism', 'n', 'Nghề làm báo / Báo chí', 'Honest and objective journalism plays a vital role in keeping citizens well informed.', 'Unit 19: The Media');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1124, 'Mass media', 'n', 'Truyền thông đại chúng', 'The mass media has a strong influence on public opinions regarding environmental protection.', 'Unit 19: The Media');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1125, 'Media', 'n', 'Truyền thông / Phương tiện truyền thông', 'Traditional media such as newspapers and radio are losing popularity to online platforms.', 'Unit 19: The Media');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1126, 'Network', 'n', 'Mạng lưới / Hệ thống truyền hình', 'The television network broadcasts educational programs for children every weekend morning.', 'Unit 19: The Media');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1127, 'The news', 'n', 'Tin tức / Bản tin', 'Many elderly people still prefer watching the news on television every evening.', 'Unit 19: The Media');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1128, 'Newspaper', 'n', 'Tờ báo / Báo giấy', 'My grandfather likes reading a printed newspaper while having his morning breakfast.', 'Unit 19: The Media');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1129, 'Newsstand', 'n', 'Sạp báo / Quầy báo', 'He bought a travel magazine at the local newsstand before boarding the train.', 'Unit 19: The Media');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1130, 'Opinion', 'n', 'Ý kiến / Quan điểm', 'Students should feel free to express their personal opinion during group classroom discussions.', 'Unit 19: The Media');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1131, 'Paparazzi', 'n', 'Thợ săn ảnh / Tay săn ảnh người nổi tiếng', 'Aggressive paparazzi often follow movie stars and disturb their personal family life.', 'Unit 19: The Media');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1132, 'Press', 'n', 'Báo chí / Giới báo chí', 'The company president held a press conference to introduce their new technological product.', 'Unit 19: The Media');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1133, 'Privacy', 'n', 'Sự riêng tư / Quyền riêng tư', 'Many smartphone users worry about their digital privacy when using social networking applications.', 'Unit 19: The Media');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1134, 'Publication', 'n', 'Ấn phẩm / Sự xuất bản', 'The university releases an academic publication every month to share scientific discoveries.', 'Unit 19: The Media');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1135, 'Publicity', 'n', 'Sự chú ý của công chúng / Sự quảng bá', 'The environmental campaign received widespread publicity after several famous actors supported it.', 'Unit 19: The Media');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1136, 'Publisher', 'n', 'Nhà xuất bản / Người xuất bản', 'The book publisher decided to print ten thousand copies of the new English dictionary.', 'Unit 19: The Media');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1137, 'Relevance', 'n', 'Sự liên quan / Tính thích hợp', 'University courses should have direct relevance to the current demands of the job market.', 'Unit 19: The Media');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1138, 'Safeguard', 'n', 'Biện pháp bảo vệ / Biện pháp an toàn', 'Strong passwords and authentication tools serve as an essential safeguard against cyber attacks.', 'Unit 19: The Media');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1139, 'Source', 'n', 'Nguồn / Nguồn tin', 'Students must cite every information source accurately when writing an academic research paper.', 'Unit 19: The Media');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1140, 'Speculation', 'n', 'Sự suy đoán / Phỏng đoán', 'There was widespread media speculation about which actor would win the major film award.', 'Unit 19: The Media');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1141, 'Tabloid', 'n', 'Báo lá cải / Báo khổ nhỏ', 'Tabloid newspapers often print sensational stories about celebrity relationships to attract readers.', 'Unit 19: The Media');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1142, 'The Web', 'n', 'Mạng internet / Mạng toàn cầu', 'You can find a vast amount of educational resources for free on the Web.', 'Unit 19: The Media');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1143, 'Alternative', 'adj', 'Thay thế / Khác', 'Many governments are investing in alternative energy sources like solar and wind power.', 'Unit 19: The Media');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1144, 'Artificial', 'adj', 'Nhân tạo', 'Parents should limit foods containing artificial colours and sweet chemicals to protect children''s health.', 'Unit 19: The Media');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1145, 'Attention-grabbing', 'adj', 'Thu hút sự chú ý / Bắt mắt', 'Online advertisers create attention-grabbing headlines to persuade internet users to click their links.', 'Unit 19: The Media');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1146, 'Biased', 'adj', 'Thiên vị / Có thành kiến', 'Reading biased news articles can make people form unfair opinions about other cultures.', 'Unit 19: The Media');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1147, 'Celebrity', 'adj', 'Thuộc về người nổi tiếng', 'Young people are heavily influenced by the glamorous celebrity lifestyle shown on television.', 'Unit 19: The Media');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1148, 'Controversial', 'adj', 'Gây tranh cãi', 'Genetically modified food remains a controversial topic among environmental scientists and consumers.', 'Unit 19: The Media');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1149, 'Distorted', 'adj', 'Bị bóp méo / Xuyên tạc / Sai lệch', 'Social media can give people a distorted view of realistic beauty and healthy lifestyles.', 'Unit 19: The Media');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1150, 'Entertaining', 'adj', 'Có tính giải trí / Thú vị', 'The history teacher always prepares entertaining lessons that help students remember facts easily.', 'Unit 19: The Media');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1151, 'Factual', 'adj', 'Dựa trên sự thật / Thực tế', 'Documentaries should present factual information rather than dramatic personal assumptions.', 'Unit 19: The Media');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1152, 'Informative', 'adj', 'Cung cấp nhiều thông tin / Bổ ích', 'The documentary provided an informative overview of climate change and its global effects.', 'Unit 19: The Media');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1153, 'Intrusive', 'adj', 'Xâm phạm riêng tư / Gây phiền toái', 'Pop-up advertisements on mobile screens are often intrusive and annoy online readers.', 'Unit 19: The Media');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1154, 'Investigative', 'adj', 'Thuộc về điều tra', 'The newspaper won a national award for its outstanding investigative reporting on financial corruption.', 'Unit 19: The Media');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1155, 'Mainstream', 'adj', 'Chính thống / Chủ lưu', 'Mainstream media outlets should focus more on pressing social issues rather than celebrity gossip.', 'Unit 19: The Media');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1156, 'Pervasive', 'adj', 'Lan tỏa khắp nơi / Tràn ngập', 'Smartphones have a pervasive influence on modern family life and everyday social communication.', 'Unit 19: The Media');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1157, 'Realistic', 'adj', 'Thực tế / Hiện thực', 'Students need to set realistic study goals to avoid feeling stressed before final exams.', 'Unit 19: The Media');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1158, 'Sensationalist', 'adj', 'Giật gân / Câu khách', 'Many websites use sensationalist headlines just to attract clicks and increase advertising revenue.', 'Unit 19: The Media');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1159, 'Superficial', 'adj', 'Hời hợt / Nông cạn', 'Judging people by their physical appearance alone often leads to superficial relationships.', 'Unit 19: The Media');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1160, 'Unbiased', 'adj', 'Khách quan / Không thiên vị', 'Judges must remain completely unbiased when hearing arguments from both sides in court.', 'Unit 19: The Media');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1161, 'Well-informed', 'adj', 'Hiểu biết rộng / Được cập nhật thông tin tốt', 'Reading reliable news daily helps citizens make well-informed decisions during democratic elections.', 'Unit 19: The Media');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1162, 'Affect', 'v', 'Ảnh hưởng đến / Tác động đến', 'Spending too much time on digital devices can negatively affect a child''s eyesight.', 'Unit 19: The Media');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1163, 'Broadcast', 'v', 'Phát sóng / Truyền phát', 'National television channels broadcast important public health announcements during the viral outbreak.', 'Unit 19: The Media');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1164, 'Censor', 'v', 'Kiểm duyệt', 'The film board decided to censor violent scenes before releasing the movie to teenagers.', 'Unit 19: The Media');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1165, 'Control', 'v', 'Kiểm soát / Khống chế', 'Governments should control online content to protect young children from harmful information.', 'Unit 19: The Media');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1166, 'Exploit', 'v', 'Khai thác / Lợi dụng', 'Some companies exploit young unpaid interns by making them work long overtime hours.', 'Unit 19: The Media');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1167, 'Expose', 'v', 'Vạch trần / Phơi bày', 'Investigative journalists worked hard to expose corporate corruption and financial dishonesty.', 'Unit 19: The Media');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1168, 'Inform', 'v', 'Thông báo / Cung cấp thông tin', 'Teachers should regularly inform parents about their children''s academic progress at school.', 'Unit 19: The Media');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1169, 'Intrude', 'v', 'Xâm phạm / Làm phiền', 'Reporters should not intrude into the private lives of grieving victims after a tragedy.', 'Unit 19: The Media');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1170, 'Invade', 'v', 'Xâm phạm / Xâm lược', 'Paparazzi constantly invade the personal privacy of famous artists to sell scandalous photos.', 'Unit 19: The Media');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1171, 'Investigate', 'v', 'Điều tra / Khảo sát', 'The local police will thoroughly investigate the causes of the serious car collision.', 'Unit 19: The Media');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1172, 'Publicize', 'v', 'Quảng bá / Đưa ra công chúng', 'The university used social media campaigns to publicize its new environmental research program.', 'Unit 19: The Media');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1173, 'Publish', 'v', 'Xuất bản / Đăng tải', 'The scientific magazine will publish her latest study on renewable energy next month.', 'Unit 19: The Media');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1174, 'Report', 'v', 'Báo cáo / Tường thuật / Đưa tin', 'Journalists must verify all facts before they report breaking news to the public.', 'Unit 19: The Media');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1175, 'Review', 'v', 'Đánh giá / Xem xét lại / Ôn tập', 'The educational committee meets every year to review the secondary school English curriculum.', 'Unit 19: The Media');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1176, 'Verify', 'v', 'Xác minh / Kiểm chứng', 'Editors must carefully verify sources of information before publishing an article online.', 'Unit 19: The Media');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1177, 'Actor', 'n', 'Diễn viên / Diễn viên nam', 'The talented actor spent months preparing for his dramatic role in the historical movie.', 'Unit 20: The Arts');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1178, 'Actress', 'n', 'Nữ diễn viên', 'She became a famous actress after winning an international award for her performance.', 'Unit 20: The Arts');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1179, 'Aesthetics', 'n', 'Tính thẩm mỹ / Mỹ học', 'Modern architecture focuses not only on function but also on the aesthetics of the building.', 'Unit 20: The Arts');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1180, 'Appreciation', 'n', 'Sự đánh giá cao / Sự cảm thụ / Sự trân trọng', 'Art classes help young children develop an appreciation of different painting styles.', 'Unit 20: The Arts');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1181, 'Artefact', 'n', 'Hiện vật / Cổ vật', 'The local museum displays an ancient artefact that was discovered by local farmers.', 'Unit 20: The Arts');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1182, 'Artist', 'n', 'Nghệ sĩ / Họa sĩ', 'The young artist used bright colours to show the beauty of the countryside.', 'Unit 20: The Arts');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1183, 'Atmosphere', 'n', 'Bầu không khí', 'Soft music and warm lighting created a relaxing atmosphere in the new restaurant.', 'Unit 20: The Arts');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1184, 'Audience', 'n', 'Khán giả / Thính giả', 'The audience clapped enthusiastically at the end of the school musical performance.', 'Unit 20: The Arts');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1185, 'Ballerina', 'n', 'Nữ diễn viên múa ba lê / Nữ vũ công ba lê', 'She trained for over ten years to become a professional ballerina in the national theatre.', 'Unit 20: The Arts');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1186, 'Ballet', 'n', 'Múa ba lê / Môn ba lê', 'Watching ballet helps many people appreciate the beauty and discipline of dance.', 'Unit 20: The Arts');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1187, 'Carving', 'n', 'Tác phẩm chạm khắc / Nghệ thuật điêu khắc', 'The traditional wooden carving attracted many tourists visiting the craft village.', 'Unit 20: The Arts');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1188, 'Conception', 'n', 'Quan niệm / Khái niệm / Ý niệm', 'His original conception of the art project changed after he visited the local community.', 'Unit 20: The Arts');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1189, 'Concert', 'n', 'Buổi hòa nhạc / Buổi biểu diễn âm nhạc', 'Thousands of teenagers attended the live concert in the city stadium last night.', 'Unit 20: The Arts');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1190, 'Crafts', 'n', 'Đồ thủ công / Nghề thủ công', 'Selling traditional crafts helps local people earn a stable income from tourism.', 'Unit 20: The Arts');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1191, 'Creation', 'n', 'Sự sáng tạo / Tác phẩm sáng tạo', 'Each painting is a unique creation that reflects the personal emotions of the artist.', 'Unit 20: The Arts');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1192, 'Culture', 'n', 'Văn hóa', 'Travelling abroad allows young people to learn about a completely different culture.', 'Unit 20: The Arts');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1193, 'Emotion', 'n', 'Cảm xúc', 'Music is a powerful medium that can express deep emotion without any words.', 'Unit 20: The Arts');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1194, 'Exhibition', 'n', 'Triển lãm / Cuộc triển lãm', 'Our teacher took us to an interesting art exhibition at the city gallery.', 'Unit 20: The Arts');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1195, 'Expression', 'n', 'Sự biểu lộ / Sự thể hiện / Biểu cảm', 'Painting provides people with a creative form of self-expression to reduce daily stress.', 'Unit 20: The Arts');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1196, 'Festival', 'n', 'Lễ hội', 'The annual film festival attracts famous directors and movie fans from around the world.', 'Unit 20: The Arts');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1197, 'Gallery', 'n', 'Phòng trưng bày nghệ thuật / Triển lãm nghệ thuật', 'Many art lovers visit the national gallery every weekend to admire classical paintings.', 'Unit 20: The Arts');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1198, 'Image', 'n', 'Hình ảnh', 'The digital image on the screen showed a peaceful sunset over the mountains.', 'Unit 20: The Arts');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1199, 'Imagination', 'n', 'Trí tưởng tượng', 'Reading books helps children develop their imagination and improves their language skills.', 'Unit 20: The Arts');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1200, 'Influence', 'n', 'Sự ảnh hưởng / Tầm ảnh hưởng', 'Parents have a strong influence on the musical tastes and hobbies of their children.', 'Unit 20: The Arts');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1201, 'Inspiration', 'n', 'Nguồn cảm hứng / Cảm hứng', 'Nature is a great source of inspiration for many poets and landscape painters.', 'Unit 20: The Arts');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1202, 'Intimacy', 'n', 'Sự thân mật / Sự gần gũi', 'The small theatre created a sense of intimacy between the actors and the audience.', 'Unit 20: The Arts');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1203, 'Literature', 'n', 'Văn học', 'Studying classical literature helps students understand human history and moral values.', 'Unit 20: The Arts');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1204, 'Mood', 'n', 'Tâm trạng', 'Listening to upbeat music can quickly improve your mood when you feel tired.', 'Unit 20: The Arts');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1205, 'Musician', 'n', 'Nhạc sĩ / Người biểu diễn âm nhạc', 'The street musician played his guitar skillfully and attracted a large crowd of listeners.', 'Unit 20: The Arts');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1206, 'Opera', 'n', 'Nhạc kịch opera / Vở opera', 'She booked two front-row tickets to watch a famous Italian opera this weekend.', 'Unit 20: The Arts');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1207, 'Orchestra', 'n', 'Dàn nhạc giao hưởng / Dàn nhạc', 'The symphony orchestra performed classical pieces written by Beethoven and Mozart.', 'Unit 20: The Arts');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1208, 'Painting', 'n', 'Bức tranh / Bức họa', 'This famous oil painting depicts a quiet rural village during the nineteenth century.', 'Unit 20: The Arts');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1209, 'Performance', 'n', 'Buổi biểu diễn / Màn trình diễn', 'Their musical performance received enthusiastic applause from both the teachers and students.', 'Unit 20: The Arts');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1210, 'The performing arts', 'n', 'Nghệ thuật biểu diễn', 'Schools should encourage students to participate in the performing arts like dance and drama.', 'Unit 20: The Arts');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1211, 'Play', 'n', 'Vở kịch', 'Our class went to the local theatre to watch a classic Shakespeare play.', 'Unit 20: The Arts');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1212, 'Portrait', 'n', 'Bức chân dung / Tranh chân dung', 'The artist painted a realistic portrait of the elderly woman sitting by the window.', 'Unit 20: The Arts');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1213, 'Proportion', 'n', 'Tỷ lệ / Sự cân đối', 'Art students must learn how to draw the correct proportion of the human body.', 'Unit 20: The Arts');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1214, 'Reflection', 'n', 'Hình ảnh phản chiếu / Sự suy ngẫm', 'Her latest sculpture is a clear reflection of modern societal challenges.', 'Unit 20: The Arts');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1215, 'Response', 'n', 'Phản hồi / Sự hưởng ứng / Câu trả lời', 'The new public art installation received an overwhelmingly positive response from local residents.', 'Unit 20: The Arts');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1216, 'Sculptor', 'n', 'Nhà điêu khắc', 'The talented sculptor carved a magnificent statue out of a single block of marble.', 'Unit 20: The Arts');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1217, 'Sculpture', 'n', 'Bức điêu khắc / Nghệ thuật điêu khắc', 'The modern sculpture in the city square attracts many tourists every afternoon.', 'Unit 20: The Arts');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1218, 'Stimulus', 'n', 'Yếu tố kích thích / Nguồn khích lệ', 'Creative activities at school provide an intellectual stimulus for curious young minds.', 'Unit 20: The Arts');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1219, 'Style', 'n', 'Phong cách', 'The young painter developed her own unique style after studying traditional landscape art.', 'Unit 20: The Arts');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1220, 'Taste', 'n', 'Thị hiếu / Gu thẩm mỹ / Khẩu vị', 'People have different taste in music, ranging from classical symphonies to modern pop.', 'Unit 20: The Arts');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1221, 'Theatre', 'n', 'Nhà hát / Kịch nghệ', 'Going to the theatre allows people to experience live drama and cultural stories directly.', 'Unit 20: The Arts');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1222, 'Theme', 'n', 'Chủ đề', 'Love and family are common themes explored in classical literature around the world.', 'Unit 20: The Arts');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1223, 'Venue', 'n', 'Địa điểm tổ chức / Địa điểm biểu diễn', 'The concert hall was chosen as the main venue for the international music competition.', 'Unit 20: The Arts');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1224, 'Works', 'n', 'Các tác phẩm / Tác phẩm', 'The exhibition features the early works of several influential twentieth-century artists.', 'Unit 20: The Arts');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1225, 'Writer', 'n', 'Nhà văn / Tác giả', 'The famous writer published a new novel that immediately topped the bestseller list.', 'Unit 20: The Arts');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1226, 'Abstract', 'adj', 'Trừu tượng', 'Many beginners find abstract paintings difficult to understand without an explanation from the artist.', 'Unit 20: The Arts');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1227, 'Accomplished', 'adj', 'Tài hoa / Điêu luyện / Xuất sắc', 'She is an accomplished pianist who has performed with prestigious orchestras worldwide.', 'Unit 20: The Arts');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1228, 'Aesthetic', 'adj', 'Thuộc về thẩm mỹ / Có tính thẩm mỹ', 'The historical city centre has great aesthetic value because of its preserved architecture.', 'Unit 20: The Arts');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1229, 'Burgeoning', 'adj', 'Đang phát triển nhanh / Đang nở rộ', 'The city has a burgeoning art scene with many independent studios opening recently.', 'Unit 20: The Arts');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1230, 'Classical', 'adj', 'Cổ điển', 'Learning classical music at an early age helps children develop concentration and patience.', 'Unit 20: The Arts');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1231, 'Creative', 'adj', 'Sáng tạo', 'Doing creative activities such as painting or writing can effectively relieve work stress.', 'Unit 20: The Arts');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1232, 'Cultural', 'adj', 'Thuộc về văn hóa', 'Visiting museums is an excellent way to experience the cultural heritage of a country.', 'Unit 20: The Arts');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1233, 'Distracting', 'adj', 'Gây mất tập trung / Làm xao nhãng', 'Loud background music can be very distracting when students are preparing for exams.', 'Unit 20: The Arts');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1234, 'Eclectic', 'adj', 'Đa dạng / Phong phú / Chiết trung', 'Her home is decorated with an eclectic mix of modern and vintage art pieces.', 'Unit 20: The Arts');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1235, 'Electric', 'adj', 'Sôi động, đầy hào hứng / Thuộc về điện', 'The atmosphere inside the crowded concert hall was electric as the band took the stage.', 'Unit 20: The Arts');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1236, 'Emotional', 'adj', 'Xúc động / Giàu cảm xúc', 'The emotional performance of the main singer brought tears to the eyes of the audience.', 'Unit 20: The Arts');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1237, 'Fundamental', 'adj', 'Cơ bản / Thiết yếu / Cốt lõi', 'Drawing is a fundamental skill that every beginner must learn in art class.', 'Unit 20: The Arts');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1238, 'Imaginative', 'adj', 'Giàu trí tưởng tượng / Sáng tạo', 'Children often write imaginative stories full of magical creatures and exciting adventures.', 'Unit 20: The Arts');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1239, 'Influential', 'adj', 'Có ảnh hưởng lớn', 'The teacher remained an influential figure throughout my entire high school education.', 'Unit 20: The Arts');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1240, 'Inspirational', 'adj', 'Truyền cảm hứng', 'His speech about pursuing dreams was deeply inspirational for all the graduating students.', 'Unit 20: The Arts');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1241, 'Interactive', 'adj', 'Tương tác / Mang tính tương tác', 'The modern science museum uses interactive exhibits to make learning fun for young visitors.', 'Unit 20: The Arts');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1242, 'Literary', 'adj', 'Thuộc về văn học', 'She joined a local literary club to discuss classic novels with fellow book lovers.', 'Unit 20: The Arts');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1243, 'Live', 'adj', 'Trực tiếp / Sống', 'Attending a live performance offers a much more exciting experience than watching online videos.', 'Unit 20: The Arts');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1244, 'Magical', 'adj', 'Kỳ diệu / Mê hoặc / Huyền diệu', 'The lighting and music created a truly magical feeling inside the historic theatre.', 'Unit 20: The Arts');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1245, 'Monotonous', 'adj', 'Đơn điệu / Tẻ nhạt', 'Doing repetitive office tasks all day long can feel extremely monotonous and tiring.', 'Unit 20: The Arts');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1246, 'Mundane', 'adj', 'Bình thường / Thường nhật / Tẻ nhạt', 'Some contemporary artists find inspiration in mundane daily objects like chairs and bottles.', 'Unit 20: The Arts');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1247, 'Passionate', 'adj', 'Đam mê / Nhiệt huyết', 'She is passionate about traditional music and practices playing the piano every evening.', 'Unit 20: The Arts');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1248, 'Popular', 'adj', 'Phổ biến / Được ưa chuộng', 'Pop music has become very popular among teenagers in almost every country.', 'Unit 20: The Arts');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1249, 'Prominent', 'adj', 'Nổi bật / Xuất chúng', 'The gallery is currently displaying works by several prominent artists from around the world.', 'Unit 20: The Arts');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1250, 'Relaxing', 'adj', 'Thư giãn / Mang lại cảm giác thư thái', 'Listening to soft classical music in the evening provides a relaxing way to unwind.', 'Unit 20: The Arts');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1251, 'Stimulating', 'adj', 'Kích thích / Thú vị / Hứng khởi', 'Art workshops offer a stimulating environment where children can freely explore new ideas.', 'Unit 20: The Arts');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1252, 'Visual', 'adj', 'Thuộc về thị giác / Trực quan', 'Teachers often use visual aids like pictures and videos to explain difficult lessons.', 'Unit 20: The Arts');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1253, 'Vivid', 'adj', 'Sống động / Rực rỡ', 'The painter used vivid colours to bring the busy street market scene to life.', 'Unit 20: The Arts');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1254, 'Choreograph', 'v', 'Biên đạo múa', 'She was invited to choreograph a modern dance routine for the annual cultural festival.', 'Unit 20: The Arts');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1255, 'Create', 'v', 'Tạo ra / Sáng tạo', 'Artists use different materials to create meaningful sculptures that reflect human feelings.', 'Unit 20: The Arts');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1256, 'Depict', 'v', 'Miêu tả / Khắc họa', 'The murals in the historic temple depict daily life during the ancient dynasties.', 'Unit 20: The Arts');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1257, 'Enrich', 'v', 'Làm phong phú / Làm giàu thêm', 'Reading books and visiting art exhibitions can greatly enrich our knowledge and imagination.', 'Unit 20: The Arts');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1258, 'Escape', 'v', 'Thoát khỏi / Trốn tránh', 'Many people listen to music or read novels to escape from daily stress.', 'Unit 20: The Arts');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1259, 'Imagine', 'v', 'Tưởng tượng / Hình dung', 'It is hard to imagine modern daily life without smartphones and internet access.', 'Unit 20: The Arts');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1260, 'Influence', 'v', 'Ảnh hưởng đến / Tác động đến', 'Celebrities and social media can strongly influence the fashion choices of young people.', 'Unit 20: The Arts');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1261, 'Inspire', 'v', 'Truyền cảm hứng', 'Dedicated teachers can inspire students to work hard and reach their full potential.', 'Unit 20: The Arts');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1262, 'Participate', 'v', 'Tham gia', 'Students are encouraged to participate actively in extracurricular activities like drama and sports.', 'Unit 20: The Arts');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1263, 'Perform', 'v', 'Biểu diễn / Trình diễn', 'The school choir will perform traditional folk songs at the upcoming community festival.', 'Unit 20: The Arts');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1264, 'Provoke', 'v', 'Kích thích / Gợi lên / Gây ra', 'The thought-provoking painting was intended to provoke deep public debate about environmental pollution.', 'Unit 20: The Arts');
INSERT OR IGNORE INTO words (id, word, type, meaning, example, library) VALUES (1265, 'Transcend', 'v', 'Vượt qua (giới hạn)', 'Great works of art can transcend cultural boundaries and bring diverse communities together.', 'Unit 20: The Arts');
COMMIT;
